E["npc:advisor-sunsworn"] = {t="npc",n="Advisor Sunsworn",z="orgrimmar",s="Advisor Sunsworn is an enigmatic blood elf envoy stationed at Splintertree Post in the dense woodlands of Ashenvale. Standing among the crude timber fortifications of the Horde outpost, he serves as an observer and advisor in an otherwise strictly orc-dominated territory.",h="Advisor Sunsworn is an enigmatic blood elf envoy stationed at Splintertree Post in the dense woodlands of...",sec={{t="A Blood Elf in Ashenvale",b="Amid the rugged palisades and spiked barricades of Splintertree Post, Advisor Sunsworn cuts an unusual figure. Blood elves are rarely seen deep within the ancient forests of Kalimdor, far from the Eastern Kingdoms. Stationed near one of the post's western huts, Sunsworn keeps a quiet vigil over Horde operations in Ashenvale, receiving couriers sent to bolster Splintertree's defenses and lending counsel in a region fraught with night elven resistance.",sp=0}},faq={{q="Who is Advisor Sunsworn?",a="Advisor Sunsworn is a blood elf stationed at Splintertree Post in Ashenvale. Rather than an active frontline commander, he acts as an emissary and advisor observing Horde frontier efforts.",al={"who is sunsworn","sunsworn npc","advisor sunsworn lore"}},{q="Where can I find Advisor Sunsworn?",a="He is located in the western portion of Splintertree Post in central Ashenvale, standing just outside one of the timber huts.",al={"sunsworn location","where is advisor sunsworn","sunsworn splintertree"}},{q="What is a blood elf doing at Splintertree Post?",a="While most forces in Ashenvale are orcs and their close allies, blood elf envoys occasionally travel to distant Horde military outposts to coordinate diplomatic matters, observe regional threats, and receive dispatches from allied commanders.",al={"why is a blood elf in ashenvale","blood elf at splintertree"}},{q="Does Advisor Sunsworn offer any tasks?",a="He serves as a point of contact for messengers dispatched to the region, receiving reports from those directed to reinforce Splintertree Post.",al={"sunsworn quests","report to splintertree post"}}},ang={["faction:Horde"]="Splintertree Post is a vital foothold against the night elves in Ashenvale, and envoys like Sunsworn help maintain communication and coordination across the Horde's far-flung outposts."},kw={"advisor sunsworn","ashenvale","blood elf","splintertree post","sunsworn"},rel={"subzone:splintertree-post","zone:ashenvale"},src={"Advisor Sunsworn"}}
E["npc:aelthalyste"] = {t="npc",n="Aelthalyste",z="orgrimmar",s="Aelthalyste is a banshee priest trainer and prominent figure within the Cult of Forgotten Shadows, stationed in the War Quarter of the Undercity. She oversees the spiritual discipline of Forsaken acolytes, teaching them to wield the dark energies of Shadow. She also coordinates with other Horde faith leaders, directing troll acolytes to their own elders in Orgrimmar.",h="Aelthalyste is a banshee priest trainer and prominent figure within the Cult of Forgotten Shadows, stationed...",sec={{t="Voice of the Forgotten Shadow",b="Unlike many priests across Azeroth who revere the Holy Light, Aelthalyste guides the Forsaken through the tenets of the Cult of Forgotten Shadows. Rising as an incorporeal banshee, she embodies the spectral agony and relentless resolve of Sylvanas Windrunner's followers. From her chamber in the Undercity's War Quarter, she calls aspiring priests back from distant outposts to master the darker arts of their discipline, teaching them to harness suffering as a lethal weapon.",sp=0},{t="Ties with the Horde",b="While her focus remains firmly on her Forsaken flock, Aelthalyste maintains mutual respect with other Horde spiritual practitioners. Recognizing the distinct nature of Darkspear spiritualism, she directs troll initiates away from her own shadow doctrines and sends them across the sea to Ur'kyo in Orgrimmar. This gesture of deference ensures that Horde spellcasters develop within their cultural traditions while cementing alliances between Kalimdor and Lordaeron.",sp=0}},faq={{q="Who is Aelthalyste?",a="Aelthalyste is a banshee priest trainer residing in the War Quarter of the Undercity. She serves as a leading teacher in the Cult of Forgotten Shadows, instructing Forsaken practitioners in Shadow magic.",al={"aelthalyste lore","who is the banshee priest","aelthalyste npc"}},{q="Where can I find Aelthalyste?",a="She is located in the War Quarter beneath the ruins of Capital City in the Undercity, surrounded by fellow Forsaken instructors.",al={"aelthalyste location","where is aelthalyste","find aelthalyste"}},{q="What is the Cult of Forgotten Shadows?",a="The Cult of Forgotten Shadows is the prevailing spiritual philosophy among the Forsaken. Born from the trauma of undeath and abandonment by the Holy Light, its adherents study the balance between Light and Shadow, embracing darkness, willpower, and personal discipline.",al={"forgotten shadows","forsaken priest religion","cult of forgotten shadows"}},{q="Why does Aelthalyste send troll priests to Orgrimmar?",a="Aelthalyste recognizes that the troll relationship with the spirits and shadow differs greatly from Forsaken doctrine. As a sign of respect, she sends troll acolytes to train under Ur'kyo, the Darkspear priest trainer in the Valley of Spirits.",al={"ur'kyo aelthalyste","why send trolls away","aelthalyste troll quest"}},{q="What does Aelthalyste teach?",a="She provides core priest instruction to Forsaken characters and directs advanced acolytes into signature undead rituals, including spells like Touch of Weakness and Devouring Plague.",al={"priest training aelthalyste","what spells does aelthalyste give","aelthalyste abilities"}},{q="Is Aelthalyste loyal to Sylvanas?",a="Yes. As a banshee within the Undercity, she shares the plight of the Highborne spirits bound to Sylvanas Windrunner and works actively to strengthen the Forsaken through the mastery of dark magic.",al={"aelthalyste faction","is she loyal to undercity","banshee loyalty"}}},ang={["class:Priest"]="For Forsaken priests, Aelthalyste represents the core of their doctrine, granting specialized dark spells and guidance in the Cult of Forgotten Shadows.",["race:Undead"]="Aelthalyste reflects the Forsaken transition away from the Holy Light of their former lives toward the pragmatic power of the Shadow.",["race:Troll"]="Rather than forcing troll initiates to adopt Forsaken rites, Aelthalyste directs Darkspear priests back to Ur'kyo in Orgrimmar out of mutual respect.",["faction:Horde"]="Her cooperation with Kalimdor trainers like Ur'kyo demonstrates how religious respect helps bridge cultural gaps across the young Horde coalition."},kw={"aelthalyste","banshee","cult of forgotten shadows","devouring plague","priest","shadow","undercity","ur'kyo","war quarter"},rel={"zone:undercity","subzone:war-quarter","npc:ur-kyo","quest:5644","quest:5643","quest:5654","topic:forsaken","topic:darkspear-tribe"},src={"Aelthalyste"}}
E["npc:ambassador-dawnsinger"] = {t="npc",n="Ambassador Dawnsinger",z="orgrimmar",s="Ambassador Dawnsinger is a blood elf diplomat stationed within Grommash Hold in Orgrimmar. Serving as the representative of Silvermoon City to the Horde, she works to cultivate ties between her people and the warchief's council while directing travelers to assist regional military outposts.",h="Ambassador Dawnsinger is a blood elf diplomat stationed within Grommash Hold in Orgrimmar.",sec={{t="Voice of Silvermoon",b="Standing within the fortified halls of Grommash Hold, Ambassador Dawnsinger serves as the diplomatic bridge between the blood elves of Quel'Thalas and the leadership of the Horde. Her duties involve fostering goodwill, managing official communication with Warchief Thrall's court, and ensuring that blood elf interests are represented in Kalimdor. Rather than remaining entirely passive, she actively involves herself in Horde logistical affairs, coordinating with regional command posts such as Splintertree Post in Ashenvale to support shared strategic interests.",sp=0}},faq={{q="Who is Ambassador Dawnsinger?",a="Ambassador Dawnsinger is an emissary from Silvermoon City stationed inside Grommash Hold in Orgrimmar. She represents the blood elves and maintains diplomatic relations with the Horde leadership.",al={"dawnsinger","who is the blood elf in grommash hold","dawnsinger identity"}},{q="Where can Ambassador Dawnsinger be found?",a="She is located inside Grommash Hold, the central seat of Horde leadership found in the Valley of Strength in Orgrimmar.",al={"dawnsinger location","where is ambassador dawnsinger"}},{q="What is her role in Orgrimmar?",a="Her primary role is maintaining strong political ties between Silvermoon and Orgrimmar. She also assists the Horde's strategic efforts by directing capable adventurers to regional installations, such as Splintertree Post in Ashenvale.",al={"what does dawnsinger do","dawnsinger purpose"}}},ang={["faction:Horde"]="For the Horde, Ambassador Dawnsinger represents vital political ties to Quel'Thalas, ensuring mutual cooperation between the eastern elves and the established forces in Kalimdor."},kw={"ambassador dawnsinger","blood elf","dawnsinger","grommash hold","orgrimmar","silvermoon","splintertree post"},rel={"subzone:grommash-hold","zone:orgrimmar","subzone:splintertree-post","topic:horde"},src={"Ambassador Dawnsinger"}}
E["npc:cazul"] = {t="npc",n="Cazul",z="orgrimmar",s="Cazul is an ancient, blind orc warlock dwelling in the darkened cavern of the Cleft of Shadow beneath Orgrimmar. Despite having lost his physical sight, he possesses profound occult insight and guides rising practitioners of the dark arts seeking to expand their demonic command.",h="Cazul is an ancient, blind orc warlock dwelling in the darkened cavern of the Cleft of Shadow beneath...",sec={{t="Eyes in the Dark",b="Tucked away in the cavernous depths of the Cleft of Shadow, Cazul endures as a relic of old warlock traditions. Though entirely blind, his senses are attuned to the shifting currents of the Twisting Nether and the whispers of demonic entities. Rising warlocks are often directed to him when seeking to expand their mastery and bind more dangerous servitors. His sharp awareness and occult wisdom make it clear that losing his eyes cost him nothing of his arcane power.",sp=0}},faq={{q="Who is Cazul?",a="Cazul is an elderly, blind orc warlock residing in the Cleft of Shadow beneath Orgrimmar. He is known for his deep knowledge of dark sorcery and demonology, serving as an advisor to aspiring warlocks.",al={"who is cazul","cazul lore","blind cazul npc"}},{q="Why is Cazul blind?",a="The exact cause of Cazul's blindness is unrecorded, though it is not uncommon for veteran warlocks to sacrifice physical senses or suffer injury from prolonged communion with fel energy and demonic entities.",al={"why is cazul blind","how did cazul lose his sight"}},{q="What role does Cazul play for warlocks?",a="Cazul plays a crucial role in directing warlocks seeking to advance their craft, particularly those learning to summon and bind a succubus.",al={"cazul quests","what does cazul teach","warlock quest cazul"}}},ang={["class:Warlock"]="Warlocks of the Horde are directed to Cazul in the Cleft of Shadow when seeking guidance on binding deeper powers from the Nether.",["race:Orc"]="Cazul represents the enduring presence of dark magic among the orcs, practicing his crafts away from the watchful eyes of Thrall's honor guard."},kw={"blind cazul","cazul","cleft of shadow","demonology","orgrimmar","voidwalker","warlock"},rel={"subzone:cleft-of-shadow","quest:1508","quest:1472","zone:orgrimmar","subzone:cleft"},src={"Cazul"}}
E["npc:craven-drok"] = {t="npc",n="Craven Drok",z="orgrimmar",s="Craven Drok is a wandering orc found skulking in the dimly lit tunnels of the Cleft of Shadow beneath Orgrimmar. True to his moniker, he keeps to the dark corners of the city, occasionally reaching out to travelers willing to deliver sensitive correspondence concerning the Horde's enemies.",h="Craven Drok is a wandering orc found skulking in the dimly lit tunnels of the Cleft of Shadow beneath...",sec={{t="A Skulker in the Shadows",b="While most orcs of Orgrimmar proudly walk the sunlit avenues of the Valley of Honor or the Valley of Strength, Craven Drok avoids the daylight entirely. He haunts the winding, subterranean paths of the Cleft of Shadow, an enclave typically reserved for warlocks, rogues, and practitioners of less honorable trades. Drok lives up to his cowardly reputation, preferring to stay out of sight while hiring passersby to carry out his discreet errands, including dispatches touching on Alliance activities.",sp=0}},faq={{q="Where can I find Craven Drok?",a="Craven Drok wanders the cavernous underground pathways of the Cleft of Shadow, situated deep beneath the main thoroughfares of Orgrimmar.",al={"craven drok location","where is craven drok","drok orgrimmar loc"}},{q="Why is he called 'Craven'?",a="Orcish culture prizes overt bravery and martial glory above all else. Drok earns his moniker by skulking in dark caverns, keeping his head down, and contracting others to handle tasks he prefers not to deal with personally.",al={"why is he craven","craven drok name","is craven drok a coward"}},{q="What is his involvement with the Alliance?",a="Drok is connected to a dispatch regarding Alliance relations, serving as an intermediary who sends couriers across Horde territory with vital communications regarding enemy factions.",al={"craven drok alliance","alliance relations drok"}},{q="Is Craven Drok related to Captain Drok?",a="While they share the same surname and heritage, any exact familial connection between Craven Drok and Captain Drok remains unconfirmed.",al={"captain drok relative","drok family"}}},ang={["race:Orc"]="Most orcs regard Craven Drok with disdain, as his preference for lurking in the gloomy Cleft of Shadow stands in stark contrast to traditional notions of orcish honor and courage.",["class:Rogue"]="The Cleft of Shadow is the natural gathering place for those who operate outside the spotlight, making contacts like Drok typical of the subterranean underworld beneath the capital."},kw={"alliance relations","captain drok","cleft of shadow","craven drok","orgrimmar"},rel={"subzone:cleft-of-shadow","zone:orgrimmar","quest:1431","topic:alliance"},src={"Craven Drok"}}
E["npc:deino"] = {t="npc",n="Deino",z="orgrimmar",s="Deino is a Darkspear troll mage trainer dwelling within the Valley of Spirits in Orgrimmar. Alongside her fellow practitioners, she teaches emerging arcanists how to master the arcane and harness volatile elemental forces. She also directs seasoned spellcasters across Kalimdor to unravel ancient magical anomalies and seek out reclusive tutors.",h="Deino is a Darkspear troll mage trainer dwelling within the Valley of Spirits in Orgrimmar.",sec={{t="The Valley's Arcanist",b="Standing amidst the totems, huts, and tranquil waters of the Valley of Spirits, Deino offers instruction to Horde mages who find themselves in the orcish capital. Troll spellcasters traditionally walk a fine line between spiritual reverence and pure arcane mastery, and Deino represents this unique path within the Darkspear tribe, standing shoulder to shoulder with fellow instructors Enyo and Pephredo.",sp=0},{t="Unraveling Arcane Mysteries",b="Beyond fundamental spell craft, Deino tasks promising spellcasters with field research far beyond Durotar's red dust. She sends practitioners northward into the corrupted wilds of Ashenvale to gather the tainted Waters of Xavian and recover enchanted hair from the Laughing Sisters. When a student's power outgrows what Orgrimmar can offer, Deino points them toward remote masters, such as the hermit sorceress Tabetha in the swamplands of Dustwallow.",sp=0}},faq={{q="Where can I find Deino?",a="Deino stands on the raised platforms in the Valley of Spirits in southwestern Orgrimmar, grouped alongside fellow troll mage trainers Enyo and Pephredo.",al={"deino location","where is deino","deino orgrimmar"}},{q="What does Deino teach?",a="She trains mages in arcane, fire, and frost spells, portal creation, and essential spell ranks as spellcasters grow in experience.",al={"deino trainer","what spells does deino teach"}},{q="Why does Deino send mages to Xavian?",a="Deino seeks the tainted Waters of Xavian from satyr territory in northern Ashenvale to aid mages in understanding volatile, corrupted magical resonances.",al={"waters of xavian quest","why xavian"}},{q="Who are the trainers standing with Deino?",a="She stands with Enyo and Pephredo. Together, the trio shares the names of the Graeae sisters of ancient myth, serving as the central circle of troll mage mentorship in Orgrimmar.",al={"who is enyo","pephredo","troll mages in valley of spirits"}},{q="Why does Deino send mages to Dustwallow Marsh?",a="When a mage reaches greater proficiency, Deino sends them to Tabetha, a powerful and reclusive human hermit living deep in Dustwallow Marsh who possesses specialized arcane secrets.",al={"deino tabetha","journey to the marsh"}},{q="Can non-trolls train with Deino?",a="Yes. Any Horde mage—whether Undead or Troll—can learn class spells and receive guidance from Deino in the Valley of Spirits.",al={"can orcs train with deino","horde mage training"}}},ang={["class:Mage"]="Deino serves as an essential class trainer in Orgrimmar, offering key talent instruction, portal spells, and specialized quests leading into Ashenvale and Dustwallow Marsh.",["race:Troll"]="Deino exemplifies the Darkspear adaptation to arcane magic, combining classical scholarly wizardry with the cultural environment of the Valley of Spirits.",["faction:Horde"]="Stationed in Orgrimmar's spiritual district, she ensures the Horde's spellcasters maintain formidable arcane power alongside shamans and warlocks."},kw={"deino","laughing sisters","mage trainer","orgrimmar","tabetha","troll mage","valley of spirits","waters of xavian","xavian"},rel={"subzone:valley-of-spirits","zone:orgrimmar","quest:1944","quest:1945","npc:tabetha","subzone:xavian","topic:troll","topic:horde"},src={"Deino"}}
E["npc:dirge-quikcleave"] = {t="npc",n="Dirge Quikcleave",z="orgrimmar",s="Dirge Quikcleave is a goblin culinary master and vendor holding court inside the inn at Gadgetzan. Renowned across Azeroth for his inventive dishes, he trains seasoned chefs seeking to master artisan-level cooking.",h="Dirge Quikcleave is a goblin culinary master and vendor holding court inside the inn at Gadgetzan.",sec={{t="Master of the Cleaver",b="Dirge Quikcleave resides in the dusty desert outpost of Gadgetzan, serving drinks and meats to parched travelers passing through the Tanaris sands. Despite operating out of a frontier tavern, he claims the mantle of the greatest living culinary artist in Azeroth. City cooking trainers across the world direct their most promising students to Dirge when they have exhausted ordinary lessons. His kitchen mastery is known for demanding, unusual ingredients—from giant clam meat and eggs for his Clamlette creations to the exotic beasts of distant shores.",sp=0},{t="Exotic Flavors and Shady Favors",b="Beneath his bravado as a gourmand, Dirge retains the entrepreneurial edge typical of any goblin in the desert. He maintains contacts with eccentric figures throughout Kalimdor and has an eye for dangerous culinary ventures. Those willing to retrieve fierce beast cuts, such as the monstrous chimaeroks native to Feralas's Isle of Dread, find that Dirge can concoct hearty recipes capable of sustaining champions on perilous journeys—provided they do not ask too many questions about his private dealings.",sp=0}},faq={{q="Who is Dirge Quikcleave?",a="Dirge Quikcleave is a master goblin chef and provisioner situated inside the inn in Gadgetzan, Tanaris. He is renowned as one of the finest culinary practitioners in Azeroth, teaching aspiring cooks how to hone their craft into artisan mastery.",al={"dirge quikcleave lore","who is dirge","gadgetzan chef"}},{q="Where can Dirge Quikcleave be found?",a="He is located inside the tavern at the Steamwheedle cartel boomtown of Gadgetzan, in the northern dunes of Tanaris.",al={"dirge location","where is dirge quikcleave","dirge inn"}},{q="Why do cooking trainers send adventurers to him?",a="Capital city cooking trainers can only take an apprentice's skill so far. Once a cook reaches an expert threshold, trainers send them to Dirge in Gadgetzan via the task 'To Gadgetzan You Go!' to prove their worth and unlock artisan-tier cooking.",al={"why visit dirge","artisan cooking quest","to gadgetzan you go"}},{q="What dishes is Dirge famous for?",a="Dirge is celebrated for his Clamlette Surprise, a savory omelet made from giant clam meat and eggs, as well as hearty wolf steaks and his potent Dirge's Kickin' Chimaerok Chops.",al={"dirge recipes","clamlette surprise","what does dirge cook"}}},ang={["profession:Cooking"]="Dirge Quikcleave is the premier artisan instructor for ambitious chefs, testing their skill with his signature clamlette recipes before conferring master status.",["race:Orc"]="Trainers in Orgrimmar point aspiring Horde gourmands straight out into the Tanaris desert to seek Dirge's culinary tutelage."},kw={"artisan cooking","clamlette surprise","cooking trainer","dirge quikcleave","gadgetzan","goblin chef","tanaris"},rel={"quest:6611","subzone:gadgetzan","zone:tanaris","subzone:isle-of-dread","topic:goblin"},src={"Dirge Quikcleave"}}
E["npc:doctor-gregory-victor"] = {t="npc",n="Doctor Gregory Victor",z="orgrimmar",s="Doctor Gregory Victor is a Forsaken surgeon stationed at the Horde outpost of Hammerfall in the Arathi Highlands. Renowned as the premier trauma physician within the Horde, he evaluates aspiring medics seeking to master advanced triage and battlefield first aid. His cold, clinical efficiency keeps frontline warriors stitched together amidst bitter regional conflicts.",h="Doctor Gregory Victor is a Forsaken surgeon stationed at the Horde outpost of Hammerfall in the Arathi...",sec={{t="Surgeon of Hammerfall",b="While many view Forsaken apothecaries with suspicion, Doctor Gregory Victor serves the Horde through practical battlefield surgery rather than blighted alchemy. Stationed deep within the contested Arathi Highlands at Hammerfall, he operates on soldiers battered by Syndicate brigands, Boulderfist ogres, and Alliance forces. His station doubles as the primary proving ground for Horde field medics, demanding ruthless efficiency and prioritizing critical patients under intense pressure.",sp=0}},faq={{q="Who is Doctor Gregory Victor?",a="Doctor Gregory Victor is a Forsaken physician stationed at Hammerfall in the Arathi Highlands. He is the master trauma surgeon for the Horde, responsible for overseeing triage operations and instructing advanced field medics.",al={"doctor victor","gregory victor","who is gregory victor"}},{q="Where can I find Doctor Gregory Victor?",a="He is located inside the stronghold of Hammerfall, situated in northeastern Arathi Highlands.",al={"gregory victor location","where is victor","doctor victor where"}},{q="What role does he play for the Horde?",a="Doctor Victor tests promising field medics in battlefield triage through rigorous examination, teaching them how to stabilize the dying and craft advanced cloth bandages for frontline combat.",al={"what does gregory victor do","gregory victor first aid","horde trauma doctor"}},{q="Who is his Alliance counterpart?",a="Doctor Gustaf VanHowzen, stationed at Theramore Isle in Dustwallow Marsh, oversees advanced trauma and triage training for the Alliance.",al={"alliance equivalent doctor victor","alliance triage doctor"}}},ang={["faction:Horde"]="Doctor Victor provides crucial battlefield medicine in one of the Horde's most precarious outposts, ensuring warriors on the Arathi front return to fighting shape.",["race:Undead"]="Unlike the Royal Apothecary Society's toxic concoctions, Doctor Victor demonstrates the Forsaken's mastery over conventional mortal anatomy and restorative surgery."},kw={"arathi highlands","doctor gregory victor","first aid","gregory victor","hammerfall","horde trauma","surgeon","triage"},rel={"subzone:hammerfall","quest:6623","zone:arathi","npc:doctor-gustaf-vanhowzen","topic:forsaken","topic:horde"},src={"Doctor Gregory Victor"}}
E["npc:doras"] = {t="npc",n="Doras",z="orgrimmar",s="Doras is the Horde's chief Wind Rider Master in Orgrimmar, perched high upon the wooden tower overlooking the Valley of Strength. He oversees the capital's wyverns, dispatching couriers, scouts, and travelers across Kalimdor.",h="Doras is the Horde's chief Wind Rider Master in Orgrimmar, perched high upon the wooden tower overlooking the...",sec={{t="Master of the Skyway",b="Perched on the wooden platform above the Valley of Strength, Doras tends the winged predators known as wind riders or wyverns. Since the Horde settled Durotar, these cunning, leathery-winged beasts have become the backbone of Horde communication and transit across Kalimdor. Doras manages their care, pairing resting mounts with riders and ensuring critical messages and reinforcements reach remote outposts like the Crossroads, Thunder Bluff, and settlements deep in Ashenvale or Dustwallow Marsh.",sp=0}},faq={{q="Where can I find Doras?",a="Doras is stationed atop the flight tower directly overlooking the Valley of Strength in Orgrimmar. Travelers can reach his roost by taking the winding ramps up the central timber structures near the city entrance.",al={"doras location","where is orgrimmar flight master","orgrimmar wyvern master"}},{q="What creatures does Doras train?",a="Doras manages wind riders, also commonly referred to as wyverns. Native to the arid crags and savannas of Kalimdor, these intelligent, venomous winged predators were befriended by the Horde and serve as reliable flying steeds over vast distances.",al={"orgrimmar mounts","what does doras fly","what are wind riders"}},{q="Where can Doras send travelers?",a="From his roost in Orgrimmar, Doras connects travelers to established Horde outposts across central and northern Kalimdor, including the Crossroads in the Barrens, Thunder Bluff in Mulgore, and military camps in Ashenvale and beyond.",al={"doras flight paths","where can i fly from orgrimmar","orgrimmar flight routes"}}},ang={["faction:Horde"]="For any Horde adventurer, Doras provides the primary aerial artery out of the capital, allowing swift travel to allied settlements across Kalimdor."},kw={"doras","flight master","orgrimmar","valley of strength","wind rider master","wyvern"},rel={"zone:orgrimmar","subzone:valley-of-strength","quest:6385","quest:6386","topic:horde","subzone:crossroads","subzone:razor-hill","zone:thunderbluff"},src={"Doras"}}
E["npc:eitrigg"] = {t="npc",n="Eitrigg",z="orgrimmar",s="Eitrigg is a seasoned veteran of the First and Second Wars who stands beside Warchief Thrall as an esteemed advisor in Orgrimmar. Once a high-ranking lieutenant of the Blackrock clan, he became disillusioned with the old demonic Horde and lived in exile until an extraordinary friendship with a human paladin changed his fate. Today, he helps guide the New Horde back to its roots of honor and shamanism.",h="Eitrigg is a seasoned veteran of the First and Second Wars who stands beside Warchief Thrall as an esteemed...",sec={{t="A Veteran of the Old Horde",b="Born on Draenor into the Blackrock clan, Eitrigg was once one of Warchief Blackhand's primary lieutenants alongside Orgrim Doomhammer and Varok Saurfang. When Doomhammer seized leadership of the Horde, Eitrigg remained a trusted officer and oversaw the captured half-orc assassin Garona. Although he initially dismissed her revelations regarding Gul'dan and the demonic corruption of the Shadow Council, the horrific battles and ultimate defeat of the Horde in the Second War forced him to confront the dark reality. Sickened by the realization of how his people had been manipulated, Eitrigg walked away from the scattered remnants and retreated into self-imposed exile, seeking only solitude in the wilds of Lordaeron.",sp=0},{t="Blood and Honor",b="Years into his wilderness exile, Eitrigg was discovered sheltering in an abandoned tower near Hearthglen by the human paladin Tirion Fordring. Their initial clash collapsed the ruins, but instead of finishing the unconscious human, Eitrigg pulled him from the rubble to safety. Moved by this display of pure martial honor, Tirion swore an oath of friendship and refused to betray the hermit's location. When the local Alliance authorities ultimately captured Eitrigg and sentenced him to hang in Stratholme, Tirion threw away his own knighthood, lands, and freedom in an attack to rescue the condemned orc. This legendary bond proved to both warriors that honor transcended the bitter hatred between their species.",sp=0},{t="Counselor to the Warchief",b="During Tirion's desperate attempt to free Eitrigg in Stratholme, Thrall's newly united Horde raided the city and extracted the aging warrior. Meeting Thrall convinced Eitrigg that the orcs were throwing off the demonic taint and rediscovering their ancestral shamanic heritage. Returning with Thrall across the Great Sea to Kalimdor, Eitrigg took up a revered post in the Valley of Wisdom within Orgrimmar. He now stands inside Grommash Hold as an advisor to the young Warchief, helping evaluate new recruits and imparting his hard-earned wisdom so that the New Horde never repeats the tragedies of the past.",sp=0}},faq={{q="Who is Eitrigg?",a="Eitrigg is an elderly Blackrock orc warrior who served as a lieutenant under Blackhand and Orgrim Doomhammer during the First and Second Wars. Today, he resides in Grommash Hold in Orgrimmar as a trusted counselor and advisor to Warchief Thrall.",al={"who is eitrigg","eitrigg lore","orc standing by thrall"}},{q="Why does Eitrigg consider a human his brother?",a="While living in exile in Lordaeron, Eitrigg saved the life of the paladin Tirion Fordring during a duel that brought down a stone tower. In return, Tirion defended Eitrigg's location and later fought his own people in Stratholme to prevent Eitrigg's execution, losing his title and lands in the process. Bound by mutual honor, Eitrigg views Tirion as his brother.",al={"eitrigg and tirion","eitrigg human friend","blood and honor"}},{q="What clan does Eitrigg belong to?",a="Eitrigg belongs to the Blackrock clan. He was a high-ranking commander during the old wars, though he abandoned the clan's corrupt remnants after learning the truth of the demonic corruption that guided them.",al={"eitrigg clan","is eitrigg blackrock"}},{q="Why did Eitrigg leave the old Horde?",a="During the Second War, Eitrigg guarded the assassin Garona, who revealed the demon worship and manipulations of Gul'dan and the Shadow Council. Following the Horde's defeat, Eitrigg realized her claims were true and left in disgust, seeking a quiet place to die rather than serve a corrupt war machine.",al={"why did eitrigg leave","eitrigg exile"}},{q="How did Eitrigg end up in Orgrimmar?",a="When Alliance forces captured Eitrigg and prepared to execute him in Stratholme, Thrall and his forces raided the city and freed him. Seeing Thrall's commitment to honor and the rediscovery of shamanism, Eitrigg chose to follow the young Warchief to Kalimdor.",al={"how did eitrigg meet thrall","eitrigg rescued"}},{q="What role does Eitrigg play in Orgrimmar right now?",a="Eitrigg advises Thrall directly within Grommash Hold and assists in testing and evaluating new recruits who swear loyalty to the New Horde.",al={"eitrigg quest","what does eitrigg do"}}},ang={["faction:Horde"]="Eitrigg serves as the living institutional memory of the Horde, standing by Thrall to ensure the mistakes of the demon-tainted past are never repeated.",["class:Warrior"]="Eitrigg represents martial honor preserved through decades of tragedy, having survived two wars through sheer strength and unbroken discipline.",["class:Paladin"]="The story of Eitrigg and Tirion Fordring is renowned among paladins as the ultimate test of duty versus righteous honor.",["race:Orc"]="For the orcs of Durotar, Eitrigg is a revered elder whose Blackrock heritage proves that any orc can embrace honor and redeem their people's legacy."},kw={"blackrock clan","blood and honor","eitrigg","grommash hold","hearthglen","orgrim doomhammer","orgrimmar","stratholme","thrall","tirion fordring"},rel={"npc:thrall","npc:tirion-fordring","topic:blackrock-clan","topic:new-horde","zone:orgrimmar","npc:orgrim-doomhammer","npc:varok-saurfang","subzone:stratholme"},src={"Eitrigg"}}
E["npc:gan-rul-bloodeye"] = {t="npc",n="Gan'rul Bloodeye",z="orgrimmar",s="Gan'rul Bloodeye is a senior orc warlock trainer residing deep within the dark cavern of the Cleft of Shadow in Orgrimmar. Hidden away from the watchful gaze of the city above, he initiates Horde warlocks into darker demonic rites. Under his instruction, initiates learn to bend otherworldly entities like voidwalkers and succubi to their will.",h="Gan'rul Bloodeye is a senior orc warlock trainer residing deep within the dark cavern of the Cleft of Shadow...",sec={{t="A Master in the Shadows",b="While Warchief Thrall tolerates the presence of warlocks in the new Horde, their dark arts are not welcomed in the open sunlight of Durotar. Gan'rul Bloodeye makes his home in the Cleft of Shadow, a subterranean refuge beneath Orgrimmar where shadow weavers, rogues, and fel casters can study unmolested. From this subterranean perch, Gan'rul serves as a primary tutor for rising practitioners of fel magic.",sp=0},{t="Binding the Nether",b="Gan'rul's primary duty is overseeing the dangerous summoning rituals required of ambitious warlocks. Practitioners seeking to bind greater demons—such as the resilient voidwalker or the seductive succubus—must consult Gan'rul to secure ritual components and learn the precise incantations needed to dominate the summoned creature before it consumes its master.",sp=0}},faq={{q="Who is Gan'rul Bloodeye?",a="Gan'rul Bloodeye is an orc warlock trainer stationed in Orgrimmar. He mentors novice and intermediate Horde warlocks, teaching them how to summon and bind demons from the Twisting Nether.",al={"gan'rul bloodeye","who is ganrul","ganrul bloodeye role"}},{q="Where can I find Gan'rul Bloodeye?",a="He is located in the Cleft of Shadow, the subterranean cavern network hidden beneath Orgrimmar. He stands alongside fellow dark practitioners, away from the main thoroughfares of the city.",al={"ganrul location","where is gan'rul bloodeye","where is cleft of shadow trainer"}},{q="Why are warlocks hidden in the Cleft of Shadow?",a="Warchief Thrall and the shamanistic society of the new Horde strongly distrust fel magic and demonic corruption after the orcs' past enslavement. Warlocks are permitted within the Horde strictly for their utility, but their practice is relegated to the shadows to prevent civic unrest.",al={"why in caves","why hide warlocks","cleft of shadow lore"}},{q="What demons does Gan'rul help summon?",a="Gan'rul guides warlocks through the rituals required to summon and subjugate both the voidwalker and the succubus. Completing his tasks proves that the summoner possesses the necessary willpower to control these fiends.",al={"demons ganrul teaches","ganrul demon quests","voidwalker succubus trainer"}},{q="Does Gan'rul have any known family?",a="He shares a surname with Halga Bloodeye, though their precise relationship is not openly documented.",al={"gan'rul relatives","halga bloodeye relative"}},{q="Who is Strahad, whom Gan'rul mentions?",a="Strahad Farsan is an accomplished warlock residing in the Barrens near the Ratchet hills. Gan'rul eventually sends promising students to Strahad for more advanced instruction and greater challenges.",al={"seeking strahad","who is strahad","strahad quest"}}},ang={["class:Warlock"]="For orc, undead, and troll warlocks, Gan'rul is a vital mentor in Kalimdor, providing the knowledge and trials needed to bind voidwalkers and succubi.",["faction:Horde"]="Gan'rul embodies the precarious position of fel magic in Thrall's Horde—utilized for military strength, but confined to the underground recesses of the capital."},kw={"bloodeye","cleft of shadow","gan'rul","orgrimmar","succubus","trainer","voidwalker","warlock"},rel={"subzone:cleft-of-shadow","zone:orgrimmar","quest:1506","quest:1473","quest:1471","quest:1472","quest:1798","npc:carendin-halgar"},src={"Gan'rul Bloodeye"}}
E["npc:great-father-winter"] = {t="npc",n="Great-father Winter",z="orgrimmar",s="Great-father Winter is an elderly orc hired by the Smokywood Pastures merchant company to pose as the legendary holiday figure in Orgrimmar. Stationed near Grommash Hold in the Valley of Strength during the Feast of Winter Veil, he listens to children's wishes while visibly growing weary of commercial holiday cheer. In exchange for holiday gifts and seasonal tasks, he routinely asks passersby for gingerbread cookies and ice cold milk.",h="Great-father Winter is an elderly orc hired by the Smokywood Pastures merchant company to pose as the...",sec={{t="A Hired Myth",b="While ancient lore speaks of Greatfather Winter as a majestic, elemental spirit wandering the land bringing snow and seasonal renewal, the figure sitting in the Valley of Strength is rather more mundane. He is an orc performer on the payroll of Smokywood Pastures, hired specifically to drive commerce, promote company wares, and entertain the youth of the Horde. Critics grumble that this commercial mascot cheapens genuine seasonal traditions, but few can deny the festive buzz he brings to the city streets.",sp=0},{t="Shift Work in the Valley of Strength",b="Stationed right outside Grommash Hold beneath the boughs of decorated evergreens, this stand-in endures an exhausting shift of children clambering onto his lap to state their gift demands. Between corporate plug drops for Smokywood Pastures discounts and half-hearted holiday greetings, his endurance frequently wanes. He openly admits to keeping a bottle of festive spirits stashed in his pack to drown out the noise as soon as his shift finishes, relying heavily on visiting adventurers to deliver snacks to keep him going.",sp=0}},faq={{q="Is this the real Greatfather Winter?",a="No. He is an ordinary orc hired by Smokywood Pastures to dress up, pose as the legendary Winter Veil figure, and hand out holiday promotions in Orgrimmar.",al={"is he real","who is great-father winter","is he an actor"}},{q="Where can I find Great-father Winter in Orgrimmar?",a="He can be found in the Valley of Strength, set up just outside the entrance to Grommash Hold by the Feast of Winter Veil tree and holiday stalls.",al={"great-father winter location","where is great father winter","where to find winter orc"}},{q="What does he do during the Feast of Winter Veil?",a="He entertains holiday-goers, listens to children's gift requests, gives out Smokywood Pastures promotional tasks, and hands out festive presents under the tree once the holiday peaks.",al={"what does he do","great-father winter purpose","winter veil quests"}},{q="Why does he want gingerbread cookies and milk?",a="Enduring loud crowds and back-to-back children on his lap all day leaves him completely drained. He asks adventurers to bring him fresh gingerbread cookies and milk to keep his energy up through the shift.",al={"treats for great father winter","why milk and cookies","gingerbread quest"}},{q="What does he think of his job?",a="He finds the performance tedious and draining. He openly grumbles about eager children, rushes through corporate slogans, and eagerly counts down the minutes until he can drink from a bottle of cheer tucked away in his bag.",al={"does he like his job","great-father winter quotes","is he drunk"}},{q="Does the Alliance have an equivalent figure?",a="Yes. The Alliance has Greatfather Winter, an elderly dwarf employed by Smokywood Pastures who sits near the holiday tree in the Commons of Ironforge.",al={"alliance greatfather","ironforge santa","alliance counterpart"}}},ang={["faction:Horde"]="He serves as the primary seasonal figurehead for the Horde in Orgrimmar, offering festival gifts and tasks on behalf of Smokywood Pastures.",["profession:Cooking"]="Chefs can bake gingerbread cookies using festive holiday recipes and deliver them alongside milk directly to Great-father Winter to restore his spirits.",["race:Orc"]="Though orcs revere seasonal shifts and the elements, seeing one of their own reduced to a costumed mascot peddling vendor discounts tests the patience of traditionalists."},kw={"gingerbread cookies","great-father winter","greatfather winter","orgrimmar","smokywood pastures","valley of strength","winter veil"},rel={"zone:orgrimmar","subzone:valley-of-strength","subzone:grommash-hold","quest:6962","quest:6984","quest:8827","npc:greatfather-winter","topic:horde"},src={"Great-father Winter"}}
E["npc:grunt-dogran"] = {t="npc",n="Grunt Dogran",z="orgrimmar",s="Grunt Dogran is an orc soldier of the Horde held prisoner deep within the quilboar territory of the southern Barrens. Originally assigned to the Crossroads and later Camp Taurajo, his patrol met with disaster during a raid on Agama'gor.",h="Grunt Dogran is an orc soldier of the Horde held prisoner deep within the quilboar territory of the southern...",sec={{t="A Grunt's Duty",b="Following his promotion within the Horde military, Grunt Dogran was dispatched from the Crossroads to reinforce Camp Taurajo. While leading a detachment of grunts into the bristled territory of Agama'gor, his unit clashed fiercely with the Razormane quilboar. Severely injured and crippled during the fray, Dogran could not be carried away by his retreating comrades and was dragged into captivity.",sp=0},{t="An Honorable Fate",b="Though trapped behind enemy lines and crippled by his wounds, Dogran retains the stubborn pride typical of orc warriors. Rather than returning home broken and forcing his mate to care for an invalid, he chose to make a final stand against the quilboar, asking only that a token of his enduring devotion be returned to the one he loves.",sp=1}},faq={{q="Where is Grunt Dogran located?",a="Dogran is held captive in Agama'gor, a dense quilboar encampment situated in the southern Barrens, south of Camp Taurajo.",al={"dogran location","where is dogran","find dogran barrens"}},{q="Why was Dogran captured by the quilboar?",a="While leading a patrol from Camp Taurajo to strike at the quilboar, Dogran suffered crippling injuries during the clash. His comrades could not transport him out in time, leaving him at the mercy of the beasts.",al={"why was dogran captured","how did dogran get caught"}},{q="Why does Dogran refuse to be rescued?",a="Dogran was permanently crippled in battle and refuses to return home as a burden to his mate. In true orc fashion, he prefers dying on his own terms against the quilboar over living out his days as an invalid.",al={"why wont dogran leave","dogran rescue"},sp=1},{q="Who is looking for Dogran?",a="Worry over his disappearance originates back at the Crossroads and Camp Taurajo, where scouts and soldiers piece together the fate of his missing patrol.",al={"who sent me for dogran","dogran quest giver"}}},ang={["race:Orc"]="Dogran exemplifies the traditional orcish ideal that dying in battle holds more honor than surviving as a helpless invalid.",["faction:Horde"]="His capture illustrates the high cost Horde garrisons pay to secure the trade roads and borders across the Barrens against aggressive quilboar tribes."},kw={"agama'gor","barrens","camp taurajo","crossroads","dogran","dorgran","grunt dogran","quilboar"},rel={"quest:1509","quest:1515","quest:1512","subzone:agama-gor","subzone:camp-taurajo","topic:quilboar","zone:barrens","subzone:crossroads"},src={"Grunt Dogran"}}
E["npc:grunth"] = {t="npc",n="Grunth",z="orgrimmar",s="Grunth is an energetic young orc orphan living under the care of the Orgrimmar orphanage in the Drag. During Children's Week, he eagerly accompanies Horde champions on grand journeys across Kalimdor and the Eastern Kingdoms to learn what it means to be a hero.",h="Grunth is an energetic young orc orphan living under the care of the Orgrimmar orphanage in the Drag.",sec={{t="A Curious Child of the Horde",b="Residing in the Drag of Orgrimmar under the watchful gaze of Orphan Matron Battlewail, Grunth represents the next generation of the newly established Horde. Like many young greenskins raised in Durotar's harsh red wastes, he looks upon armored adventurers with wide-eyed awe and an inexhaustible stream of questions—wondering whether armored warriors are truly terrifying, why lightning on water doesn't kill every fish, and whether he will ever see someone fight an actual dragon.",sp=0},{t="Children's Week Journeys",b="When festival season arrives, adventurers blow an Orcish Orphan Whistle to summon Grunth and take him on an expansive tour across the world. His bucket list spans the breadth of the Horde's domain: seeking an audience with High Chieftain Cairne Bloodhoof in Mulgore, venturing deep into the ruins of Lordaeron to see the Banshee Queen Sylvanas Windrunner, and visiting the rugged frontiers where his people fight for their future.",sp=0}},faq={{q="Who is Grunth?",a="Grunth is an orc child residing at the Orgrimmar orphanage in the Drag. He is cared for by Orphan Matron Battlewail and dreams of becoming a legendary hero of the Horde.",al={"grunth npc","orc orphan","orgrimmar orphan"}},{q="Where can Grunth be found?",a="He stays in the Drag in Orgrimmar with the other orphans, but during Children's Week, an adventurer can summon him anywhere using an Orcish Orphan Whistle obtained from Orphan Matron Battlewail.",al={"grunth location","where is grunth","find grunth"}},{q="What places does Grunth want to visit?",a="Grunth yearns to see the greatest icons of the Horde. His requests include visiting High Chieftain Cairne Bloodhoof in Thunder Bluff, touring the Ratchet docks, and traveling all the way to the ruined throne room of Lordaeron to glimpse Lady Sylvanas Windrunner.",al={"grunth quests","what does the orphan want","grunth tour"}},{q="What kind of personality does Grunth have?",a="Grunth is loud, curious, and intensely imaginative. He constantly fires off absurd riddles and childlike inquiries to the adventurers shepherding him, such as asking what 'zug zug' actually means, whether a wingless fly is called a walk, and casually mentioning he shoved a rock up his nose.",al={"grunth quotes","grunth dialogue","what does grunth say"}}},ang={["faction:Horde"]="Mentoring Grunth during Children's Week reminds Horde champions of what their faction strives to protect: a rising generation born into freedom rather than demonic servitude.",["race:Orc"]="Grunth embodies the youth of Durotar, growing up knowing tribal honor and survival rather than the dark lethargy of the internment camps."},kw={"children's week","grunth","orc orphan","orgrimmar","orphan matron battlewail","orphan whistle","the drag"},rel={"npc:orphan-matron-battlewail","subzone:drag","zone:orgrimmar","topic:horde","topic:lordaeron"},src={"Grunth"}}
E["npc:innkeeper-gryshka"] = {t="npc",n="Innkeeper Gryshka",z="orgrimmar",s="Innkeeper Gryshka is an orc host who manages the Broken Tusk inn in Orgrimmar's Valley of Strength. Serving as the primary hospitality contact for travelers arriving through the city gates, she provides hearthstone bindings, food, and drink to visiting Horde adventurers. She maintains close ties with hunters and scouts across Durotar and the Barrens to keep her tavern stocked with choice cuts of meat.",h="Innkeeper Gryshka is an orc host who manages the Broken Tusk inn in Orgrimmar's Valley of Strength.",sec={{t="Hearth of the Valley of Strength",b="Standing behind the counter of the Broken Tusk, Gryshka manages one of the most heavily trafficked inns in the Horde. Located just beyond the main gates of Orgrimmar in the Valley of Strength, her establishment serves as the first point of rest for warriors, messengers, and newly arrived champions seeking shelter under Thrall's banner.",sp=0},{t="A Taste for Fresh Meat",b="Running a bustling tavern in an arid canyon requires steady supply lines. Gryshka maintains a well-known affinity for fresh meat, relying on trusted hunters across the Horde territories to supply her kitchen. Companions such as Zargh in the Crossroads and Grimtak in Durotar routinely ship their finest game cuts back to the Broken Tusk to satisfy her demanding culinary standards.",sp=0}},faq={{q="Who is Innkeeper Gryshka?",a="Innkeeper Gryshka is the orc innkeeper who runs the Broken Tusk tavern inside Orgrimmar's Valley of Strength. She welcomes Horde travelers, sets hearthstone bindings, and sells food and drink to weary adventurers.",al={"who is gryshka","gryshka orgrimmar","innkeeper broken tusk"}},{q="Where can Innkeeper Gryshka be found?",a="She is located inside the Broken Tusk tavern in the Valley of Strength, the first major district you enter after passing through the main southern gates of Orgrimmar.",al={"where is gryshka","broken tusk inn location","valley of strength innkeeper"}},{q="Where does Gryshka get her meat supplies?",a="Gryshka relies on friends and scouts throughout Horde lands to supply her larder, including Zargh stationed at the Crossroads in the Barrens and Grimtak in Durotar, who send her choice game cuts.",al={"gryshka food sources","who supplies the broken tusk","zargh meat delivery"}},{q="What services does Gryshka provide?",a="Gryshka can bind your hearthstone to the Broken Tusk so you can teleport directly to Orgrimmar. She also sells various foods, breads, and drinks to restore health and mana.",al={"can i bind my hearthstone here","broken tusk hearthstone","gryshka vendor items"}},{q="Does Gryshka have any connection to the wind rider roost?",a="Travelers sent on flight errands from the Barrens often deliver packages directly to Gryshka before being directed up to Doras, the wind rider master perched high on the mesa above the city.",al={"doras quest","wind rider master broken tusk","ride to orgrimmar inn"}},{q="What kind of personality does Gryshka have?",a="Gryshka is a practical, hearty orc host who appreciates good meat, direct talk, and keeping her tavern well-stocked and orderly for the steady stream of Horde warriors passing through the capital.",al={"is gryshka friendly","what is gryshka like"}}},ang={["faction:Horde"]="For any Horde traveler arriving in Durotar, Gryshka's inn in the Valley of Strength is often the primary hub to bind hearthstones and re-supply before venturing deeper into Kalimdor.",["profession:Cooking"]="Cooks will appreciate Gryshka's discerning palate, as she goes out of her way to source prime cuts from hunters stationed as far out as the Barrens."},kw={"broken tusk","doras","gryshka","hearthstone","innkeeper","orgrimmar","valley of strength","zargh"},rel={"subzone:broken-tusk","subzone:valley-of-strength","zone:orgrimmar","npc:zargh","npc:doras","quest:6384","quest:6385","topic:horde"},src={"Innkeeper Gryshka"}}
E["npc:kaplak"] = {t="npc",n="Kaplak",z="orgrimmar",s="Kaplak is an orc rogue trainer stationed in Razor Hill in central Durotar. He instructs young orcs and trolls in the arts of stealth, subterfuge, and bladecraft, preparing them for service to the Horde before dispatching them into Orgrimmar.",h="Kaplak is an orc rogue trainer stationed in Razor Hill in central Durotar.",sec={{t="A Mentor in the Shadows",b="Tucked away in the settlement of Razor Hill, Kaplak serves as a foundational instructor for fledgling Horde rogues emerging from the Valley of Trials. Where traditional orc culture glorifies open combat and roaring charges, Kaplak teaches the colder, quieter disciplines necessary for survival: stalking unseen, picking locks, and striking lethal blows from behind. Once his students outgrow his tutelage in the dusty red ravines of Durotar, he directs them north to the capital of Orgrimmar to deepen their craft among senior guild operatives.",sp=0}},faq={{q="Who is Kaplak?",a="Kaplak is an orc rogue trainer stationed in Razor Hill within Durotar. He trains novice orc and troll rogues who have left the Valley of Trials, teaching them early rogue skills before sending them along to higher trainers in Orgrimmar.",al={"who is kaplak","kaplak lore","kaplak razor hill"}},{q="Where can Kaplak be found?",a="Kaplak can be found in Razor Hill, the central settlement of Durotar, typically resting in or around the local barracks area alongside other class trainers.",al={"where is kaplak","kaplak location","find kaplak"}},{q="What quests does Kaplak offer?",a="Kaplak assists rogue adventurers as they progress, directing them toward advanced trainers and assignments such as sending them to seek out Therzok in Orgrimmar.",al={"kaplak quests","quests from kaplak"}}},ang={["class:Rogue"]="For young orc and troll rogues departing the Valley of Trials, Kaplak provides early professional training and directs them to the covert networks operating in Orgrimmar.",["faction:Horde"]="Kaplak quietly ensures that the Horde maintains skilled scouts, spies, and assassins capable of safeguarding Durotar and operating beyond standard battle lines."},kw={"durotar","kaplak","orc","orgrimmar","razor hill","rogue trainer","stealth","therzok"},rel={"subzone:razor-hill","zone:durotar","quest:1859","quest:2380","zone:orgrimmar"},src={"Kaplak"}}
E["npc:kaymard-copperpinch"] = {t="npc",n="Kaymard Copperpinch",z="orgrimmar",s="Kaymard Copperpinch is a goblin merchant representing Smokywood Pastures in Orgrimmar during the Feast of Winter Veil. Stationed in the Valley of Strength, he hawks festive goods and directs travelers toward holiday cheer and missing holiday supplies. His brisk trade brings seasonal merriment—and Goblin commercial enterprise—to the Horde capital.",h="Kaymard Copperpinch is a goblin merchant representing Smokywood Pastures in Orgrimmar during the Feast of...",sec={{t="A Goblin's Winter Veil",b="When the Feast of Winter Veil arrives, Smokywood Pastures sets up shop right in the bustling Valley of Strength in Orgrimmar, fronted by the enterprising Kaymard Copperpinch. While Great-father Winter receives visitors nearby, Kaymard makes sure the season remains profitable. Selling higher-end treats, festive wrapping paper, and holiday necessities, he embodies the goblin view that no grand cultural festival is complete without a lively exchange of coin.",sp=0},{t="Holiday Complications",b="Beyond peddling festive wares, Kaymard often serves as a point of contact for the seasonal mishaps that plague Smokywood Pastures. From stolen shipments of holiday confections to the mysterious disappearance of Metzen the Reindeer, Kaymard eagerly enlists Horde adventurers to sort out trouble in the snow and keep the festival running smoothly.",sp=0}},faq={{q="Who is Kaymard Copperpinch?",a="Kaymard Copperpinch is a goblin merchant affiliated with Smokywood Pastures. During the Feast of Winter Veil, he operates in Orgrimmar's Valley of Strength, selling premium seasonal goods and offering festive tasks to passersby.",al={"who is kaymard","kaymard copperpinch lore","what does kaymard do"}},{q="What is Smokywood Pastures?",a="Smokywood Pastures is a vendor consortium that handles the food, treats, and seasonal merchandise of the Feast of Winter Veil across Azeroth. They supply both the Horde and the Alliance with festival goods while turning a tidy profit.",al={"what is smokywood pastures","who does he work for","smokywood pastures lore"}},{q="Where can I find Kaymard Copperpinch?",a="He can be found standing in the Valley of Strength in Orgrimmar, stationed near the central festival display where Great-father Winter sits during the Feast of Winter Veil.",al={"kaymard location","where is kaymard copperpinch","where is he in orgrimmar"}},{q="Why does he ask adventurers for help during the holidays?",a="Smokywood Pastures frequently runs into logistical disasters during Winter Veil, including stolen holiday sweets and the kidnapping of their prized reindeer, Metzen. Kaymard hires willing adventurers to recover their assets and safeguard the season's profits.",al={"kaymard quests","winter veil treats quest","metzen quest horde"}}},ang={["faction:Horde"]="For the Horde, Kaymard represents the commercial side of Winter Veil in Orgrimmar, balancing traditional winter celebrations with goblin entrepreneurship.",["profession:Cooking"]="Kaymard and his fellow Smokywood Pastures associates provide seasonal recipes and specialty ingredients essential for baking traditional holiday treats."},kw={"copperpinch","goblin","kaymard","metzen","orgrimmar","smokywood pastures","valley of strength","winter veil"},rel={"subzone:valley-of-strength","zone:orgrimmar","npc:great-father-winter","quest:6984","topic:horde"},src={"Kaymard Copperpinch"}}
E["npc:keldran"] = {t="npc",n="Keldran",z="orgrimmar",s="Keldran is an orc operative stationed just north of the Valley of Spirits in Orgrimmar. Dedicated to paving the way for eventual diplomacy with the Alliance, he coordinates covert strikes against demonic remnants to prove the modern Horde has truly forsaken the Burning Legion.",h="Keldran is an orc operative stationed just north of the Valley of Spirits in Orgrimmar.",sec={{t="A Diplomatic Crusade",b="While Thrall governs from the Valley of Wisdom, Keldran works from the city's red rock terraces to solve a lingering diplomatic disaster. The Alliance still views all orcs as bloodthirsty puppets of demonic masters, a reputation cemented during the first wars. Convinced that even Thrall tires of endless conflict, Keldran believes true peace talks can never occur while demon-worshiping cults endure in Kalimdor. Without formal sanction from the Warchief, he takes the initiative upon himself, directing trusted agents toward distant threats to dismantle the demonic stain once and for all.",sp=0},{t="The War in Desolace",b="To build his case to the Alliance, Keldran targets the grim wastes of Desolace. He dispatched Takata Steelblade and Maurin Bonesplitter to spearhead operations against the demonic infestations there, placing special emphasis on wiping out the Burning Blade cultists. By eradicating these demonic practitioners and bringing tangible proof back to Orgrimmar, Keldran hopes to demonstrate unequivocally that the new Horde is as much an enemy of the Legion as the humans and night elves are.",sp=1}},faq={{q="Who is Keldran?",a="Keldran is an orc located north of the Valley of Spirits in Orgrimmar who organizes efforts to purge demonic influence and open a path toward diplomatic relations with the Alliance.",al={"who is keldran","keldran lore","keldran npc"}},{q="Why does Keldran care about relations with the Alliance?",a="Keldran believes that Thrall is growing weary of continuous war with the Alliance. He knows peace talks will remain impossible as long as the Alliance assumes the Horde is still in league with the Burning Legion.",al={"why alliance relations","keldran motives","why does he want peace"}},{q="Is Keldran acting under Thrall's official orders?",a="No. Keldran lacks official authorization from Warchief Thrall for his operation, choosing to act independently to clear the Horde's name and set the groundwork for future peace.",al={"did thrall send keldran","thrall orders keldran","is keldran sanctioned"}},{q="What is Keldran doing in Desolace?",a="He dispatched Takata Steelblade and Maurin Bonesplitter to Desolace to purge the local demonic forces and decisively eradicate the presence of the Burning Blade cult.",al={"desolace operation","why desolace","keldran burning blade"}}},ang={["faction:Horde"]="Keldran represents the forward-thinking segment of the Horde that recognizes the dire need to shed their demonic reputation if they are ever to secure lasting peace on Kalimdor.",["class:Warlock"]="Keldran's covert war against the Burning Blade underscores how severely the Horde's leadership wishes to distance itself from uncontrolled demonic corruption."},kw={"alliance relations","burning blade","desolace","keldran","maurin bonesplitter","orgrimmar","takata steelblade","valley of spirits"},rel={"quest:1431","subzone:valley-of-spirits","zone:orgrimmar","npc:takata-steelblade","npc:maurin-bonesplitter","zone:desolace","npc:thrall","topic:burning-legion"},src={"Keldran"}}
E["npc:nat-pagle"] = {t="npc",n="Nat Pagle",z="orgrimmar",s="Nat Pagle is widely hailed as the most renowned angler in all of Azeroth, despite claiming he only fishes as an excuse to drink heavily. He makes his home on a secluded inlet in Dustwallow Marsh, where he trains elite anglers from both the Alliance and the Horde who manage to prove their patience.",h="Nat Pagle is widely hailed as the most renowned angler in all of Azeroth, despite claiming he only fishes as...",sec={{t="The Master Angler",b="Though his name is synonymous with angling mastery across the known world, Nat Pagle is remarkably casual about his craft. Having cast lines for several decades, he often admits he has no great reverence for the sport itself, famously calling it little more than a convenient excuse to sit back and drink heavily. Despite this gruff nonchalance, Nat understands aquatic life and the art of angling better than anyone alive, even authoring his own guide and licensing fishing gear sought out by professionals.",sp=0},{t="A Marshland Hermit",b="Pagle makes his camp on a small spit of land along the eastern coast of Dustwallow Marsh, far from the bustling taverns of the Eastern Kingdoms. He remains fiercely independent and uninterested in the politics of factions, welcoming Alliance travelers sent by trainers like Grimnur Stonebrand as well as Horde aspirants directed to him by Lumak in Orgrimmar. For Nat, anyone willing to scour the corners of the world for rare specimens deserves a lesson in genuine angling.",sp=0},{t="Old Tales and Sea Monsters",b="Before settling in Kalimdor, Nat spent his earlier years fishing the docks of Southshore in the Hillsbrad Foothills, where he frequently baffled his angling partners with vivid, prophetic dreams of historical upheavals. Pagle has also ventured into far more perilous waters, including an excursion into the ruins of Zul'Gurub where he misplaced his favorite measuring tape and tackle box near the waters prowled by the monstrous hydra Gahz'ranka.",sp=0}},faq={{q="Who is Nat Pagle?",a="Nat Pagle is the most famous fisherman in Azeroth. Having angled for decades, he now lives a quiet life along the coast of Dustwallow Marsh, training veteran anglers who have outgrown ordinary trainers.",al={"who is nat","nat pagle lore","who is the fishing guy"}},{q="Where can Nat Pagle be found?",a="He lives on a small spit of land on the eastern coast of Dustwallow Marsh in Kalimdor, southwest of Theramore Isle.",al={"where is nat pagle","nat pagle location","find nat pagle"}},{q="Why does Nat Pagle fish if he says he dislikes it?",a="Pagle has candidly confessed that he views fishing primarily as a respectable, undisturbed excuse to sit by the water and drink heavily for hours at a time.",al={"does nat like fishing","why does nat fish","nat pagle drinking"}},{q="Will Nat Pagle train members of the Horde?",a="Yes. Nat is entirely neutral toward faction rivalries. Horde anglers who reach the upper limits of ordinary skill are sent directly to him by his friend Lumak in Orgrimmar.",al={"is nat alliance only","horde nat pagle","can horde talk to nat"}},{q="What connection does Nat Pagle have to Zul'Gurub?",a="Nat once fished within the ancient troll city of Zul'Gurub, leaving behind his tackle box and prized measuring tape near the waters harboring the great hydra Gahz'ranka.",al={"nat in zg","nat pagle tackle box","nat pagle zul gurub"}},{q="Where did Nat Pagle come from originally?",a="Years ago, Nat fished the southern docks of Southshore in the Hillsbrad Foothills alongside fellow locals, long before he decided to cross the Great Sea to Kalimdor.",al={"nat pagle southshore","nat origin","nat pagle hillsbrad"}}},ang={["faction:Horde"]="Lumak, the fishing trainer in the Valley of Honor in Orgrimmar, counts Nat Pagle as a trusted friend and sends promising Horde fishermen across the sea to train with him.",["faction:Alliance"]="Dwarven master anglers such as Grimnur Stonebrand in Ironforge hold Nat in high esteem, sending experienced Alliance fishermen down to Dustwallow Marsh to learn the craft's final secrets."},kw={"artisan fishing","dustwallow marsh","gahz'ranka","grimnur stonebrand","lumak","nat pagle","pagle","pagle's pointe","southshore"},rel={"zone:dustwallow","subzone:southshore","zone:hillsbrad","quest:6608","subzone:zul-gurub","zone:ironforge","topic:horde","topic:alliance"},src={"Nat Pagle"}}
E["npc:ogunaro-wolfrunner"] = {t="npc",n="Ogunaro Wolfrunner",z="orgrimmar",s="Ogunaro Wolfrunner is the Horde's premier wolf breeder and kennel keeper in Orgrimmar, stationed by the Hunter's Hall in the Valley of Honor. He tends the fierce wolves chosen to bear orc champions and their trusted allies into battle. For seasoned riders seeking a bond with Durotar's apex predators, Ogunaro is the master to see.",h="Ogunaro Wolfrunner is the Horde's premier wolf breeder and kennel keeper in Orgrimmar, stationed by the...",sec={{t="Master of the Pack",b="Situated near the Hunter's Hall within the Valley of Honor, Ogunaro Wolfrunner oversees the breeding and conditioning of Orgrimmar's battle wolves. The bond between orc and wolf dates back generations across the plains of Draenor and the rugged wilderness of Durotar, representing a partnership of mutual respect rather than mere domestication. Ogunaro ensures only the hardiest, fiercest beasts—from dire wolves to agile timber prowlers—are entrusted to warriors who have proven their strength and worth to the warchief.",sp=0}},faq={{q="Who is Ogunaro Wolfrunner?",a="Ogunaro Wolfrunner is the primary wolf breeder and mount vendor for the Horde, found outside the Hunter's Hall in Orgrimmar's Valley of Honor.",al={"ogunaro","wolf vendor orgrimmar","orc mount vendor"}},{q="Can anyone purchase a wolf from him?",a="By heritage, orcs can acquire wolves freely once properly trained. Non-orc members of the Horde must earn exalted standing and the utmost trust of Orgrimmar before Ogunaro will part with one of his prized beasts.",al={"can non orcs buy wolves","wolf mount rep requirements"}},{q="What kinds of wolves does he provide?",a="Ogunaro keeps a diverse kennel of battle-hardened mounts, including black, brown, dire, and timber wolves, as well as swift, armored breeds suited for veterans of war.",al={"types of wolf mounts","which wolves does ogunaro sell"}}},ang={["race:Orc"]="For orcs, riding a wolf is an ancestral tradition linking back to the clans of Draenor; Ogunaro stands as the keeper of that sacred martial bond.",["faction:Horde"]="Trolls, tauren, and Forsaken must prove their dedication and honor to Orgrimmar before Ogunaro will entrust them with a wolf mount."},kw={"dire wolf","ogunaro wolfrunner","orgrimmar mounts","timber wolf","valley of honor","wolf mount"},rel={"subzone:valley-of-honor","zone:orgrimmar","quest:7660","quest:7661"},src={"Ogunaro Wolfrunner"}}
E["npc:orokk-omosh"] = {t="npc",n="Orokk Omosh",z="orgrimmar",s="Orokk Omosh is an aging orc blacksmith stationed in Orgrimmar's Valley of Honor. As the last heir to a storied lineage of smiths, he seeks worthy apprentices across the Horde to preserve his family's armoring secrets before they are lost to time.",h="Orokk Omosh is an aging orc blacksmith stationed in Orgrimmar's Valley of Honor.",sec={{t="A Lineage at Its End",b="Standing beside the roaring forges in the Valley of Honor, Orokk Omosh carries a heavy burden: he is the final smith of the venerable Omosh line. Having fathered no children to inherit his craft, Orokk refuses to let his family's hard-won techniques die with him. Instead, he invites capable Horde blacksmiths to undertake demanding trials of metalwork, promising to impart the revered secrets of Omosh armorcraft to those who prove their dedication.",sp=0},{t="The Spirit of the Forge",b="Despite the somber reality of his fading bloodline, Orokk is known among fellow artisans for his boisterous enthusiasm when true mastery is displayed. Completing his trials of craftsmanship earns more than just specialized armoring patterns—it often provokes the famous 'Omosh Dance of Joy,' a jubilant celebration of traditional smithing that echoes through the halls of Orgrimmar.",sp=0}},faq={{q="Who is Orokk Omosh?",a="Orokk Omosh is a master orc blacksmith residing in the Valley of Honor in Orgrimmar. He is the last surviving member of the Omosh lineage of smiths and spends his days searching for promising apprentices to inherit his family's metallurgical knowledge.",al={"who is orokk","orokk omosh lore","orc smith orgrimmar"}},{q="Where can Orokk Omosh be found?",a="You can find Orokk Omosh near the smithing forges and anvils in the Valley of Honor, located in the northeastern section of Orgrimmar.",al={"orokk omosh location","where is orokk","find orokk omosh"}},{q="Why is Orokk Omosh teaching outsiders his family secrets?",a="Orokk has no children of his own to inherit his family's craft. Rather than allow generations of orcish armoring techniques to die out, he has chosen to teach any skilled Horde blacksmith who proves capable of meeting his high standards.",al={"why does orokk give quests","omosh legacy","why teach blacksmiths"}},{q="What is the 'Omosh Dance of Joy'?",a="It is an exuberant, celebratory jig that Orokk performs when an artisan successfully proves their worth and masters his line's smithing techniques. It serves as both his personal stamp of approval and a spirited tribute to the craft.",al={"dance of joy","omosh dance","joys of omosh"}}},ang={["profession:Blacksmithing"]="For aspiring Horde armorers, Orokk Omosh is an essential mentor who offers specialized patterns and training to ensure his ancestral craft survives.",["faction:Horde"]="Orokk's dedication ensures that traditional orcish plate and mail techniques remain available to bolster the warriors defending the fledgling Horde."},kw={"barbaric battlements","blacksmithing","dance of joy","omosh","orc smith","orgrimmar","orokk omosh","valley of honor"},rel={"subzone:valley-of-honor","zone:orgrimmar","quest:2751","quest:2753","quest:2755","topic:horde"},src={"Orokk Omosh"}}
E["npc:orphan-matron-battlewail"] = {t="npc",n="Orphan Matron Battlewail",z="orgrimmar",s="Orphan Matron Battlewail manages the Horde orphanage in Orgrimmar's Valley of Honor. Together with her fellow caretaker Tosamina, she shelters and raises young orc children who have lost their families to continuous warfare.",h="Orphan Matron Battlewail manages the Horde orphanage in Orgrimmar's Valley of Honor.",sec={{t="Caretaker of the Horde's Youth",b="War takes a constant toll across Azeroth, and the young capital of Orgrimmar bears witness to those costs. Orphan Matron Battlewail tends to the youngsters who lost their kin to violence, ensuring that the next generation of the Horde is protected, sheltered, and nurtured. Working alongside Tosamina in the Valley of Honor, Battlewail opens the orphanage doors to passing adventurers, especially during festive traditions like Children's Week when travelers are called upon to mentor these youths.",sp=0}},faq={{q="Who is Orphan Matron Battlewail?",a="She is an orc woman who oversees the orphanage in Orgrimmar, dedicating her life to sheltering and raising children whose parents died in battle.",al={"battlewail role","who is battlewail","matron battlewail"}},{q="Where can she be found in Orgrimmar?",a="Battlewail and her companion Tosamina care for the children in the Valley of Honor, situated within the eastern reaches of Orgrimmar.",al={"battlewail location","where is the orphanage","find battlewail"}},{q="What is her role during Children's Week?",a="During the holiday of Children's Week, Battlewail organizes mentorship efforts, sending willing champions out into the world with an orphan to show them the wonders and heritage of the Horde.",al={"childrens week battlewail","warden of the horde","orphan quest"}},{q="Who assists Battlewail at the orphanage?",a="Tosamina lives and works alongside Battlewail, helping watch over and protect the children entrusted to their care.",al={"tosamina","orphan matron helper"}}},ang={["faction:Horde"]="Battlewail preserves the future of the Horde by giving guidance and shelter to children left behind by the harsh realities of war.",["race:Orc"]="For orcs striving to build a lasting homeland in Durotar, Battlewail's orphanage stands as a sobering reminder of the sacrifices their people endure."},kw={"battlewail","children's week","orgrimmar","orphan matron battlewail","orphanage","tosamina","valley of honor","warden of the horde"},rel={"zone:orgrimmar","subzone:valley-of-honor","quest:5502","topic:horde","subzone:drag"},src={"Orphan Matron Battlewail"}}
E["npc:searn-firewarder"] = {t="npc",n="Searn Firewarder",z="orgrimmar",s="Searn Firewarder is a Darkspear troll shaman trainer stationed inside Grommash Hold in Orgrimmar. He assists developing shamans across the Horde, directing them toward the trials needed to commune with the elemental spirits of fire, water, and air.",h="Searn Firewarder is a Darkspear troll shaman trainer stationed inside Grommash Hold in Orgrimmar.",sec={{t="A Guide to the Elements",b="Standing within the fortified walls of Grommash Hold alongside the Horde's high command, Searn Firewarder serves as an elemental guide for aspiring shamans. While many Darkspear trolls commune with the spirits through witch doctors and voodoo rituals, Searn represents the bond troll shamans forge directly with the living elements of Kalimdor. He acts as an intermediary, directing initiates toward the far-flung mentors and rites required to earn the Call of Fire, Call of Water, and Call of Air.",sp=0}},faq={{q="Who is Searn Firewarder?",a="Searn Firewarder is a jungle troll shaman trainer based inside Grommash Hold in Orgrimmar. He directs developing Horde shamans through the steps of their spiritual journeys.",al={"searn firewarder lore","who is searn","searn orgrimmar"}},{q="What quests does Searn Firewarder offer?",a="Searn helps guide shamans through their elemental awakening quests, including the Call of Fire, Call of Water, and Call of Air, pointing them to distant shrines and spiritual teachers across the continents.",al={"searn quests","searn firewarder questline"}},{q="Why is a troll shaman stationed inside Grommash Hold?",a="Grommash Hold serves as the heart of Orgrimmar's leadership, hosting Warchief Thrall and prominent representatives from the allied races. Searn's presence reflects the close unity between the orcs and the Darkspear tribe, as well as the central role shamanism plays in the new Horde.",al={"why is searn in grommash hold","searn grommash hold"}}},ang={["class:Shaman"]="Searn is an important checkpoint for developing Horde shamans, directing them toward the masters and trials needed to bind the elements to their totems.",["race:Troll"]="As a Darkspear shaman standing inside Grommash Hold, Searn demonstrates how troll spiritualists have adapted their ancestral ties alongside their orc and tauren allies."},kw={"call of air","call of fire","call of water","darkspear","grommash hold","orgrimmar","searn firewarder","shaman trainer"},rel={"subzone:grommash-hold","zone:orgrimmar","quest:1524","quest:63","quest:1531","topic:troll","topic:horde"},src={"Searn Firewarder"}}
E["npc:seereth-stonebreak"] = {t="npc",n="Seereth Stonebreak",z="orgrimmar",s="Seereth Stonebreak is an orc shaman who serves the Horde by monitoring the disturbances unsettling the land. Camped near the Greatwood Vale on the border of the Stonetalon Mountains and the Barrens, she directs travelers to address environmental ruin, rogue machines, and rising tensions in Kalimdor.",h="Seereth Stonebreak is an orc shaman who serves the Horde by monitoring the disturbances unsettling the land.",sec={{t="A Watchful Shaman",b="Seereth Stonebreak is an orc dedicated to the harmony of the elements and the protection of Horde territories. Sent to Stonetalon after the land's spirits cried out against the goblins' plunder, she keeps her camp near the Greatwood Vale and maintains a vigilant eye over the landscape. Rather than retreat into despair, she uses her spiritual insight and knowledge of the wild frontier to guide adventurers against looming dangers.",sp=0},{t="Turmoil in Stonetalon",b="Seereth is acutely troubled by the turmoil wracking the Stonetalon range. Between the disruptive presence of ruthless goblin ventures and the unchecked operations of mechanical shredders cutting through ancient woodlands, the spiritual balance of the mountains has been severely fractured. She tasks Horde envoys with confronting these reckless invaders and consulting elder lorekeepers to heal the land's distress.",sp=0}},faq={{q="Who is Seereth Stonebreak?",a="Seereth Stonebreak is an orc shaman serving the Horde. She provides guidance and quests for travelers heading toward the Stonetalon Mountains, addressing threats to the land and the Horde's presence.",al={"seereth","who is seereth","seereth stonebreak lore"}},{q="Why is Seereth concerned about the Stonetalon Mountains?",a="The Stonetalon Mountains are suffering from rampant deforestation, aggressive goblin logging machinery, and heightened conflict. As a shaman, Seereth senses the agitation of the local spirits and works to halt the devastation.",al={"why stonetalon","seereth problems","stonetalon unrest"}},{q="What happened to her original post?",a="Nothing has befallen it. Seereth was sent to Stonetalon by the Horde and remains camped near the Greatwood Vale, on the border of the Stonetalon Mountains and the Barrens, reached by the road west of the Crossroads.",al={"seereth past","honors stand seereth","why did seereth move"}},{q="What tasks does Seereth offer to adventurers?",a="She sends Horde adventurers into Stonetalon to deal with intrusive Venture Company goblins, dismantle destructive shredding machines, commune with troubled spirits, and consult respected elder figures like Magatha Grimtotem.",al={"seereth quests","what does seereth want","seereth stonebreak missions"}},{q="Who is the Elder Crone she mentions?",a="The Elder Crone refers to Magatha Grimtotem, a powerful and influential tauren elder residing on the Elder Rise in Thunder Bluff, whom Seereth consults for guidance regarding deep spiritual disturbances.",al={"the elder crone","who is elder crone","crone quest"}},{q="Why is she concerned with goblin operations?",a="Unchecked goblin logging operations rely on mechanical shredders that tear through sacred forests, polluting waterways and enraging nature spirits that Seereth is sworn to appease.",al={"seereth goblins","goblin invaders","why hate goblins"}}},ang={["class:Shaman"]="Seereth's focus on the troubled elements and wounded nature in Stonetalon mirrors the duty of any shaman to heal environmental scars and placate agitated spirits.",["faction:Horde"]="Her orders protect critical overland routes and resources against both encroaching Alliance forces and reckless goblin operations.",["race:Orc"]="Seereth represents the modern orcish return to shamanism and reverence for the natural world, standing in opposition to mindless destruction."},kw={"crone","goblins","seereth","shaman","shredders","spirits","stonebreak","stonetalon"},rel={"zone:stonetalon","quest:1061","quest:1062","quest:1068","quest:1063","topic:goblin","topic:alliance"},src={"Seereth Stonebreak"}}
E["npc:serge-hinott"] = {t="npc",n="Serge Hinott",z="orgrimmar",s="Serge Hinott is a Forsaken alchemist stationed in Tarren Mill in the Hillsbrad Foothills. Working closely alongside Apothecary Lydon, he assists the Royal Apothecary Society with brewing concoctions, antidotes, and reagents essential to the Forsaken war effort.",h="Serge Hinott is a Forsaken alchemist stationed in Tarren Mill in the Hillsbrad Foothills.",sec={{t="Apothecary's Hand in Tarren Mill",b="Positioned beside Apothecary Lydon in the fortified settlement of Tarren Mill, Serge Hinott plays a crucial supporting role for Forsaken operations in Hillsbrad Foothills. While Lydon focuses on broader chemical development and aggressive plague research against neighboring human settlements like Southshore, Hinott manages specialized brewing tasks. His expertise includes preparing restorative salves and critical antidotes required when field agents and scouts encounter dangerous poisons and toxic mishaps.",sp=0}},faq={{q="Where can Serge Hinott be found?",a="Serge Hinott is stationed in Tarren Mill, located in the central northern reaches of the Hillsbrad Foothills. He stands outdoors near Apothecary Lydon, working among his brewing supplies and alchemical equipment.",al={"serge hinott location","where is hinott","find serge hinott"}},{q="What role does Serge Hinott serve?",a="He is an alchemist serving the Forsaken in Tarren Mill. In addition to aiding in the preparation of local brews and treatments, he helps brew specialized mixtures when requested by field operatives and couriers.",al={"what does hinott do","serge hinott role"}},{q="What is Hinott's connection to Apothecary Lydon?",a="Hinott works directly beside Apothecary Lydon, acting as an assistant and fellow chemist supporting Lydon's ongoing alchemical research and operations throughout Hillsbrad Foothills.",al={"hinott and lydon","who does hinott work with"}}},ang={["race:Undead"]="Hinott represents the practical arm of the Royal Apothecary Society in Hillsbrad, providing necessary chemical mixtures and support directly to frontline Forsaken forces.",["class:Rogue"]="Hinott assists rogues seeking a cure for the virulent Touch of Zanzil, crafting the essential antidote when standard remedies fail."},kw={"apothecary lydon","hillsbrad foothills","hinott","royal apothecary society","serge hinott","tarren mill"},rel={"subzone:tarren-mill","quest:2479","zone:hillsbrad","topic:forsaken","subzone:southshore"},src={"Serge Hinott"}}
E["npc:shenthul"] = {t="npc",n="Shenthul",z="orgrimmar",s="Shenthul is a jungle troll rogue trainer based in the shadowy subterranean reaches of the Cleft of Shadow in Orgrimmar. As an operative of the Shattered Hand, he orchestrates espionage operations across Kalimdor and initiates rising rogues into the guild's covert ranks.",h="Shenthul is a jungle troll rogue trainer based in the shadowy subterranean reaches of the Cleft of Shadow in...",sec={{t="Eyes in the Chasm",b="Tucked away inside the murky depths of the Cleft of Shadow, Shenthul serves as one of the Horde's foremost rogue mentors. While the warriors and shamans above march openly across the red dust of Durotar, Shenthul trains those who prefer stealth, ambush, and subterfuge. Under his tutelage, initiates master essential fieldcraft and lethal arts, learning to operate within the unforgiving politics and harsh wilderness of Kalimdor.",sp=0},{t="The Shattered Hand",b="Shenthul represents the Shattered Hand, an order transformed from an old orcish clan into the Horde's intelligence network and secret service. He views the organization as a timeless, watchful veil blanketing Kalimdor—acting as investigator, judge, jury, and executioner. Fiercely pragmatic and independent of shifting political tides, Shenthul famously reminds outsiders that the Shattered Hand existed long before Warchief Thrall took power and will endure long after him.",sp=0},{t="Covert Fieldwork",b="Beyond basic training, Shenthul coordinates delicate missions into contested territories. His assignments send operatives on perilous infiltration assignments, such as conducting deep-cover operations against hostile interests, monitoring suspicious operations like the Venture Company in Windshear Crag, and testing recruits through demanding clandestine trials. When poisons strike his field agents, Shenthul ensures they secure remedies before fatal consequences take hold.",sp=1}},faq={{q="Who is Shenthul?",a="Shenthul is a jungle troll rogue trainer and operative of the Shattered Hand stationed in the Cleft of Shadow beneath Orgrimmar.",al={"shenthul role","who is shenthul","troll rogue trainer orgrimmar"}},{q="Where can I find Shenthul?",a="He can be found in the Cleft of Shadow, the subterranean cavern complex accessed through the darker tunnels of Orgrimmar.",al={"shenthul location","where is shenthul","shenthul cleft of shadow"}},{q="What is Shenthul's connection to the Shattered Hand?",a="Shenthul is a dedicated operative and recruiter for the Shattered Hand, the covert intelligence and assassin guild operating within the Horde.",al={"shattered hand shenthul","is shenthul shattered hand","what faction is shenthul"}},{q="What does Shenthul think of Warchief Thrall?",a="Shenthul is loyal to the craft and security of the Horde, but maintains that the Order of the Shattered Hand existed before Thrall and will outlast his rule, seeing his guild as an eternal necessity.",al={"shenthul thoughts on thrall","does shenthul like thrall","shenthul loyalty"}},{q="What missions does Shenthul offer to rogues?",a="He guides rogues through initiation trials, sends them on covert infiltration missions, and dispatches them to investigate threats such as the Venture Company in Stonetalon Mountains.",al={"shenthul quests","rogue quests shenthul"}},{q="Does Shenthul assist with rogue poisons?",a="Yes, during crucial field operations where rogues face lethal toxins, Shenthul directs agents to Hinott to ensure survival and ongoing fieldwork.",al={"shenthul poison quest","hinott assistance shenthul"}}},ang={["class:Rogue"]="Shenthul is a primary mentor and handler for Horde rogues arriving in Orgrimmar, offering skill training, initiation trials, and covert assignments.",["faction:Horde"]="Operating beneath the surface of the capital, Shenthul directs the covert intelligence arm that protects the Horde from unseen internal and external threats.",["race:Troll"]="As a jungle troll embedded deeply in the traditionally orcish Shattered Hand, Shenthul demonstrates how Darkspear rogues have woven themselves into the Horde's highest levels of espionage."},kw={"cleft of shadow","jungle troll","orgrimmar","rogue trainer","shattered hand","shenthul","venture company","windshear crag"},rel={"subzone:cleft-of-shadow","zone:orgrimmar","quest:2458","quest:2478","quest:2460","quest:2479","subzone:windshear-crag","topic:venture-company"},src={"Shenthul"}}
E["npc:tai-jin"] = {t="npc",n="Tai'jin",z="orgrimmar",s="Tai'jin is a Darkspear troll priest trainer stationed within the barracks of Razor Hill in Durotar. She guides fledgling priests of the Horde, introducing Darkspear initiates to traditional troll rites such as the Hex of Weakness.",h="Tai'jin is a Darkspear troll priest trainer stationed within the barracks of Razor Hill in Durotar.",sec={{t="Priestess of Razor Hill",b="Stationed inside the sturdy barracks of Razor Hill, Tai'jin serves as a spiritual mentor for young priests stepping out into Durotar. While orcs predominantly turn to shamanism or dark warlock arts, the Darkspear trolls bring their own distinct communion with the spirits and loas to the Horde. Tai'jin offers foundational teachings in the priesthood, ensuring that new acolytes understand both the balance of light and shadow and the spiritual heritage unique to troll culture.",sp=0}},faq={{q="Where can I find Tai'jin?",a="Tai'jin is located on the ground floor of the Razor Hill Barracks in central Durotar, right beside other class trainers.",al={"tai'jin location","where is tai'jin","taijin razor hill"}},{q="What does Tai'jin teach?",a="As a priest trainer, she teaches new priest spells, ranks, and abilities to Horde characters as they gain experience, including early training quests for troll initiates.",al={"taijin trainer","what does taijin train","priest spells razor hill"}},{q="Why is a troll priest stationed in an orc settlement?",a="Razor Hill serves as the main training hub for all young Horde adventurers venturing out of the Valley of Trials and Sen'jin Village. Because orcs do not practice the priestly arts, Tai'jin represents the Darkspear tribe's spiritual traditions for the settlement.",al={"why is taijin in razor hill","trolls in razor hill barracks"}},{q="What special rites does Tai'jin provide for troll priests?",a="Tai'jin guides Darkspear priests through introductory spiritual rites, notably teaching them how to channel ancestral curses through the Hex of Weakness.",al={"hex of weakness quest","taijin quests"}}},ang={["class:Priest"]="For Horde priests training in Durotar, Tai'jin is your primary mentor before heading to the grand halls of Orgrimmar.",["race:Troll"]="Tai'jin introduces young Darkspear priests to their culture's distinctive spells, such as the Hex of Weakness."},kw={"darkspear","durotar","hex of weakness","priest trainer","razor hill","tai'jin","taijin"},rel={"subzone:razor-hill","zone:durotar","topic:troll","quest:5654","zone:orgrimmar"},src={"Tai'jin"}}
E["npc:takata-steelblade"] = {t="npc",n="Takata Steelblade",z="orgrimmar",s="Takata Steelblade is an orc warrior stationed at Ghost Walker Post in Desolace. Dispatched from Orgrimmar by Keldran alongside Maurin Bonesplitter, he spearheads the Horde's local campaign against demonic corruption. His primary focus is eradicating the regional satyr population affiliated with the sinister Burning Blade.",h="Takata Steelblade is an orc warrior stationed at Ghost Walker Post in Desolace.",sec={{t="Sent to Desolace",b="Takata Steelblade was sent from the capital to Desolace under direct orders from Keldran, an influential figure in Orgrimmar committed to uncovering and purging demonic subversion. Operating out of the isolated Tauren encampment of Ghost Walker Post, Takata coordinates military efforts against the Legion-aligned forces plaguing the barren wastes.",sp=0},{t="Scourge of the Satyrs",b="While his companion Maurin Bonesplitter attempts to track and dismantle the clandestine Burning Blade cultists directly, Takata focuses on their demonic allies: the satyrs. Takata has orchestrated aggressive strikes against Desolace's corrupted satyrs, decimating their ranks to break the cult's local power structure and halt their spreading taint.",sp=0}},faq={{q="Who is Takata Steelblade?",a="Takata Steelblade is a veteran orc warrior stationed at Ghost Walker Post in Desolace. He directs operations against demonic forces and satyrs allied with the Burning Blade.",al={"takata","takata lore","who is takata"}},{q="Who sent Takata to Desolace?",a="He was sent by Keldran from Orgrimmar to eliminate the threat posed by the Burning Blade and their demonic allies throughout the region.",al={"who sent takata","keldran connection","takata orders"}},{q="What is the relationship between Takata and Maurin Bonesplitter?",a="Both were dispatched together by Keldran. While Maurin attempts to counter the Burning Blade cultists directly, Takata focuses his military strikes on the satyrs allied with them.",al={"takata and maurin","maurin bonesplitter"}},{q="Why is Takata hunting satyrs?",a="The satyrs in Desolace are actively allied with the Burning Blade cult, spreading demonic taint and threatening the Horde's foothold across the region.",al={"why kill satyrs","takata satyr","befouled by satyr"}},{q="Where can Takata Steelblade be found?",a="He is located at Ghost Walker Post, a Horde camp in north-central Desolace.",al={"takata location","where is takata steelblade"}},{q="What is Takata's fighting style or background?",a="Bearing a slender blade and the surname Steelblade, Takata carries the demeanor and weapon choice associated with traditional orcish blademasters, applying swift martial mastery against demonic foes.",al={"is takata a blademaster","takata class"}}},ang={["faction:Horde"]="Takata coordinates regional Horde defense in Desolace, working out of Ghost Walker Post to purge demonic infiltrators.",["race:Orc"]="Acting under orders from Orgrimmar's leadership, Takata embodies the orcish duty to stamp out any remnant of demonic servitude.",["class:Warrior"]="A master swordsman, Takata's campaign emphasizes decisive martial force to cut down demonic infiltrators."},kw={"bonesplitter","burning blade","desolace","ghost walker post","keldran","maurin","satyr","steelblade","takata"},rel={"subzone:ghost-walker-post","zone:desolace","npc:keldran","npc:maurin-bonesplitter","topic:satyr","quest:1431"},src={"Takata Steelblade"}}
E["npc:thrall"] = {t="npc",n="Thrall",z="orgrimmar",s="Thrall is the Warchief of the Horde and the ruler of Durotar, holding court from the Valley of Wisdom in Orgrimmar. Once a human slave raised to be an arena gladiator, he broke the chains of his people, rediscovered their ancient shamanic traditions, and led them across the Great Sea to build a new homeland.",h="Thrall is the Warchief of the Horde and the ruler of Durotar, holding court from the Valley of Wisdom in...",sec={{t="From Slave to Shaman",b="Born Go'el, the son of Frostwolf chieftain Durotan and Draka, Thrall was orphaned as an infant when his parents were murdered by Gul'dan's assassins. He was discovered by human commander Aedelas Blackmoore, who named him 'Thrall'—meaning slave—and raised him at Durnholde Keep as an arena fighter with an education in human tactics. Aided by his foster sister Taretha Foxton, Thrall eventually escaped his captors. Guided by the Frostwolf exile Drek'Thar, he cast aside demonic corruption to master the elemental spirits, becoming the first of a new generation of orcish shaman.",sp=0},{t="The Mantle of the Warchief",b="Thrall joined forces with the legendary Orgrim Doomhammer to liberate the lethargic orcs languishing in Alliance internment camps after the Second War. When Doomhammer fell in battle, he bestowed his black plate armor and mighty warhammer upon Thrall, naming him the new Warchief. Following prophetic visions from the mysterious Prophet Medivh, Thrall led his people to commandeer human ships and sail across the Great Sea to the forgotten continent of Kalimdor, escaping the doom falling upon the Eastern Kingdoms.",sp=0},{t="Forging the New Horde",b="In Kalimdor, Thrall reshaped the Horde from a warmongering engine into an alliance of survival and honor. He rescued the Darkspear trolls led by Vol'jin and allied with Cairne Bloodhoof's tauren before leading the coalition alongside human and night elf forces to defeat the Burning Legion atop Mount Hyjal. Afterward, Thrall founded the nation of Durotar and its capital Orgrimmar, named after his father and mentor. Despite maintaining an uneasy peace with Jaina Proudmoore's Theramore, Thrall now balances the defense of his fragile nation with controversial alliances, such as admitting the Forsaken of Lordaeron into the Horde fold.",sp=0}},faq={{q="Who is Thrall?",a="Thrall is the Warchief of the Horde and the leader of the orcish people. Born Go'el of the Frostwolf clan, he was raised as an enslaved gladiator by humans before breaking free, learning the shamanic arts, and leading the orcs to Kalimdor to found their new capital of Orgrimmar.",al={"who is the warchief","thrall backstory","who is thrall"}},{q="Where does Thrall's name come from?",a="His birth name is Go'el, given by his parents Durotan and Draka. His human captor, Aedelas Blackmoore, named him 'Thrall'—an old human word meaning slave. Thrall retained the name as a reminder of where he came from and the oppression his people swore never to endure again.",al={"why is he called thrall","what does thrall mean","thrall real name"}},{q="Why does Thrall wear black armor and carry a hammer?",a="Thrall wears the black plate armor and wields the Doomhammer passed to him by Orgrim Doomhammer, the former Warchief. Upon receiving a mortal wound during the liberation of the internment camps, Orgrim bestowed both the weapon and the mantle of Warchief upon Thrall with his dying breath.",al={"doomhammer","thrall weapon","black armor"}},{q="Where can I find Thrall in the game?",a="Thrall resides inside the Valley of Wisdom within Orgrimmar, the Horde capital in Durotar. He stands inside Grommash Hold accompanied by his bodyguards and advisers.",al={"where is thrall","thrall location","thrall room"}},{q="What is Thrall's relationship with Jaina Proudmoore?",a="Thrall and Lady Jaina Proudmoore forged a mutual respect and pact of cooperation while fighting alongside each other during the Third War at Mount Hyjal. Though their respective factions remain deeply distrustful, the two leaders strive to preserve a fragile peace between Orgrimmar and Theramore.",al={"thrall and jaina","jaina alliance","peace with theramore"}},{q="Why did Thrall allow the Forsaken into the Horde?",a="While cautious of the undead, Thrall recognized the desperate plight of Sylvanas Windrunner's Forsaken, who had freed themselves from the Lich King's control. Aided by the diplomatic urging of the tauren, who believe the Forsaken can be redeemed, Thrall granted them membership to secure a strategic foothold in the Eastern Kingdoms.",al={"why are undead in horde","forsaken alliance","sylvanas horde entry"}}},ang={["faction:Horde"]="Thrall is your supreme commander and Warchief, having led the Horde out of enslavement and ruin to claim an honorable future on Kalimdor.",["faction:Alliance"]="Alliance leaders view Thrall as a dangerous yet pragmatic leader whose disciplined Horde is vastly preferable to the bloodthirsty conquerors of the First and Second Wars.",["class:Shaman"]="Thrall is revered as the first new orcish shaman in a generation, having restored the sacred communion between his people and the elemental spirits after decades of demonic corruption.",["race:Orc"]="To the orcs, Thrall is a living savior who broke the lethargy of the human internment camps and returned the race to its ancestral honor."},kw={"blackmoore","doomhammer","durotar","go'el","orgrimmar","shaman","thrall","warchief"},rel={"zone:orgrimmar","zone:durotar","npc:orgrim-doomhammer","topic:new-horde","npc:vol-jin","npc:sylvanas-windrunner","subzone:durnholde-keep","topic:third-war"},src={"Thrall"}}
E["npc:ur-kyo"] = {t="npc",n="Ur'kyo",z="orgrimmar",s="Ur'kyo is a revered jungle troll priest trainer located in the Valley of Spirits within Orgrimmar. Known as the spiritual leader and greatest priest among the Darkspear tribe, he guides fledgling practitioners of the spiritual arts in the capital of the Horde. Through his council, priests learn to commune with the spirits and balance the powerful forces of shadow and light.",h="Ur'kyo is a revered jungle troll priest trainer located in the Valley of Spirits within Orgrimmar.",sec={{t="Spiritual Master of the Darkspear",b="Residing in the serene waters and huts of the Valley of Spirits, Ur'kyo stands as one of the most prominent spiritual authorities in Orgrimmar. For the Darkspear trolls who fled the Echo Isles and forged a home in Durotar alongside Thrall's Horde, maintaining their sacred traditions is essential. Ur'kyo preserves these ancestral practices, serving as a pillar of spiritual discipline and guidance for tribal mystics and visiting practitioners alike.",sp=0},{t="Guidance and Ancient Rites",b="Priests walking the path of faith find a patient instructor in Ur'kyo. He oversees traditional training and ancient rites, including teachings that bestow the Hex of Weakness and the defensive ward known as Shadowguard. Ur'kyo also acts as a liaison for Horde priests seeking to understand the diverse spiritual practices within their coalition, helping them bridge the gap between troll voodoo, ancestral ways, and foreign disciplines.",sp=0}},faq={{q="Who is Ur'kyo?",a="Ur'kyo is a jungle troll and the primary priest trainer in Orgrimmar's Valley of Spirits. He is regarded as the spiritual leader of the Darkspear priests and the greatest practitioner of the priesthood among his tribe.",al={"urkyo role","ur'kyo identity","who is urkyo"}},{q="Where can I find Ur'kyo?",a="Ur'kyo resides in the Valley of Spirits, the troll-inhabited district on the western side of Orgrimmar. He can be found in the training huts near the water alongside other spiritual mentors.",al={"ur'kyo location","urkyo map","find urkyo"}},{q="What abilities does Ur'kyo teach?",a="As a class trainer, Ur'kyo instructs priests in foundational spells of shadow and light. In addition, he initiates Darkspear priests into their unique racial rites, guiding them to master Hex of Weakness and Shadowguard.",al={"urkyo spells","ur'kyo abilities","troll priest spells"}},{q="Why does Ur'kyo practice in Orgrimmar rather than the Echo Isles?",a="Following the betrayal of Zalazane and the loss of the Echo Isles, the Darkspear tribe resettled alongside the orcs in Durotar. Ur'kyo established himself in the Valley of Spirits to maintain the tribe's mystical traditions and train new defenders for the Horde.",al={"urkyo orgrimmar lore","why is urkyo in orgrimmar"}},{q="Does Ur'kyo interact with non-troll priests?",a="Yes. Ur'kyo instructs all Horde priests who visit him, serving as a conduit for knowledge between the Darkspear trolls and other members of the Horde, including the Forsaken.",al={"can undead train at urkyo","urkyo horde trainer"}},{q="What is Ur'kyo's role among the Darkspear priests?",a="Ur'kyo is recognized as the greatest priest of the Darkspear tribe and acts as their premier spiritual leader, ensuring that ancestral customs, rites, and voodoo practices are handed down to the next generation.",al={"ur'kyo standing","greatest priest of the tribe"}}},ang={["class:Priest"]="Ur'kyo is a vital teacher for Horde priests traveling through Durotar, instructing adventurers in the mysteries of faith, shadow rites, and sacred wards.",["race:Troll"]="For Darkspear trolls, Ur'kyo is the foremost spiritual guide in Orgrimmar, preserving the tribe's traditional voodoo and ancient magical rites after the loss of the Echo Isles.",["faction:Horde"]="Located in the heart of Orgrimmar's Valley of Spirits, Ur'kyo provides the spiritual backbone needed to prepare healers and shadowcasters for the Horde's defense."},kw={"darkspear","hex of weakness","orgrimmar","priest trainer","shadowguard","ur'kyo","urkyo","valley of spirits"},rel={"subzone:valley-of-spirits","zone:orgrimmar","topic:troll","quest:5654","quest:5643","quest:5644"},src={"Ur'kyo"}}
E["npc:warcaller-gorlach"] = {t="npc",n="Warcaller Gorlach",z="orgrimmar",s="Warcaller Gorlach is an orc herald roaming the dusty streets of Orgrimmar, calling champions of the Horde to distant battlefronts. True to his title, he rallies travelers and seasoned warriors to answer commands in perilous outposts across Kalimdor and beyond.",h="Warcaller Gorlach is an orc herald roaming the dusty streets of Orgrimmar, calling champions of the Horde to...",sec={{t="Voice of the Warchief's Call",b="Patrolling the thoroughfares of Orgrimmar, Warcaller Gorlach serves as a primary herald for the Horde's expansion and strategic defenses. Rather than staying confined to a garrison desk, he marches among the citizenry, issuing orders directly to volunteers ready to test their mettle. Whether dispatching hunters into the contested canopy of Ashenvale, directing scouts toward the wilderness of Camp Mojache in Feralas, or issuing desperate calls to arms for distant campaigns like the Plaguelands, Gorlach ensures that no warrior lingering in the capital remains idle while the Horde faces threats abroad.",sp=0}},faq={{q="Who is Warcaller Gorlach?",a="Gorlach is a wandering orc herald in Orgrimmar who issues orders and directs adventurous Horde members toward critical combat zones and remote frontiers.",al={"gorlach","who is gorlach","warcaller"}},{q="Where does Warcaller Gorlach send adventurers?",a="He directs Horde champions toward various outposts in need of aid, including the forests of Ashenvale, Camp Mojache in Feralas, and distant fronts such as the Plaguelands.",al={"gorlach destinations","where does gorlach send you","gorlach quests"}},{q="Where can Warcaller Gorlach be found?",a="He can be found wandering through the streets and valleys of Orgrimmar, shouting the call to arms as he patrols the capital.",al={"gorlach location","where is gorlach","find gorlach"}}},ang={["faction:Horde"]="For Horde champions looking to prove their strength or seek guidance beyond Durotar, Gorlach provides clear direction toward outposts desperate for reinforcements."},kw={"ashenvale hunt","call to arms","camp mojache","gorlach","herald","orgrimmar","warcaller gorlach"},rel={"zone:orgrimmar","topic:horde","quest:235","zone:ashenvale","subzone:camp-mojache"},src={"Warcaller Gorlach"}}
E["npc:warlord-gorchuk"] = {t="npc",n="Warlord Gorchuk",z="orgrimmar",s="Warlord Gorchuk is an orc commander stationed in Orgrimmar's Valley of Spirits. Tasked with organizing the Horde's side of the massive Ahn'Qiraj War Effort, he tracks logistical stockpiles and directs vital supplies south to Silithus.",h="Warlord Gorchuk is an orc commander stationed in Orgrimmar's Valley of Spirits.",sec={{t="Marshal of the Horde War Effort",b="When ancient terrors began stirring beneath the shifting sands of Silithus, the Horde recognized a threat capable of sweeping across Kalimdor and consuming all life. To meet the swarms of Ahn'Qiraj, the Horde required an unprecedented mobilization of metals, herbs, leathers, bandages, and provisions. Warlord Gorchuk serves as the logistical head of this operation within Orgrimmar. Stationed in the Valley of Spirits, he tallies incoming materials from adventurers and craftsmen across the realm, ensuring supply lines are filled before the grand march southward begins.",sp=0},{t="An Uneasy Truce Against the Old God",b="Though proud of the Horde's martial strength, Gorchuk openly acknowledges the chilling scope of the looming conflict. The insectoid qiraji and their master, the Old God C'Thun, despise all mortal life forged by the ancient Titans. Because neither faction can endure such an onslaught alone, Gorchuk coordinates closely with intelligence regarding the Alliance's own mobilization, tracking collective stockpiles until both factions are prepared to ship their full arsenal to the Scarab Dais.",sp=0}},faq={{q="Where can I find Warlord Gorchuk?",a="Warlord Gorchuk is stationed in the Valley of Spirits within the Horde capital of Orgrimmar, coordinating resource collection for the impending campaign in Silithus.",al={"gorchuk location","where is gorchuk","warlord gorchuk valley of spirits"}},{q="What is the purpose of the war supplies Gorchuk requests?",a="The gathered materials—spanning hundreds of thousands of bandages, metal bars, leathers, cooked meals, and herbs—are stockpiled to equip and sustain the united armies preparing to confront the qiraji armies sealed behind the Gates of Ahn'Qiraj.",al={"why donate supplies","what are war supplies for","war effort turn ins"}},{q="Why is the Horde working alongside the Alliance for this campaign?",a="As Gorchuk explains, the threat posed by C'Thun and the qiraji threatens to destroy all mortal life across Kalimdor. Facing an entity that despises all creatures born of the Titans, both factions have agreed to a collective war effort to ensure mutual survival.",al={"horde alliance cooperation","why work with alliance","ahn'qiraj truce"}},{q="How can players check the progress of the War Effort?",a="Speaking directly with Warlord Gorchuk provides up-to-date accounting on every required material, detailing exactly how many bars, herbs, bandages, skins, and fish the Horde has amassed toward its final goal.",al={"check war effort status","how much copper turned in","gorchuk dialogue status"}}},ang={["faction:Horde"]="Warlord Gorchuk embodies the Horde's collective resolve, rallying orcs, trolls, tauren, and Forsaken to pool their labor and defend Kalimdor from total annihilation."},kw={"ahn'qiraj","c'thun","gorchuk","orgrimmar","silithus","valley of spirits","war effort","warlord gorchuk"},rel={"zone:orgrimmar","zone:silithus","subzone:valley-of-spirits","subzone:scarab-dais","npc:field-marshal-snowfall","topic:old-god","topic:titan","topic:horde"},src={"Warlord Gorchuk"}}
E["npc:zamja"] = {t="npc",n="Zamja",z="orgrimmar",s="Zamja is a Darkspear troll cooking trainer found working in the bustling corridor of the Drag in Orgrimmar. Known for her steady hand with a meat cleaver, she instructs Horde adventurers in preparing hearty meals from the beasts of Kalimdor.",h="Zamja is a Darkspear troll cooking trainer found working in the bustling corridor of the Drag in Orgrimmar.",sec={{t="A Cleaver in the Drag",b="Stationed within the winding canyon path of the Drag, Zamja spends her days breaking down cuts of meat and teaching hungry Horde travelers how to sustain themselves. Practical cooking is a vital survival skill in the rugged terrain of Durotar and the Barrens, and Zamja ensures that anyone willing to hold a skillet learns the basics of turning raw game into wholesome rations. For cooks who have mastered basic recipes and seek further training, she directs them south toward Gadgetzan.",sp=0}},faq={{q="Who is Zamja?",a="Zamja is a Darkspear troll cooking trainer situated in the Drag in Orgrimmar. She teaches culinary arts to members of the Horde and helps budding cooks refine their craft.",al={"zamja npc","who is zamja","zamja orgrimmar"}},{q="Where can I find Zamja?",a="She can be found in the Drag, the shaded, winding trench connecting the Valley of Strength to the Valley of Honor within Orgrimmar.",al={"zamja location","where is zamja","zamja trainer spot"}},{q="What training does Zamja offer?",a="Zamja provides cooking training and teaches recipes that allow adventurers to prepare sustenance from beasts and game gathered throughout Kalimdor. When a cook advances far enough, she also directs them toward more advanced instructors.",al={"what does zamja teach","zamja cooking recipes","cooking trainer orgrimmar"}},{q="Where does Zamja send advanced cooks?",a="Once a chef's skills outgrow the local training available in Orgrimmar, Zamja directs them to Gadgetzan in Tanaris via the quest 'To Gadgetzan You Go!' to seek out Dirge Quikcleave.",al={"zamja quest","to gadgetzan you go quest","expert cooking horde"}}},ang={["profession:Cooking"]="Zamja is one of the primary cooking trainers for Horde characters visiting Orgrimmar, teaching essential recipes and eventually pointing seasoned cooks south to Tanaris for advanced instruction.",["race:Troll"]="Like many Darkspear trolls who have settled in Orgrimmar under Warchief Thrall's banner, Zamja brings troll resourcefulness and culinary craft to the heart of the Horde capital."},kw={"cooking trainer","darkspear","orgrimmar","the drag","to gadgetzan you go","troll","zamja"},rel={"zone:orgrimmar","subzone:drag","quest:6611","subzone:gadgetzan","topic:troll"},src={"Zamja"}}
E["npc:zankaja"] = {t="npc",n="Zankaja",z="orgrimmar",s="Zankaja is a young orc woman living in Orgrimmar, residing along the path between the Valley of Strength and the Valley of Wisdom. She anxiously awaits news of her mate, Dogran, who was assigned to duty at the Crossroads in the dangerous frontier of the Barrens.",h="Zankaja is a young orc woman living in Orgrimmar, residing along the path between the Valley of Strength and...",sec={{t="A Watchful Heart",b="Life in the fledgling Horde capital is demanding, but for Zankaja, the true ordeal is the waiting. Her mate Dogran earned a promotion that sent him south into the Barrens to bolster the outpost at the Crossroads. While an honor for a warrior, the Barrens is a brutal expanse crawling with quilboar, centaur, and aggressive beasts. When Dogran failed to send word or return home as expected, Zankaja began seeking out travelers willing to seek news of his fate.",sp=0},{t="Tragic Tidings",b="Zankaja's worst fears prove warranted when inquiries in the Barrens uncover that Dogran fell into the clutches of the Razormane quilboar. Though she holds onto hope within Orgrimmar's canyon walls, the frontier is unforgiving, and the news brought back by adventurers paints a grim picture of sacrifice on the Horde's perilous borders.",sp=1}},faq={{q="Where can I find Zankaja?",a="Zankaja stands along the path connecting the Valley of Strength and the Valley of Wisdom in the city of Orgrimmar.",al={"zankaja location","where is zankaja","find zankaja"}},{q="Who is Dogran?",a="Dogran is Zankaja's mate. He is an orc warrior whose recent promotion earned him a station at the Crossroads in the Barrens.",al={"who is dogran","dogran","zankaja mate"}},{q="Why is Zankaja worried?",a="Dogran was sent into the harsh wilds of the Barrens for his duties at the Crossroads and failed to return or send word home, leading Zankaja to fear he met harm along the frontier.",al={"what does zankaja want","zankaja problem","why is zankaja sad"}},{q="What does Zankaja ask adventurers to do?",a="She asks passing adventurers traveling out of Orgrimmar to visit Captain Gazrog at the Crossroads to inquire about Dogran's whereabouts and wellbeing.",al={"zankaja quest","news of dogran quest"}},{q="What happened to Dogran in the Barrens?",a="Dogran was wounded and taken prisoner by the Razormane quilboar near the Crossroads, news his comrades at the outpost would rather keep from Zankaja.",al={"is dogran dead","dogran fate","what happened to dogran"},sp=1}},ang={["race:Orc"]="Zankaja embodies the personal cost borne by ordinary families in Durotar, where duty to the Warchief's new realm regularly sends loved ones into untamed, lethal frontiers.",["faction:Horde"]="Her plea reminds Horde adventurers that holding outposts like the Crossroads requires real blood and sacrifice from the grunts stationed there."},kw={"barrens","crossroads","dogran","gazrog","orgrimmar","valley of strength","valley of wisdom","zankaja"},rel={"quest:1509","quest:1508","npc:gazrog","zone:barrens","subzone:crossroads","zone:orgrimmar","subzone:valley-of-strength"},src={"Zankaja"}}
E["npc:zevrost"] = {t="npc",n="Zevrost",z="orgrimmar",s="Zevrost is an orc warlock trainer secluded within the subterranean Cleft of Shadow beneath Orgrimmar. He mentors developing warlocks of the Horde, guiding them through the hazardous disciplines of fel magic, summoning rituals, and binding dark artifacts.",h="Zevrost is an orc warlock trainer secluded within the subterranean Cleft of Shadow beneath Orgrimmar.",sec={{t="Master of the Dark Arts",b="Tucked away deep in the caverns of the Cleft of Shadow, Zevrost is one of the principal mentors for Horde warlocks residing in Thrall's capital. While the broader orcish society remains wary of fel energies following the demonic corruption of their past, practitioners like Zevrost are tolerated under strict watch. He instills in his pupils the harsh discipline required to command demonic forces without succumbing to their corruptive nature, asserting that the fel only ruins those lacking inner strength.",sp=0},{t="Guiding the Ambitious",b="Beyond basic instruction in spells and curses, Zevrost acts as a conduit for more ambitious dark undertakings. Initiates seeking advanced implements—such as the Orb of Orahil or the means to summon a fiery Felsteed—frequently pass through his hands. He directs aspirational practitioners to other masters of the craft, such as Menara Voidrender in the Barrens, ensuring that those who wield shadow magic push their capabilities to their absolute limits.",sp=0}},faq={{q="Who is Zevrost?",a="Zevrost is an orc warlock trainer stationed in the Cleft of Shadow beneath Orgrimmar. He teaches novice and experienced Horde warlocks new incantations and guides them on pivotal class rituals.",al={"zevrost role","who is zevrost","zevrost npc"}},{q="Where can Zevrost be found?",a="He resides in the subterranean cavern known as the Cleft of Shadow, located beneath the main districts of Orgrimmar.",al={"zevrost location","where is zevrost","find zevrost"}},{q="Why are warlocks like Zevrost permitted in Orgrimmar?",a="While Thrall's Horde strictly regulates and monitors dark sorcery due to the orcs' history with demon blood, warlocks are permitted to practice in the secluded depths of the Cleft of Shadow to provide valuable, ruthless power against the Horde's many enemies.",al={"why are warlocks allowed in orgrimmar","warlock cleft of shadow"}},{q="What is Zevrost's philosophy on demonic magic?",a="Zevrost believes that dark and arcane energies only corrupt those who are weak of will. He urges his students to maintain rigid discipline in their studies lest they succumb to the destructive forces they command.",al={"zevrost quote","zevrost belief"}}},ang={["class:Warlock"]="For Horde warlocks, Zevrost is a vital instructor, unlocking advanced spells and setting initiates on quests to secure specialized weapons, off-hands, and their fiery steed.",["race:Orc"]="Living among an orcish society that largely shuns demonic magic, Zevrost represents those practitioners who still harness dark arts under the heavy scrutiny of the Warchief."},kw={"cleft of shadow","fel magic","felsteed","orgrimmar","trainer","warlock","zevrost"},rel={"subzone:cleft-of-shadow","zone:orgrimmar","npc:menara-voidrender","quest:4736","topic:horde"},src={"Zevrost"}}
E["npc:zor-lonetree"] = {t="npc",n="Zor Lonetree",z="orgrimmar",s="Zor Lonetree is a knowledgeable orc advisor found within Grommash Hold in Orgrimmar. Well-versed in external affairs and Alliance politics, he aids the Horde by analyzing enemy artifacts and directing travelers to troubled regions across Kalimdor.",h="Zor Lonetree is a knowledgeable orc advisor found within Grommash Hold in Orgrimmar.",sec={{t="Advisor in Grommash Hold",b="Stationed within Grommash Hold alongside the Horde's high leadership, Zor Lonetree serves as a shrewd advisor who keeps a watchful eye on developments beyond Durotar. He possesses an unusually keen understanding of human and Alliance politics, making him an invaluable counselor when foreign curiosities or political threats reach the capital. From inspecting noble jewelry recovered from human settlements to monitoring disturbances among the land's spirits in Stonetalon Mountains, Lonetree ensures the warchief's court stays informed on matters both mundane and mystical.",sp=0}},faq={{q="Who is Zor Lonetree?",a="Zor Lonetree is an orc advisor stationed inside Grommash Hold in Orgrimmar. He is known for his intellect, understanding of Alliance political structures, and interest in Kalimdor's spiritual matters.",al={"zor lonetree who is he","who is zor","zor orgrimmar"}},{q="Where can I find Zor Lonetree?",a="You can find him standing inside Grommash Hold, located in the Valley of Wisdom at the heart of Orgrimmar.",al={"zor lonetree location","where is zor lonetree","zor in orgrimmar"}},{q="What tasks does Zor Lonetree give adventurers?",a="Zor Lonetree directs Horde champions to assist the spirits of Stonetalon Peak, dispatching travelers to soothe the elemental unrest in the Stonetalon Mountains. He also analyzes strange human relics brought to the capital by scouts.",al={"zor lonetree quests","the spirits of stonetalon zor"}},{q="Why is Zor Lonetree knowledgeable about the Alliance?",a="Unlike many frontline warriors, Zor specializes in foreign affairs and statecraft. He studies human aristocratic customs and Alliance movements, allowing him to decipher noble signets, regalia, and tactical motives that other orcs might overlook.",al={"zor lonetree alliance lore","why does zor know alliance politics"}}},ang={["faction:Horde"]="For Horde scouts operating near human enclaves or disputed borderlands, Zor Lonetree serves as a vital contact in Orgrimmar for interpreting enemy intentions and relics.",["class:Shaman"]="Shaman who heed the call of disturbed elemental forces will find common cause with Zor, who pays close attention to the suffering spirits of the Stonetalon Mountains."},kw={"advisor","alliance politics","grommash hold","orgrimmar","stonetalon","valley of strength","zor lonetree"},rel={"subzone:grommash-hold","zone:orgrimmar","subzone:valley-of-strength","quest:1061","zone:stonetalon","topic:horde","topic:alliance"},src={"Zor Lonetree"}}
E["quest:1061"] = {t="quest",n="The Spirits of Stonetalon",z="orgrimmar",s="The Spirits of Stonetalon is a Horde courier quest initiated by the orc advisor Zor Lonetree in Orgrimmar. He detects deep unrest among the earth spirits across the western crags and dispatches young champions into the Stonetalon Mountains. Traveling west past the Crossroads, adventurers report directly to Seereth Stonebreak near the Greatwood Vale to address rampant logging.",h="The Spirits of Stonetalon is a Horde courier quest initiated by the orc advisor Zor Lonetree in Orgrimmar.",sec={{t="A Cry from the West",b="In the Valley of Wisdom within Orgrimmar, Zor Lonetree communes with the natural world and senses profound distress emanating from the Stonetalon Mountains. The elemental spirits of the rocky peaks have grown furious as industrial exploitation tears into their forests. Listening to their distress, the shamans of the Horde recognize that unbridled devastation in the western highlands threatens the spiritual balance of Kalimdor.",sp=0},{t="Industrial Deforestation",b="The primary threat in the region stems from the Venture Company, an unscrupulous goblin syndicate clear-cutting timber in Greatwood Vale. Rather than harvesting sustainably, these commercial crews employ aggressive machinery, saws, and muscle to butcher the ancient woodland. To investigate this assault, the Horde dispatched Seereth Stonebreak, an insightful young shaman stationed on the frontier to monitor the forest and rally defenders against the ravagers.",sp=0}},faq={{q="Who starts this quest and where are they located?",a="The quest is offered by Zor Lonetree, a wise orc advisor found in Grommash Hold in the Horde capital of Orgrimmar.",al={"quest giver","where get quest","zor lonetree location"}},{q="Where can I find Seereth Stonebreak?",a="Seereth Stonebreak is stationed in the Stonetalon Mountains, along the path near the Greatwood Vale just past the eastern entrance leading from the northern Barrens.",al={"seereth location","where is seereth stonebreak","stonetalon camp"}},{q="Why are the spirits of Stonetalon angry?",a="Goblins—specifically those working for the Venture Company—are violently clear-cutting the pristine mountain woods, scarring the wilderness and provoking the land's ancient elemental guardians.",al={"why are spirits mad","stonetalon unrest","angry spirits"}},{q="How do I reach the Stonetalon Mountains from Orgrimmar?",a="Leave Orgrimmar and journey south across the Barrens to the Crossroads, then take the westward road that climbs through the rocky pass directly into Stonetalon.",al={"path to stonetalon","how to get to stonetalon","route to stonetalon"}},{q="What comes next after speaking with Seereth?",a="Upon arriving at her camp, Seereth Stonebreak assigns you 'Goblin Invaders', sending you into the woods of Greatwood Vale to eliminate loggers and cut down their operations directly.",al={"next quest","followup","what after spirits of stonetalon"}},{q="Why is the Horde intervening in Stonetalon's deforestation?",a="The tauren and orc shamans hold a sacred reverence for the elemental spirits. Allowing reckless goblin strip-logging damages the land's spiritual harmony and poses a threat right along the borders of the Barrens.",al={"why does horde care","tauren stonetalon interest"}}},ang={["class:Shaman"]="For shamans, this summons is a direct plea from the elements itself, calling upon spiritual practitioners to mend a fractured bond between the earth and the living.",["race:Tauren"]="Tauren adventurers feel a heavy cultural obligation to soothe the weeping earth and defend sacred forests from wanton goblin exploitation.",["faction:Horde"]="Securing the borders between Stonetalon and the Barrens ensures Horde travel corridors remain free from rogue commercial syndicates."},kw={"crossroads","deforestation","greatwood vale","seereth stonebreak","stonetalon mountains","valley of wisdom","venture company","zor lonetree"},rel={"quest:1062","npc:seereth-stonebreak","npc:zor-lonetree","zone:stonetalon","subzone:greatwood-vale","zone:barrens","subzone:crossroads","topic:goblin"},m={start="Zor Lonetree",["end"]="Seereth Stonebreak",level="17",faction="Horde",id=1061},src={"The Spirits of Stonetalon"}}
E["quest:1361"] = {t="quest",n="Regthar Deathgate",z="orgrimmar",s="This directive dispatches seasoned Horde champions from major capitals to reinforce an outpost in the western Barrens. The veteran warrior Regthar Deathgate is marshaling capable volunteers for an impending campaign across the mountains into the arid wastes of Desolace. He seeks those willing to carry Horde steel against the entrenched centaur clans terrorizing the frontier.",h="This directive dispatches seasoned Horde champions from major capitals to reinforce an outpost in the western...",sec={{t="Call of the Warchief's Lieutenants",b="Across Kalimdor, influential leaders of the Horde—including Shadow Hunter Vol'jin, Nazgrel, and seasoned commanders like Belgrom Rockmaul—keep a watchful eye on potential threats along the borders. In the Barrens, an experienced warrior named Regthar Deathgate has established a defensive post guarding the western passes. Recognizing that regional skirmishes require hardened fighters rather than raw recruits, Horde officers direct proven adventurers west of the Crossroads to answer Regthar's call.",sp=0},{t="The Road to Desolace",b="Regthar Deathgate is stationed within the fortified redoubt bunkered along the ridges west of the Crossroads. From this vantage point, he monitors the western mountain trails that wind into the desolate badlands of Desolace. His mandate is direct and unyielding: assemble an expeditionary vanguard capable of braving hostile terrain to strike directly at the heart of the Kolkar and other warring centaur clans before their violent expansion threatens Horde territory.",sp=0}},faq={{q="Who is Regthar Deathgate?",a="Regthar Deathgate is an orc warrior and Horde commander stationed in the Barrens. Tasked with frontier security, he coordinates reconnaissance and military strikes into the dangerous, ash-choked expanse of Desolace.",al={"who is regthar","regthar deathgate lore","who is the questgiver"}},{q="Where is Regthar Deathgate located?",a="He can be found in the Barrens, stationed inside the fortified Horde bunkers on the hill path directly west of the Crossroads, overlooking the western mountain pass.",al={"where is regthar","regthar location","find regthar deathgate"}},{q="Who gives the quest to seek out Regthar?",a="Several prominent Horde leaders and military figures offer this assignment, including Shadow Hunter Vol'jin in Sen'jin Village, Nazgrel and Belgrom Rockmaul in Orgrimmar, and Krusk.",al={"who starts regthar deathgate","where to get regthar quest"}},{q="What is the primary objective of Regthar's mission?",a="Regthar is recruiting able warriors to cross the mountains into Desolace and launch an offensive against the hostile centaur clans, particularly targeting the Kolkar.",al={"what does regthar want","regthar deathgate purpose"}},{q="Why is the Horde concerned with Desolace?",a="Desolace is a war-torn wilderness overrun by aggressive centaur clans. Leaving them unchecked risks letting their raids spill across the mountain passes into the Barrens and neighboring Horde settlements.",al={"why go to desolace","horde interest in desolace"}},{q="What comes next after speaking with Regthar Deathgate?",a="Once you report to Regthar, he immediately briefs you on the situation beyond the western mountains and tasks you with your first strike across the border in the quest 'The Kolkar of Desolace'.",al={"next quest after regthar","regthar follow up"}}},ang={["faction:Horde"]="This mission represents the Horde's proactive frontier defense, ensuring aggressive centaur populations in neighboring Desolace are subdued before they can raid deeper into the Barrens.",["race:Tauren"]="Having endured generations of brutal conflict against the centaur across central Kalimdor, tauren warriors have a personal stake in aiding Regthar's strike against the Kolkar.",["class:Warrior"]="Regthar values straightforward combat prowess and unflinching discipline, making his call to arms a natural trial for frontline warriors eager to test their mettle in hostile badlands."},kw={"belgrom rockmaul","crossroads","desolace","kolkar","krusk","nazgrel","regthar deathgate","the barrens","vol'jin"},rel={"quest:1362","zone:desolace","zone:barrens","subzone:crossroads","topic:centaur","topic:horde"},m={start="Krusk, Belgrom Rockmaul, Nazgrel, Vol'jin",["end"]="Regthar Deathgate",level="32",faction="Horde",id=1361},src={"Regthar Deathgate (quest)"}}
E["quest:1431"] = {t="quest",n="Alliance Relations",z="orgrimmar",s="Alliance Relations is an introductory quest offered by Craven Drok in Orgrimmar. It directs seasoned Horde adventurers to seek out Keldran, a mystic operating quietly near the city's western exit. The task opens a conversation about the delicate, behind-the-scenes diplomacy and intelligence work required to maintain Thrall's fragile peace with the Alliance.",h="Alliance Relations is an introductory quest offered by Craven Drok in Orgrimmar.",sec={{t="A Diplomatic Dilemma",b="While many orcs favor brute strength and straightforward conquest, Warchief Thrall understands that endless war with the Alliance would ruin his young nation. Having grown up in human captivity, Thrall learned the subtle nuances of human statecraft and military strategy. Craven Drok notices warriors and champions who might possess the patience for a more nuanced approach, directing them to look beyond raw force.",sp=0},{t="Keldran's Hovel",b="Tucked away near the western gates of Orgrimmar sits the humble dwelling of Keldran, a practitioner of magic and covert arts. Unlike the boisterous warriors drinking in the Valley of Strength, Keldran deals in appearances, perception, and statecraft. He seeks operatives capable of exercising discretion on behalf of the Warchief, navigating the tense standoff between the Horde and its bitter rivals.",sp=0}},faq={{q="Who gives the quest Alliance Relations?",a="Craven Drok offers this quest in Orgrimmar to Horde adventurers who have reached their thirtieth season of experience.",al={"quest giver alliance relations","who starts alliance relations","where to get alliance relations"}},{q="Where can I find Keldran?",a="Keldran resides in a small hovel situated near the western exit of Orgrimmar, away from the bustling center of the city.",al={"keldran location","where is keldran","keldran orgrimmar"}},{q="What is Keldran's role in Orgrimmar?",a="Keldran is a student of magic and mystical arts who assists Warchief Thrall with discreet matters, particularly those concerning diplomacy, intelligence, and the public perception of the Horde.",al={"who is keldran","keldran lore"}},{q="Why does Thrall care about diplomacy with the Alliance?",a="Thrall was raised among humans and understands their politics and military power intimately. Knowing that outright war could destroy his fledgling people, he chooses prudence and measured statecraft to protect the Horde's future.",al={"thrall diplomacy","why horde peace with alliance","thrall and humans"}},{q="Does this quest lead to further missions?",a="Yes, turning in this errand to Keldran begins a deeper dialogue regarding the Horde's standing with other factions, leading directly into subsequent tasks dealing with regional diplomacy and espionage.",al={"alliance relations followup","what comes after alliance relations"}},{q="Why is discretion so important for this task?",a="Open conflict with the Alliance risks massive casualties and destabilizing Kalimdor. Thrall relies on subtle operatives to handle sensitive diplomatic friction before it erupts into open war.",al={"why subtlety","keldran subtlety"}}},ang={["faction:Horde"]="This mission highlights the ideological contrast inside the Horde between traditional brute strength and Thrall's nuanced, diplomatic statecraft.",["race:Orc"]="For orcs accustomed to resolving conflict by the axe, Keldran's approach demands an unfamiliar discipline: patience and tactical subtlety.",["class:Rogue"]="Keldran's focus on secrecy and perception makes his tasks particularly suited to those who make their living in the shadows."},kw={"alliance relations","craven drok","diplomacy","horde","keldran","orgrimmar","thrall"},rel={"npc:keldran","npc:craven-drok","npc:thrall","zone:orgrimmar","topic:horde"},m={start="Craven Drok",["end"]="Keldran",level="30",faction="Horde",id=1431},src={"Alliance Relations"}}
E["quest:1432"] = {t="quest",n="Alliance Relations",z="orgrimmar",s="Alliance Relations is a Horde assignment dispatched from Orgrimmar to Desolace to prevent dangerous political fallout. With the Alliance pushing deeper into central Kalimdor, the Horde moves proactively to purge regional Burning Legion forces before rivals can accuse Thrall's people of renewed demonic corruption.",h="Alliance Relations is a Horde assignment dispatched from Orgrimmar to Desolace to prevent dangerous political...",sec={{t="A Matter of Perception",b="As Alliance scouts and expeditions venture across Kalimdor, Horde leadership faces a delicate diplomatic threat. The presence of demonic remnants scattered across central Kalimdor risks confirming old prejudices that the orcs and their allies remain in league with the Burning Legion. Acting with Warchief Thrall's sanction, Keldran in Orgrimmar oversees targeted operations to ensure these demonic remnants are wiped out before hostile Alliance factions can twist their presence into justification for war.",sp=0},{t="Outpost in the Wastes",b="Carrying orders southward requires passing through the Charred Vale of the Stonetalon Mountains down into the bleak expanse of Desolace. There, just north of the vast Kodo Graveyard, lies Ghost Walker Post. Horde agents like Takata Steelblade monitor the desolate wilderness, navigating both the rampant centaur tribes and the pervasive demonic corruption that threatens to overrun the region.",sp=0},{t="Pragmatic Alliances",b="Takata Steelblade regards the assignment with grim pragmatism. Though wiping out the local demons inevitably relieves pressure on the violent native centaur tribes and even assists the Horde's resident warlocks, the duty takes precedence. Eliminating the Burning Legion's footholds serves the broader security of the Horde, regardless of who else might profit from the culling.",sp=1}},faq={{q="Why is the Horde concerned about the Alliance here?",a="As Alliance forces advance across Kalimdor, Horde leadership worries that active demon infestations might be used as proof that the Horde still consorts with the Burning Legion. By actively purging local demons, the Horde seeks to disarm those accusations.",al={"why worry about alliance","horde alliance relations desolace","alliance accusations"}},{q="Who is Keldran?",a="Keldran is a Horde operative based in Orgrimmar who oversees specialized missions with the Warchief's approval, focused on eliminating demonic elements that endanger the Horde's standing.",al={"keldran","who is keldran","keldran orgrimmar"}},{q="Where is Ghost Walker Post located?",a="Ghost Walker Post is an encampment in northern Desolace, situated directly south of the pass from the Charred Vale in the Stonetalon Mountains and just north of the Kodo Graveyard.",al={"ghost walker post location","where is takata steelblade","finding ghost walker post"}},{q="Who is Takata Steelblade?",a="Takata Steelblade is a Horde soldier stationed at Ghost Walker Post in Desolace, tasked with keeping regional threats like demons and hostile centaur in check on behalf of the Warchief.",al={"takata steelblade","who is steelblade","steelblade desolace"}},{q="Why does Takata mention aiding the centaur?",a="The centaur claim Desolace as their territory but lack the strength to contain the growing demon threat. By culling the local demons, the Horde unintentionally helps the centaur survive, a compromise Takata accepts purely for the Horde's greater security.",al={"helping centaur","centaur desolace","why aid centaur"}},{q="How do warlocks tie into this mission?",a="While the mission roots out wild demons, Takata notes with some distaste that clearing demonic reagents and influence inevitably intersects with and assists the controversial warlocks who operate within the Horde.",al={"warlock connection","why help warlocks","warlocks in the horde"}}},ang={["faction:Horde"]="The mission reflects Warchief Thrall's ongoing struggle to legitimize the new Horde and bury the legacy of demonic servitude before hostile neighbors can exploit it.",["class:Warlock"]="While regular soldiers like Takata Steelblade view dark powers with suspicion, operations targeting wild demons frequently cross paths with the Horde's pragmatic use of warlock practitioners.",["race:Orc"]="For orcs striving to honor Thrall's vision of redemption, any lingering hint of demonic taint in Kalimdor is a bitter threat to their hard-won freedom."},kw={"alliance relations","burning legion","charred vale","desolace","ghost walker post","keldran","kodo graveyard","takata steelblade"},rel={"quest:1431","npc:keldran","npc:takata-steelblade","subzone:ghost-walker-post","zone:desolace","topic:burning-legion","subzone:charred-vale","subzone:kodo-graveyard"},m={start="Keldran",["end"]="Takata Steelblade",level="30",faction="Horde",id=1432},src={"Alliance Relations (2)"}}
E["quest:1501"] = {t="quest",n="Creature of the Void",z="orgrimmar",s="Creature of the Void is a pivotal rite of passage for young Horde warlocks training in Orgrimmar. Seeking to expand an initiate's summoning mastery to call forth a voidwalker, Gan'rul Bloodeye tasks the warlock with recovering the stolen Tablet of Verga from the rogue cultists of the Burning Blade hiding in Skull Rock.",h="Creature of the Void is a pivotal rite of passage for young Horde warlocks training in Orgrimmar.",sec={{t="A Precarious Art",b="In the subterranean shadows of Orgrimmar's Cleft of Shadow, Gan'rul Bloodeye watches over the Horde's practicing warlocks. Fel magic is viewed with deep wariness in Thrall's new realm, tainted as it is by the dark history of the orcish clans. Gan'rul acknowledges that few true warlocks remain within the Horde, yet he insists their perilous skills are essential for the Horde's survival. To be useful to the Warchief, an initiate cannot rely solely on the chaotic fire of an imp; they must learn to command beings of pure shadow and endurance.",sp=0},{t="The Stolen Tablet",b="Summoning a voidwalker requires specialized runes inscribed upon the Tablet of Verga. Unfortunately, the relic was plundered by the Burning Blade, a fanatical shadow cult operating right beneath the Warchief's nose in the cavern of Skull Rock. Gan'rul sends his student to strike into the cultists' den, retrieve the tablet, and deal a bloody blow to the renegades who cast a stain upon all practicing warlocks.",sp=0}},faq={{q="Who is Gan'rul Bloodeye?",a="Gan'rul Bloodeye is a senior warlock trainer located in the Cleft of Shadow beneath Orgrimmar. He oversees the instruction of young Horde warlocks, teaching them how to safely harness dark powers and bind otherworldly minions without falling prey to corruption.",al={"gan'rul","ganrul bloodeye","who gives this quest"}},{q="What is the Tablet of Verga?",a="The Tablet of Verga is a relic etched with specialized summoning runes needed to call forth a voidwalker from the Nether. Stolen by the Burning Blade cult, it must be reclaimed so Gan'rul can guide the initiate through the ritual.",al={"tablet of verga","verga tablet","what is the tablet"}},{q="Where is Skull Rock?",a="Skull Rock is a shadowy cavern located directly east of Orgrimmar, along the rugged bluffs of Durotar. It serves as a hidden hideout for cultists of the Burning Blade.",al={"skull rock location","where is skull rock","where to find tablet"}},{q="Why does Gan'rul Bloodeye despise the Burning Blade?",a="The Burning Blade cult openly serves demonic masters and actively undermines Thrall's Horde. Gan'rul views them as an intolerable nuisance to the Warchief and a reckless blight that brings suspicion and disrepute onto all practicing warlocks.",al={"burning blade warlock","why hate burning blade"}},{q="Why do warlocks need to summon a voidwalker?",a="Voidwalkers are beings of the Nether capable of absorbing tremendous punishment and protecting their summoner from harm. Mastering the binding of a voidwalker marks an essential leap in a warlock's practical survival and summoning power.",al={"why voidwalker","voidwalker purpose"}},{q="What happens after retrieving the tablet?",a="Once Gan'rul receives the Tablet of Verga, he provides the initiate with the necessary runes and summons them to complete the ritual in 'The Binding', where the warlock must physically subdue the summoned voidwalker to master it.",al={"next quest","what comes next"},sp=1}},ang={["class:Warlock"]="This trial marks a fundamental rite of passage for Horde warlocks, graduating them from small imps to commanding frontline shadow minions.",["faction:Horde"]="While Thrall's Horde generally distrusts fel practitioners, mentors like Gan'rul work to ensure that those who study the dark arts use their power strictly in service to the Warchief.",["race:Orc"]="For orcs haunted by their history with the Shadow Council, hunting down the Burning Blade offers a measure of vengeance against those who still embrace demonic ruin."},kw={"burning blade","cleft of shadow","creature of the void","gan'rul bloodeye","orgrimmar","skull rock","tablet of verga","voidwalker","warlock quest"},rel={"npc:gan-rul-bloodeye","quest:1506","quest:1471","quest:827","zone:orgrimmar","topic:horde"},m={start="Gan'rul Bloodeye",level="11",faction="Horde",id=1501},src={"Creature of the Void (Orgrimmar)"}}
E["quest:1504"] = {t="quest",n="The Binding",z="orgrimmar",s="The Binding is the final initiation ritual in Orgrimmar for young Horde warlocks seeking command over a voidwalker. Under the direction of Gan'rul Bloodeye, the petitioner inscribes glyphs from the Tablet of Verga within Neeru Fireblade's summoning circle to call forth, subdue, and perpetually enslave a creature of the Void.",h="The Binding is the final initiation ritual in Orgrimmar for young Horde warlocks seeking command over a...",sec={{t="Subjugation of the Void",b="For an initiate warlock lurking in the dark tunnels of the Cleft of Shadows, summoning an imp is merely child's play. Subduing a voidwalker is the first true test of willpower and arcane dominance. Warlocks do not form polite pacts or commune with these otherworldly horrors; they wrest them across dimensions through raw force and bind them in eternal servitude. Gan'rul Bloodeye demands that the initiate draw upon the glyphs transcribed from the Tablet of Verga, calling the monstrosity directly into Neeru Fireblade's ritual circle to break it in single combat.",sp=0},{t="An Unending Vigil",b="Overcoming the entity in physical and magical combat is only half the battle. As Gan'rul Bloodeye warns, a bound voidwalker never truly accepts its enslavement. Though it serves its master as a durable, shadowy bulwark in battle, it perpetually searches for lapses in concentration. A warlock must maintain an unwavering mental grip over their servant, for the moment discipline falters, the voidwalker will happily consume the soul of the one who bound it.",sp=0}},faq={{q="What kind of creature is being summoned?",a="The initiate summons a voidwalker, a towering being forged of pure cosmic shadow and void energies. Unlike imps, which are mischievous demons, voidwalkers are brutish entities ripped from the Twisting Nether and the Void, utilized by warlocks primarily to absorb devastating physical blows.",al={"what is summoned","what demon","voidwalker lore"}},{q="Where does this summoning ritual take place?",a="The ritual is carried out inside the tent of Neeru Fireblade, located within the Cleft of Shadows beneath Orgrimmar. A designated summoning circle inscribed on the ground focuses the dimensional energies needed to tear the voidwalker from the Nether.",al={"where do i summon","summoning circle location","ritual site"}},{q="What is the Tablet of Verga used for?",a="The Tablet of Verga holds the ancient, specialized glyphs required to manifest and tear a voidwalker through the fabric of reality. The initiate studies its inscriptions to craft the Glyphs of Summoning needed to establish the summoning circle.",al={"tablet of verga","glyphs of summoning"}},{q="Why must the warlock defeat the voidwalker?",a="Warlocks control extraplanar creatures through sheer dominance. Before a voidwalker will yield its essence and obey commands, the summoner must prove their mastery by physically and magically beating the entity into submission.",al={"why kill the voidwalker","why fight it","binding process"}},{q="Who is Gan'rul Bloodeye?",a="Gan'rul Bloodeye is a senior warlock trainer of the Horde stationed in the shadowy caverns of Orgrimmar's Cleft of Shadows. He oversees the dark education of young orc and troll practitioners, teaching them how to enslave more potent demonic entities.",al={"who is ganrul","gan'rul bloodeye"}},{q="Can a bound voidwalker ever be fully trusted?",a="Never. As Gan'rul notes, even a voidwalker that has served for years without resistance is merely waiting for its master to let their guard down. The bond demands constant vigilance, as the creature harbors eternal resentment toward its captor.",al={"will voidwalker turn on me","is voidwalker loyal","can demons rebel"}}},ang={["class:Warlock"]="This rite marks a warlock's ascension from dabbling with petty imps to commanding frontline terrors of shadow, cementing the ruthless philosophy that power must be conquered and enslaved.",["race:Orc"]="Orcish warlocks operate in hidden corners like the Cleft of Shadows, practicing their dark arts far from the disapproving gaze of Warchief Thrall and the shamanic revival.",["faction:Horde"]="While Thrall's Horde officially turns away from the demonic corruption of the past, the pragmatic necessity of warlock magic is tolerated beneath Orgrimmar under watchful eyes."},kw={"cleft of shadows","gan'rul bloodeye","glyphs of summoning","neeru fireblade","orgrimmar","tablet of verga","the binding","voidwalker","warlock"},rel={"quest:1473","quest:1506","npc:gan-rul-bloodeye","quest:829","zone:orgrimmar","quest:1471"},m={start="Gan'rul Bloodeye",level="11",faction="Horde",id=1504},src={"The Binding (Voidwalker, Orgrimmar)"}}
E["quest:1506"] = {t="quest",n="Gan'rul's Summons",z="orgrimmar",s="Gan'rul's Summons is an urgent call delivered to young Horde warlocks by Ophek in Razor Hill. Senior warlock Gan'rul Bloodeye requires their immediate presence in the Cleft of Shadow to advance their training. It marks the first step toward mastering the dark art of summoning a voidwalker.",h="Gan'rul's Summons is an urgent call delivered to young Horde warlocks by Ophek in Razor Hill.",sec={{t="A Summons to the Shadows",b="Novice warlocks operating in Durotar do not remain unnoticed for long. Once a practitioner demonstrates sufficient mastery over their initial imp, word reaches the deeper subterranean recesses of Orgrimmar. Ophek, stationed out in Durotar, acts as a messenger for the senior dark casters, intercepting warlocks with an urgent demand to drop whatever they are doing and report to the Cleft of Shadow.",sp=0},{t="The Senior Warlock",b="Gan'rul Bloodeye oversees the training of nascent orc and troll warlocks within the Horde. Operating out of the hidden caverns beneath Orgrimmar, he maintains a delicate balance between honing lethal fel power and keeping such dangerous arts shielded from the disapproving gaze of the Warchief. When Bloodeye calls an apprentice to his circle, it signals that simple fire spells and imps are no longer enough; it is time to bind a creature from the Twisting Nether.",sp=0}},faq={{q="Who is Ophek?",a="Ophek is an associate of the warlocks stationed out in Durotar. He tracks rising practitioners and delivers orders from senior mentors like Gan'rul Bloodeye.",al={"ophek","who gives this quest","quest starter"}},{q="Where is Gan'rul Bloodeye located?",a="Gan'rul Bloodeye resides in the Cleft of Shadow, the dark subterranean cavern system hidden beneath the rocky plateaus of Orgrimmar.",al={"where is ganrul","gan'rul location","find gan'rul bloodeye"}},{q="Why does Gan'rul Bloodeye want to see me?",a="Gan'rul has deemed you experienced enough to advance your warlock studies and begin the dangerous rituals required to summon and bind a voidwalker.",al={"why summons","what does ganrul want","quest reason"}},{q="What happens after reporting to Gan'rul?",a="Reporting to Gan'rul begins the task 'Creature of the Void', which sends you to retrieve the necessary components and knowledge to pull a void entity into Azeroth.",al={"next quest","what comes after gan'rul's summons"}},{q="Why do the warlocks stay in the Cleft of Shadow?",a="Warlocks practice volatile fel magic, which Thrall and the traditional shamanic Horde view with deep suspicion. The Cleft of Shadow allows them to conduct rituals out of public view.",al={"why cleft of shadow","why are warlocks hiding","warlock cave orgrimmar"}},{q="Can any class take this quest?",a="No. This quest is exclusively offered to Horde warlocks who have reached the tenth circle of their training.",al={"is this warlock only","who gets this quest"}}},ang={["class:Warlock"]="This summons marks your progression past basic imp conjuration, opening the path to commanding the sturdy protection of a voidwalker.",["faction:Horde"]="Warlocks hold an uneasy place within Thrall's new Horde, tolerated for their pragmatic power but sequestered deep beneath Orgrimmar."},kw={"bloodeye","cleft of shadow","gan'rul","ophek","orgrimmar","summons","voidwalker","warlock quest"},rel={"npc:gan-rul-bloodeye","quest:1473","quest:1471","subzone:cleft-of-shadow","zone:orgrimmar"},m={start="Ophek",["end"]="Gan'rul Bloodeye",level="10",faction="Horde",id=1506},src={"Gan'rul's Summons"}}
E["quest:1507"] = {t="quest",n="Devourer of Souls",z="orgrimmar",s="Devourer of Souls is the opening task in an aspiring Horde warlock's journey to summon and command a succubus. Offered by Gan'rul Bloodeye deep within the Cleft of Shadow, the quest sends the practitioner across the cavern to consult the ancient warlock Cazul on how to lure and bind such a manipulative demon.",h="Devourer of Souls is the opening task in an aspiring Horde warlock's journey to summon and command a succubus.",sec={{t="A Step Into Seductive Shadows",b="Warlocks of the Horde who have mastered lesser demons like the imp and the voidwalker eventually reach a point where brute force is no longer enough. Gan'rul Bloodeye, overseer of dark arts beneath Orgrimmar, judges when a warlock is ready to reach into the Twisting Nether for a succubus—a creature notorious for turning the minds of the frail against themselves. Binding such a fiend requires subtle methods rather than sheer strength.",sp=0},{t="The Lore of Cazul",b="Because a succubus preys on mortal desires, it cannot be summoned by raw incantations alone; it must be baited into our world with an object imbued with pure love and devotion. Unwilling or unable to provide such a relic himself, Gan'rul directs the summoner to Cazul, an ancient warlock lurking within the Cleft of Shadow whose extensive knowledge of the arcane and demonic rites guides the next phase of the ritual.",sp=0}},faq={{q="What is the purpose of this quest?",a="Devourer of Souls initiates the Horde quest chain required to learn the ritual to summon a succubus minion. It connects you with mentors in the Cleft of Shadow who teach you the nature of the demon and how to lure one from the Twisting Nether.",al={"why do devourer of souls","succubus quest start","what does this quest unlock"}},{q="Where do I find Cazul?",a="Cazul is located within the Cleft of Shadow, the subterranean cavern hidden beneath Orgrimmar where the city's rogue and warlock trainers practice their forbidden arts away from the scrutiny of the Warchief.",al={"cazul location","where is cazul","find cazul orgrimmar"}},{q="Why does a warlock need an object of love to summon a succubus?",a="Succubi are demonic manipulators that feed upon mortal emotion, devotion, and weak will. To draw one across the veil of the Twisting Nether, a summoner must offer a potent talisman of genuine devotion and affection as bait before overpowering and binding the creature.",al={"succubus bait love","why love item for succubus","succubus summoning lore"}},{q="Who is Gan'rul Bloodeye?",a="Gan'rul Bloodeye is a senior warlock trainer of the Horde residing in Orgrimmar's Cleft of Shadow. He guides developing practitioners through the dangerous bindings of increasingly powerful demonic servants.",al={"who gives devourer of souls","gan'rul lore","ganrul bloodeye"}},{q="What level is required to begin this quest?",a="A warlock must reach level 20 before Gan'rul Bloodeye considers their magical prowess and mental fortitude sufficient to undertake the ritual and survive bargaining with a succubus.",al={"what level for succubus","devourer of souls level","succubus chain level req"}},{q="What follows after speaking with Cazul?",a="Speaking to Cazul leads into the quest 'Blind Cazul', which sends the summoner into the field across the Barrens and Stonetalon Mountains to locate a suitable token of love and find a captured grunt named Dogran.",al={"next quest after devourer of souls","what comes after cazul","succubus quest progression"},sp=1}},ang={["class:Warlock"]="This quest marks your transition into commanding demons of mental dominance and seduction, demanding psychological resolve as well as raw fel power.",["faction:Horde"]="Unlike the public shamans and warriors of Thrall's Horde, warlocks must conduct these dangerous rites hidden away within the damp, secluded crevices of the Cleft of Shadow."},kw={"binding","cazul","cleft of shadow","gan'rul bloodeye","orgrimmar","succubus","summoning","warlock"},rel={"npc:cazul","npc:gan-rul-bloodeye","subzone:cleft-of-shadow","quest:1508","quest:1509","quest:1515","quest:1512","quest:1471"},m={start="Gan'rul Bloodeye",["end"]="Cazul",level="20",faction="Horde",id=1507},src={"Devourer of Souls (Orgrimmar)"}}
E["quest:1508"] = {t="quest",n="Blind Cazul",z="orgrimmar",s="Blind Cazul is a transitional step in the Horde warlock trial to bind a succubus. After being directed by the coven leaders in the Cleft of Shadow, an initiate seeks out the sightless warlock Cazul, who points toward an object of intense emotion needed for the ritual.",h="Blind Cazul is a transitional step in the Horde warlock trial to bind a succubus.",sec={{t="A Matter of Enticement",b="Subjugating a demonic minion requires more than raw willpower; certain creatures of the Twisting Nether must be drawn across the veil by their innate cravings. A succubus, known as a devourer of souls, responds eagerly to mortal longing, sorrow, and unfulfilled desire. Cazul understands this well, recognizing immediately why an aspiring summoner has sought him out.",sp=0},{t="Eyes in the Bluffs",b="Despite his physical blindness, Cazul remains sharply attuned to the quiet lives and tragedies unfolding within Orgrimmar's red ramparts. Rather than sending the warlock directly to battle, he directs them to an orc woman named Zankaja living atop the bluffs near the wind rider roost. Zankaja has been anxiously waiting for the return of her mate, Dogran, harboring the very despair that demons find irresistible.",sp=0}},faq={{q="Who is Cazul?",a="Cazul is a sightless warlock who operates quietly in Orgrimmar. He assists the warlocks of the Cleft of Shadow by identifying reagents and conduits for demonic summonings.",al={"blind cazul","who is cazul"}},{q="Why does Cazul send you to Zankaja?",a="To summon and bind a succubus, an initiate requires an item steeped in powerful mortal yearning or love. Zankaja is waiting in distress for her missing mate, Dogran, making her personal connection the key to obtaining an emotional lure.",al={"why zankaja","what does zankaja have"}},{q="Where can Zankaja be found in Orgrimmar?",a="Zankaja resides on the elevated bluffs of Orgrimmar, west of the wind rider roost. She can be reached by crossing the bridge from the flight tower and checking the nearby dwellings to the right.",al={"zankaja location","where is zankaja"}},{q="What happens after speaking to Zankaja?",a="Zankaja is distressed because her mate Dogran has vanished. Speaking to her leads the warlock to search the Barrens for word of his fate, beginning the chain to retrieve a potent token of love.",al={"what comes next","next step after cazul"}},{q="What kind of demon is this quest preparing you to summon?",a="This errand is part of the initiation rite to summon and enslave a succubus, a demonic minion that wields seduction and psychic torment.",al={"which pet","demon reward"}},{q="Why must warlocks exploit personal tragedies for their rituals?",a="Lesser demons like the succubus are drawn to intense mortal emotions—particularly passion, devotion, and heartbreak. Warlocks deliberately harness tokens tainted by grief or desire to serve as spiritual bait during the summoning ritual.",al={"warlock morality","why use dogran"}}},ang={["class:Warlock"]="This task demonstrates that demonic conjuration relies on psychological resonance as much as fel magic, requiring conduits of intense mortal emotion to lure a succubus.",["faction:Horde"]="The dark arts practiced deep in the Cleft of Shadow operate just beneath the surface of the Horde capital, quietly touching the lives of ordinary citizens living on the mesas above."},kw={"blind cazul","cazul","cleft of shadow","dogran","orgrimmar","succubus","warlock","zankaja"},rel={"npc:cazul","npc:zankaja","quest:1472","quest:1509","quest:1515","quest:1512","quest:1471","zone:orgrimmar"},m={start="Cazul",["end"]="Zankaja",level="20",faction="Horde",id=1508},src={"Blind Cazul"}}
E["quest:1509"] = {t="quest",n="News of Dogran",z="orgrimmar",s="This quest sends Horde warlocks from the clefts of Orgrimmar into the dry expanses of the Barrens in search of a missing grunt named Dogran. His mate, Zankaja, fears the worst after days of silence, sending the practitioner to question Dogran's superior at the Crossroads. Unraveling Dogran's fate forms a crucial step in the warlock ritual to bind a succubus.",h="This quest sends Horde warlocks from the clefts of Orgrimmar into the dry expanses of the Barrens in search...",sec={{t="A Mate's Despair",b="On the bluffs of Orgrimmar, Zankaja waits in quiet dread. Her mate Dogran was assigned to the Crossroads on an honorable promotion, yet his scheduled return has long passed without a single word. Unaware of the intricate dark arts pulling strings behind the scenes, she reaches out to a sympathetic traveler to seek answers from his commander, Gazrog.",sp=0},{t="Grim Tidings in the Barrens",b="Reaching the central outpost of the Crossroads, the truth turns dark. Dogran is not merely delayed by duties; he has fallen into the hands of the ferocious quilboar infesting the plains. Gazrog acknowledges that while Dogran still lives, his capture presents a brutal reality he is hesitant to send back to Zankaja.",sp=1},{t="An Instrument of Summoning",b="For an aspiring warlock, Dogran's tragedy is not merely a rescue mission. The path to summoning and mastering a succubus—a creature bound by raw passion, despair, and torment—demands relics touch by true emotion. Dogran's suffering and his bond with Zankaja provide the exact emotional conduit required for the binding ritual.",sp=2}},faq={{q="Who is Dogran?",a="Dogran is an orc grunt stationed in the Barrens who recently earned a promotion to the Crossroads. He is also the mate of Zankaja, an orc woman living in Orgrimmar.",al={"dogran lore","who is dogran","grunt dogran"}},{q="Why does a warlock care about a missing orc guard?",a="Warlock mentors in the Cleft of Shadow orchestrate this search because the binding ritual for a succubus requires tokens steeped in deep mortal emotions, such as love, devotion, and suffering.",al={"why warlock quest","why do warlocks do this","succubus connection"}},{q="Where is Gazrog located?",a="Gazrog is stationed at the Crossroads in the Barrens, serving as one of the primary Horde authorities managing defense against local threats.",al={"where is gazrog","gazrog location","crossroads gazrog"}},{q="What happened to Dogran?",a="Dogran was ambushed and taken prisoner by the hostile quilboar of the Barrens. While badly wounded, he remains alive in captivity.",al={"is dogran dead","where is dogran","dogran fate"},sp=1},{q="Who gives this quest?",a="The quest is given by Zankaja on the bluffs of Orgrimmar, after being directed to her by the warlock trainer Cazul.",al={"quest giver","where to start news of dogran"}},{q="What comes next in the chain?",a="After speaking with Gazrog, warlocks are tasked with gathering a draught to treat Dogran's wounds and tracking down the quilboar encampment where he is held.",al={"what next","next quest","succubus chain continuation"},sp=1}},ang={["class:Warlock"]="This leg of your journey transitions your training from dark texts in Orgrimmar into real-world exploitation of mortal tragedy to claim a succubus.",["faction:Horde"]="The mission illustrates the constant danger faced by Horde grunts attempting to secure the perilous crossroads of Kalimdor from hostile indigenous threats.",["race:Orc"]="The quiet grief of Zankaja reveals the personal cost behind the Horde's expansion and defense throughout Durotar and the Barrens."},kw={"barrens","cazul","crossroads","dogran","gazrog","news of dogran","quilboar","succubus","zankaja"},rel={"npc:zankaja","npc:gazrog","npc:cazul","quest:1508","quest:1515","quest:1511","quest:1471","zone:barrens"},m={start="Zankaja",["end"]="Gazrog",level="20",faction="Horde",id=1509},src={"News of Dogran"}}
E["quest:1512"] = {t="quest",n="Love's Gift",z="orgrimmar",s="Love's Gift is the penultimate quest in the Horde warlock chain to summon and bind a succubus. After being tracked down and revived in the Barrens, the dying Grunt Dogran relinquishes a treasured keepsake to provide the bait necessary for the dark ritual.",h="Love's Gift is the penultimate quest in the Horde warlock chain to summon and bind a succubus.",sec={{t="A Grunt's Sacrifice",b="Found imprisoned and tortured by the Bristleback quilboar in the Barrens, Grunt Dogran is nursed back to consciousness by Ken'zigla's draught. Knowing his body is broken beyond recovery, Dogran resolves to face death in glorious battle rather than return to his mate, Zankaja, as an invalid. He surrenders a dirt-caked pendant—a gift born of pure love—asking only that she never learn of what he gave up.",sp=1},{t="Bait for a Demon",b="To summon and subjugate a succubus, a warlock requires a talisman of intense, unblemished emotion. Succubi feed on mortal desire and pervert genuine affection into anguish. Dogran's pendant carries the weight of authentic devotion and tragic parting. Returned to Gan'rul Bloodeye in the shadowy clefts of Orgrimmar, the talisman is cleaned and polished so its radiant emotional resonance can lure the devourer of souls across the Twisting Nether.",sp=0}},faq={{q="Why does a warlock need Dogran's pendant?",a="Succubi are demonic beings drawn to deep mortal passions, which they twist and consume. Dogran's pendant represents selfless love and heartfelt sacrifice, making it the perfect mystical lure to entice a succubus into the summoner's circle.",al={"why pendant","succubus bait","why dirt-caked pendant"}},{q="Who is Grunt Dogran?",a="Dogran is a Horde warrior captured and brutally tortured by the Bristleback quilboar in the southern Barrens. Though rescued and revived with an alchemical tonic, his grievous injuries leave him unable to live as a proud warrior.",al={"who is dogran","grunt dogran lore"}},{q="Who is Zankaja?",a="Zankaja is Dogran's young mate who waited anxiously for news of his whereabouts. To spare her the sorrow and burden of nursing a broken shell, Dogran chooses to give up her token and seek a warrior's death.",al={"zankaja lore","dogran mate"},sp=1},{q="Why does Dogran ask you to keep this secret from Zankaja?",a="Dogran refuses to chain a young mate to a dying invalid. He surrenders her pendant knowing it will never return to her, but begs that she be spared the guilt of knowing how his fate ended.",al={"why not tell zankaja","dogran secret"},sp=1},{q="Who cleans the pendant and why?",a="Gan'rul Bloodeye, the warlock trainer in Orgrimmar, takes the pendant. He cleans off the filth and grime so its bright, pristine appearance and emotional resonance will prove irresistible to the summoned demon.",al={"gan'rul bloodeye role","why clean the pendant"}},{q="What happens immediately after completing this quest?",a="Gan'rul Bloodeye directs you to bring the purified pendant into the summoning circle beneath Orgrimmar to cast the binding ritual and defeat the succubus in single combat.",al={"what comes next","next quest after love's gift"},sp=1}},ang={["class:Warlock"]="The binding of a succubus teaches warlocks that demons are not merely summoned with arcane power, but ensnared by exploiting their hunger for raw mortal passions like love and grief.",["faction:Horde"]="Grunt Dogran embodies the harsh martial ethos of the Horde, preferring to die on the battlefield rather than live as a crippled burden to his kin."},kw={"dirt-caked pendant","gan'rul bloodeye","grunt dogran","love's gift","orgrimmar","succubus","the barrens","zankaja"},rel={"npc:grunt-dogran","npc:gan-rul-bloodeye","npc:zankaja","quest:1471","quest:1515","quest:1511","quest:1472","zone:orgrimmar"},m={start="Grunt Dogran",["end"]="Gan'rul Bloodeye",level="20",faction="Horde",id=1512},src={"Love's Gift"}}
E["quest:1513"] = {t="quest",n="The Binding",z="orgrimmar",s="The Binding is the final trial in an aspiring Horde warlock's quest to enslave a succubus in Orgrimmar. By channeling the lingering demonic pull within Dogran's Pendant at Neeru Fireblade's summoning circle, the warlock wrenches a demon from the Twisting Nether and breaks its will through force of arms and spellcraft.",h="The Binding is the final trial in an aspiring Horde warlock's quest to enslave a succubus in Orgrimmar.",sec={{t="A Demon's Anchor",b="To reach across realms and compel a succubus, a summoner requires an anchor—a conduit attuned to the creature's particular nature. The pendant recovered from the fallen orc Dogran serves this dark purpose. Worn through torment and death, the trinket carries the exact emotional and demonic resonance needed to bridge the Twisting Nether and seize a demon's attention.",sp=1},{t="The Circle in the Shadows",b="Beneath the clefts of Orgrimmar, deep within the tent of Neeru Fireblade, lies a summoning circle prepared for such hazardous work. Under the tutelage of Gan'rul Bloodeye, the warlock activates the rune-scribed circle and battles the summoned seductress. A warlock cannot simply call a demon into service; they must overpower it in single combat, bending its malevolent spirit to their sovereign will.",sp=0},{t="Wiles and Willpower",b="As Gan'rul warns, succubi are perilous thralls. While their presence intoxicates and tempts the senses, they steadily drain the vitality and spirit of careless masters. The tragic downfall of Dogran stands as a stark lesson: raw pride and emotional weakness invite ruin. True mastery demands an unyielding will that never succumbs to the demon's allure.",sp=1}},faq={{q="What happens during this ritual?",a="The warlock brings Dogran's Pendant into the summoning circle inside Neeru Fireblade's tent in the Cleft of Shadows. Using the talisman's demonic resonance, the summoner calls forth a succubus from the Twisting Nether and battles it to submission to establish total dominion over the creature.",al={"how does the ritual work","what do you do in the binding","succubus ritual"}},{q="Where does the summoning take place?",a="The summoning takes place in the Cleft of Shadows in Orgrimmar, specifically within the tent of Neeru Fireblade, where a permanent ritual circle is inscribed into the floor.",al={"where is the circle","summoning circle location","where do i summon the succubus"}},{q="Who was Dogran and why is his pendant needed?",a="Dogran was a Horde grunt captured and maimed by the quilboar in the Barrens. His pendant, a keepsake tied to his beloved Zankaja, serves as the essential focal point needed to lure and anchor a succubus.",al={"who is dogran","why dograns pendant","dogran story"},sp=1},{q="Who is Gan'rul Bloodeye?",a="Gan'rul Bloodeye is a senior warlock trainer residing in the Cleft of Shadows beneath Orgrimmar. He mentors rising practitioners of the dark arts and guides them through the perilous rites of demon subjugation.",al={"who gives the quest","who is ganrul","ganrul bloodeye role"}},{q="What power does a warlock gain upon completing this trial?",a="Subduing the creature completes the warlock's training, granting them the secret knowledge and runic mastery required to summon a succubus minion into service at any time.",al={"what reward do warlocks get","why summon succubus","succubus pet ability"}},{q="Why is summoning a succubus considered especially dangerous?",a="Succubi wield powerful charms and manipulate the desires of mortals. Overconfident warlocks risk having their souls slowly siphoned away, succumbing to the demon's subtle guile rather than commanding it.",al={"succubus danger","why are succubi risky","succubus lore"}}},ang={["class:Warlock"]="This rite marks a warlock's transition into commanding cunning, disruptive demons, proving that personal willpower can dominate the seductive perils of the Nether.",["faction:Horde"]="Conducted in secret within the Cleft of Shadows, the ritual highlights the uneasy tolerance Thrall's Horde extends to demonic practitioners hidden away from the city's honor-bound populace.",["race:Orc"]="For orcs, dealing with demonic entities carries the bitter weight of their people's past corruption, making the discipline and control demanded by Gan'rul especially poignant."},kw={"binding","cleft of shadows","dogran","gan'rul","neeru","orgrimmar","pendant","succubus","warlock","zankaja"},rel={"npc:gan-rul-bloodeye","quest:1512","quest:1515","quest:1511","quest:1509","quest:1508","quest:1472","npc:zankaja"},m={start="Gan'rul Bloodeye",level="20",faction="Horde",id=1513},src={"The Binding (Succubus, Orgrimmar)"}}
E["quest:1531"] = {t="quest",n="Call of Air",z="orgrimmar",s="Call of Air is a vital rite of passage for seasoned Horde shamans seeking mastery over the winds. Initiated by Searn Firewarder in the Valley of Spirits, this quest directs practitioners far south across Kalimdor to commune with the elusive Prate Cloudseer. Through her guidance, shamans earn the final elemental pillar of their craft: the Air Totem.",h="Call of Air is a vital rite of passage for seasoned Horde shamans seeking mastery over the winds.",sec={{t="A Breath from the South",b="Having already earned the favor of earth, fire, and water, a shaman reaching the height of early training stands ready to harness the subtle and capricious element of air. In Orgrimmar, the troll trainer Searn Firewarder recognizes when a disciple is prepared for this final foundational step. Rather than testing them within Durotar's canyons, he bids them travel south across the expanse of the Barrens and descend into the canyon labyrinth of Thousand Needles.",sp=0},{t="The Cloudseer's Hermitage",b="The mentor awaiting travelers is Prate Cloudseer, a hermit dwelling in a high cave among the sandstone mesas of Thousand Needles. Living quietly alongside her partner away from the bustle of Horde encampments, Prate demands deference before unveiling the secrets of the wind. Upon meeting her with proper respect, she imparts the knowledge and focus needed to manifest the Air Totem, completing the shaman's elemental circle.",sp=0}},faq={{q="Who starts this quest?",a="Searn Firewarder, a shaman trainer residing in the Valley of Spirits within Orgrimmar, offers this quest to qualified shamans once they reach appropriate experience.",al={"quest giver","where to get call of air","searn firewarder"}},{q="Where can I find Prate Cloudseer?",a="Prate Cloudseer is located in Thousand Needles. After descending the Great Lift from the southern Barrens, head eastward through the canyon floor to locate the cave where she dwells.",al={"prate cloudseer location","find prate","air totem npc"}},{q="What is the Air Totem used for?",a="The Air Totem is the fourth and final elemental focus a shaman acquires. Carrying it allows the shaman to invoke spells and totems of the air element, granting speed, grace, and wind-based powers.",al={"air totem purpose","why do air totem quest","what does air totem do"}},{q="Why does Searn Firewarder send you so far away?",a="Mastery over the elements requires finding mentors who have dedicated their lives to communing with specific spirits. Prate Cloudseer possesses deep insight into the winds of the shifting canyon gusts in Thousand Needles, making her the ideal guide for communing with air.",al={"why thousand needles","why prate cloudseer"}},{q="Do I need to complete other elemental totem quests first?",a="Yes. A shaman's training follows a strict progression through the elements, beginning with earth, followed by fire and water, before finally proving worthy to command air.",al={"prerequisites","totem order","can i do air totem first"}},{q="Are there other versions of this quest for different cities?",a="Yes. Shaman trainers in other Horde capitals, such as Thunder Bluff, provide their own directional instructions sending initiates to Prate Cloudseer in Thousand Needles.",al={"thunder bluff air totem","undercity air totem"}}},ang={["class:Shaman"]="Obtaining the Air Totem is the culminating milestone of early shamanic journeying, allowing you to invoke wind spirits alongside earth, fire, and water.",["faction:Horde"]="The shamanic tradition ties the diverse races of the Horde together, relying on far-flung elders and hermits across central Kalimdor to pass down sacred customs."},kw={"air totem","call of air","orgrimmar","prate cloudseer","searn firewarder","shaman quest","thousand needles","valley of spirits"},rel={"npc:searn-firewarder","zone:thousandneedles","zone:barrens"},m={start="Searn Firewarder",["end"]="Prate Cloudseer",level="30",faction="Horde",id=1531},src={"Call of Air (Orgrimmar)"}}
E["quest:1858"] = {t="quest",n="The Shattered Hand",z="orgrimmar",s="This rogue trial serves as the final initiation into the ranks of the Shattered Hand within Orgrimmar. Therzok tasks aspiring rogues with unlocking a recovered satchel by lifting the key from an unwitting accomplice.",h="This rogue trial serves as the final initiation into the ranks of the Shattered Hand within Orgrimmar.",sec={{t="A Test of Subtlety",b="Having retrieved Tazan's locked satchel, aspiring rogues find the prize useless without its key. Rather than forcing the complex lock by brute strength, the Shattered Hand insists on genuine craft. Therzok points his initiates toward Gamon, an easily distracted tauren drunkard who frequent's Orgrimmar's tavern and previously assisted Tazan, making him an ideal mark for quiet thievery.",sp=0},{t="Welcome to the Shadows",b="Relieving Gamon of the key without alerting the entire tavern allows an initiate to unlock the satchel and secure Tazan's logbook. Bringing these stolen contents back to Therzok in the Cleft of Shadow satisfies the guild's rigorous standards. With the job done cleanly, the candidate is formally inducted as a recognized operative of the Shattered Hand.",sp=0}},faq={{q="Who is Gamon and why does he have the key?",a="Gamon was an assistant to Tazan, the operative whose satchel Therzok is investigating. While Tazan carried the satchel, he left the key in the hands of Gamon, an unsuspecting drunkard who spends his days drinking in Orgrimmar's central tavern.",al={"why gamon","who has the key","gamon key"}},{q="What is inside Tazan's satchel?",a="Inside the locked satchel rests Tazan's logbook. Its contents detail intelligence of interest to Therzok and the Shattered Hand, proving the initiate's ability to recover vital information under covert circumstances.",al={"tazan's logbook","satchel contents","what is in the satchel"}},{q="What is the Shattered Hand in Orgrimmar?",a="Originally an infamous orcish clan from Draenor known for self-mutilation and ruthlessness, the Shattered Hand has evolved in Orgrimmar into the Horde's premier guild of assassins, spies, and rogues, operating out of the subterranean Cleft of Shadow.",al={"what is shattered hand","shattered hand rogues","orgrimmar rogues"}},{q="Where does Therzok operate?",a="Therzok operates out of the Cleft of Shadow, the dim cavern network hidden beneath the rocky ridges of Orgrimmar where warlocks, rogues, and shadowcraft thrive away from daylight.",al={"where is therzok","therzok location","cleft of shadow rogue trainer"}},{q="Why doesn't Therzok just break open the satchel?",a="The satchel is fitted with a complex locking mechanism, but more importantly, this is a test of a rogue's discipline. The Shattered Hand values surgical theft and finesse over noisy destruction.",al={"why pickpocket","why need key"}},{q="What happens after this quest?",a="This assignment marks the conclusion of the initiation chain. By handing over Tazan's logbook, you are formally declared a recognized member of the Shattered Hand and rewarded with tools to aid your future covert endeavors.",al={"shattered hand reward","end of chain"},sp=1}},ang={["class:Rogue"]="This rite of passage teaches the core tenets of the rogue craft: stalking an oblivious target in crowded quarters, lifting a key unnoticed, and securing vital intelligence.",["faction:Horde"]="Beneath the martial honor of Thrall's new Horde lies the necessity of covert reconnaissance, quietly managed by the Shattered Hand deep within Orgrimmar."},kw={"cleft of shadow","gamon","orgrimmar","pickpocket","rogue","shattered hand","tazan","therzok"},rel={"quest:1859","subzone:cleft-of-shadow","zone:orgrimmar","topic:horde","subzone:cleft"},m={start="Therzok",level="13",faction="Horde",id=1858},src={"The Shattered Hand (2)"}}
E["quest:1859"] = {t="quest",n="Therzok",z="orgrimmar",s="Therzok is a summons delivered to promising Horde rogues operating near the Valley of Trials and Sen'jin Village. The rogue trainer Kaplak spots your knack for violence and stealth, quietly directing you into the cavernous Cleft of Shadow to meet an operative of the Shattered Hand.",h="Therzok is a summons delivered to promising Horde rogues operating near the Valley of Trials and Sen'jin...",sec={{t="A Whispered Summons",b="Not all servants of the new Horde fight in plain daylight under the banner of Thrall's honor. When young rogues begin making a name for themselves in Durotar, Kaplak pulls them aside with hushed words. Word of an agent who combines physical lethality with a willingness to skirt the rules of open warfare travels fast to the ears of the underground guild in Orgrimmar.",sp=0},{t="Into the Cleft of Shadow",b="Kaplak sends the initiate deep beneath the red stone cliffs of Orgrimmar into the Cleft of Shadow. Away from the watchful eyes of the city grunts, Therzok waits in the gloom. The meeting serves as an induction point, bringing lone cutpurses and ambushers into the structured fold of the Shattered Hand, the covert network functioning as the Horde's daggers in the dark.",sp=0}},faq={{q="Who is Therzok?",a="Therzok is an operative of the Shattered Hand situated in the subterranean Cleft of Shadow in Orgrimmar. He vets promising young rogues who arrive from the training grounds of Durotar and initiates them into the guild's service.",al={"who is therzok","therzok lore","npc therzok"}},{q="Why does Kaplak send me to him?",a="Kaplak recognizes that you possess skill in combat alongside a talent for stealth and subterfuge. Knowing the Shattered Hand is constantly looking for capable scoundrels to bolster their ranks, he passes along Therzok's request to recruit you.",al={"why send me to therzok","kaplak quest","why go to orgrimmar"}},{q="What is the Shattered Hand in Orgrimmar?",a="While the name traces back to an ancient Draenor clan, in modern Orgrimmar the Shattered Hand operates as the secret guild of assassins, spies, and thieves serving the Horde. They carry out the necessary, morally ambiguous tasks that Thrall's honorable warriors cannot openly perform.",al={"what is shattered hand","shattered hand orgrimmar","horde rogue guild"}},{q="Where is the Cleft of Shadow located?",a="The Cleft of Shadow is a vast cavern tucked beneath central Orgrimmar, accessible through dark passages leading down from the Valley of Strength and the Valley of Honor. It houses the city's warlocks and rogues away from public scrutiny.",al={"where is cleft of shadow","how to find therzok","cleft of shadow location"}},{q="What comes after meeting Therzok?",a="Upon greeting Therzok, he immediately introduces you to the responsibilities of working for the Shattered Hand, assigning tasks to prove your capability, stealth, and loyalty to the network.",al={"next quest","what does therzok want","after therzok"}},{q="Do non-rogues receive this quest?",a="No. This quest is exclusively offered to rogues upon reaching a certain level of experience, marking their transition from local skirmishers into formal operatives of the Horde's intelligence network.",al={"can other classes do this","is this rogue only","rogue quest"}}},ang={["class:Rogue"]="This summons marks your formal entrance into the Shattered Hand, connecting your solitary work in Durotar to the organized spy network running throughout the Horde.",["faction:Horde"]="While Thrall preaches honor and warrior spirit, the existence of Therzok and his network proves the Horde understands the practical necessity of unseen blades and secret gatherers of intelligence."},kw={"assassin","cleft of shadow","durotar","kaplak","orgrimmar","rogue","shattered hand","therzok"},rel={"quest:1858","npc:kaplak","subzone:cleft-of-shadow","zone:orgrimmar","subzone:cleft"},m={start="Kaplak",["end"]="Therzok",level="10",faction="Horde",id=1859},src={"Therzok (quest)"}}
E["quest:1943"] = {t="quest",n="Speak with Deino",z="orgrimmar",s="\"Speak with Deino\" is a summons directing promising Horde mages to seek out a skilled practitioner in Orgrimmar. Deino, a troll mage operating out of the Valley of Spirits, requires an adept to undertake critical work on behalf of their craft. Answering her call opens the path to deeper magical study and vital tasks across Kalimdor.",h="\"Speak with Deino\" is a summons directing promising Horde mages to seek out a skilled practitioner in...",sec={{t="A Summons to Orgrimmar",b="As practitioners of the arcane hone their abilities within the Horde, instructors in Undercity and Kalimdor recognize when a student is prepared for more demanding ventures. Mentors like Anastasia Hartwell in the Undercity or Quithas in Durotar point developing mages toward Orgrimmar. There, tucked away in the troll-dominated quarter, more specialized knowledge and perilous errands await.",sp=0},{t="The Valley of Spirits and Darkbriar Lodge",b="Deino makes her home within the Darkbriar Lodge in Orgrimmar's Valley of Spirits. Among the Darkspear, dedicated practitioners of the arcane are relatively rare compared to witch doctors and priests, making Deino a notable authority in the capital. She works not just for local concerns, but for the broader interests of the Horde's arcane practitioners, seeking ambitious mages willing to brave distant perils.",sp=0}},faq={{q="Who sends you to speak with Deino?",a="Mage trainers such as Anastasia Hartwell in the Magic Quarter of Undercity and Quithas in Durotar send aspiring mages to Orgrimmar once they reach sufficient skill.",al={"quest giver","who starts this","where do i get speak with deino"}},{q="Where can I find Deino?",a="Deino is located inside the Darkbriar Lodge, nestled in the Valley of Spirits on the western side of Orgrimmar.",al={"deino location","where is deino","darkbriar lodge location"}},{q="Why does Deino need assistance?",a="Deino oversees important research and tasks deemed vital to the society of Horde mages. She enlists capable spellcasters to venture into dangerous lands to secure rare magical resources.",al={"why deino needs help","what does deino want"}},{q="What happens after reporting to Deino?",a="Once you report to Deino, she briefs you on her mission and sends you on your next assignment, beginning with gathering the Waters of Xavian.",al={"next quest","what comes after","follow up quest"}},{q="Is this quest available to all classes?",a="No. This quest is exclusively offered to mages of the Horde as part of their dedicated class progression and training.",al={"is this mage only","can warlocks do this","class restriction"}},{q="Are troll mages common in the Horde?",a="Arcane magic is less common among the Darkspear trolls than spiritual shamanism, voodoo, or loa priesthood. However, figures like Deino show that some trolls have thoroughly mastered the formal study of arcane forces.",al={"trolls using arcane","darkspear mages lore"}}},ang={["class:Mage"]="This quest is a pivotal step in your formal arcane training, connecting you to senior spellcasters in Orgrimmar.",["race:Troll"]="Deino represents the focused arcane discipline practiced by a select few among the Darkspear tribe.",["faction:Horde"]="The summons bridges regional trainers from Lordaeron and Durotar into the centralized arcane leadership gathering in Orgrimmar."},kw={"anastasia hartwell","darkbriar lodge","deino","mage quest","orgrimmar","quithas","valley of spirits","waters of xavian"},rel={"npc:deino","quest:1944","zone:orgrimmar","topic:horde","topic:troll"},m={start="Anastasia Hartwell, Quithas",["end"]="Deino",level="26",faction="Horde",id=1943},src={"Speak with Deino"}}
E["quest:1963"] = {t="quest",n="The Shattered Hand",z="orgrimmar",s="This rogue trial, issued by Therzok in the Cleft of Shadow, tests initiates seeking entry into the secretive Shattered Hand guild. To prove their deadly efficiency, aspiring rogues are tasked with hunting down the troll smuggler Tazan and seizing his locked satchel.",h="This rogue trial, issued by Therzok in the Cleft of Shadow, tests initiates seeking entry into the secretive...",sec={{t="Shadows in the Cleft",b="Beneath the bustling streets of Orgrimmar lies the subterranean gloom of the Cleft of Shadow. Here operates the Shattered Hand, a clandestine order of assassins and thieves rooted in old orcish traditions. While Warchief Thrall preaches honor, diplomacy, and caution in ruling the nascent Horde, the leadership of the Shattered Hand believes such hesitation weakens their people. They seek to reclaim martial supremacy through covert violence, using knives and poison where battlefield charges might fail.",sp=0},{t="A Smuggler's Fate",b="To weed out the clumsy and the weak, the handler Therzok sets a straightforward contract: eliminate Tazan, an errant troll operating in the Barrens near Ratchet. Tazan has been trading with coastal pirates and holds sensitive intelligence the guild covets. Recovering his locked satchel confirms the rogue's ability to stalk prey beyond the city walls, though extracting the contents inside requires even further finesse.",sp=1}},faq={{q="What is the Shattered Hand in Orgrimmar?",a="The Shattered Hand is the Horde's covert guild of rogues, scouts, and assassins operating out of the Cleft of Shadow in Orgrimmar. While historically an old orcish clan known for brutal self-mutilation, in the modern Horde they serve as a shadowy intelligence and wetwork network that favors ruthless pragmatism over Thrall's cautious diplomacy.",al={"who are shattered hand","shattered hand rogues","shattered hand purpose"}},{q="Who is Therzok?",a="Therzok is a Shattered Hand handler stationed in the Cleft of Shadow. He tests prospective rogues to ensure they have the cunning and lethality required to serve the guild, expressing open skepticism toward Thrall's restraint.",al={"therzok role","who is questgiver","therzok orgrimmar"}},{q="Why does Therzok want Tazan dead?",a="Tazan is a troll smuggler conducting illicit trade with the Southsea pirates near the port of Ratchet. Beyond whatever contraband he moves, Tazan carries critical information in a satchel that the Shattered Hand wants for their own covert operations.",al={"why kill tazan","tazan lore","what did tazan do"}},{q="Where is Tazan located?",a="Tazan operates out in the Barrens, lurking near the coast and pirate operations south of Ratchet.",al={"tazan location","where is tazan","find tazan"}},{q="What happens after recovering Tazan's satchel?",a="When returned to Therzok, the satchel turns out to be locked. Pleased with Tazan's demise but requiring the intelligence inside, Therzok uses the situation as a follow-up test of the rogue's lockpicking ability.",al={"next quest","locked satchel","what to do with satchel"},sp=1},{q="Does Thrall know about the Shattered Hand's methods?",a="While the Shattered Hand nominally serves the Horde, their members operate largely from the shadows and harbor contempt for Thrall's cautious leadership. They quietly pursue their own intelligence networks to eliminate perceived threats before the Warchief's diplomacy can stall action.",al={"thrall and shattered hand","does warchief approve","thrall rogues"}}},ang={["class:Rogue"]="This rite of passage initiates young Horde rogues into the fold of the Shattered Hand, emphasizing ruthless efficiency, assassination, and utility over open combat.",["faction:Horde"]="The Shattered Hand represents the internal ideological friction in Orgrimmar, where clandestine factions quietly challenge Thrall's cautious vision for the young Horde."},kw={"cleft of shadow","orgrimmar","ratchet","rogue","satchel","shattered hand","tazan","therzok"},rel={"subzone:cleft-of-shadow","quest:1859","zone:orgrimmar","subzone:ratchet","topic:horde","topic:pirate","topic:troll"},m={start="Therzok",level="13",faction="Horde",id=1963},src={"The Shattered Hand (Classic)"}}
E["quest:235"] = {t="quest",n="The Ashenvale Hunt",z="orgrimmar",s="Issued by Warcaller Gorlach in Orgrimmar, this directive summons budding Horde adventurers northward beyond the Barrens into the ancient forests of Ashenvale. Players are directed to report to Senani Thunderheart at Splintertree Post to participate in the ongoing hunt and reinforce the Horde's expanding frontier.",h="Issued by Warcaller Gorlach in Orgrimmar, this directive summons budding Horde adventurers northward beyond...",sec={{t="Call of the Wilds",b="Orgrimmar buzzes with martial fervor, but the young city requires vast amounts of timber, meat, and secure trade routes to sustain its growth. Warcaller Gorlach serves as the voice of the Horde's high command, directing seasoned wanderers and new blood alike toward active campaigns. For warriors coming of age in Durotar and the Barrens, the ancient woodlands of Ashenvale represent the next testing ground for both glory and survival.",sp=0},{t="A Treacherous Frontier",b="Crossing the northern border of the Barrens brings travelers directly into Ashenvale, where the Horde maintains two primary bastions: Splintertree Post nestled in the eastern woods and Zoram'gar Outpost along the western coast. Senani Thunderheart coordinates operations at Splintertree Post, organizing trackers and hunters to tame the beast-choked canopy and push back against hostile night elven sentinels disputing the Horde's claims.",sp=0}},faq={{q="Who starts this quest and where can I find them?",a="Warcaller Gorlach offers this quest inside Orgrimmar, the Horde capital. He serves as an officer calling capable adventurers to take up campaigns beyond the borders of Durotar.",al={"quest giver","where is gorlach","who gives ashenvale hunt"}},{q="Where is Splintertree Post?",a="Splintertree Post lies directly north of the Barrens in eastern Ashenvale, situated along the main forest road running eastward toward Azshara.",al={"splintertree location","where is splintertree post","how to get to splintertree"}},{q="Who is Senani Thunderheart?",a="Senani Thunderheart is a seasoned tauren tracker stationed at Splintertree Post. She directs the hunting efforts across Ashenvale and evaluates adventurers who wish to take part in the local trials.",al={"who is senani","senani thunderheart location","turn in npc"}},{q="What is the purpose of the Ashenvale hunt?",a="The hunt allows the Horde to secure wild game, harvest valuable hides, and eliminate apex predators that endanger patrols around Splintertree Post and nearby logging operations.",al={"why hunt in ashenvale","ashenvale hunt story","horde goal in ashenvale"}},{q="What other outposts does the Horde hold in Ashenvale?",a="In addition to Splintertree Post, the Horde maintains an encampment on the far western edge of the forest along the Zoram Strand.",al={"horde bases in ashenvale","zoram strand post","ashenvale outposts"}},{q="Does this quest involve any combat?",a="No. This quest serves purely as a breadcrumb assignment, directing you to travel safely from Orgrimmar through the Barrens to report to Senani Thunderheart.",al={"is there fighting in this quest","do i fight anything","simple turn in"}}},ang={["faction:Horde"]="The march into Ashenvale tests whether the newly unified Horde can expand beyond the dry crags of Durotar into resource-rich yet hostile foreign soil.",["class:Hunter"]="Ashenvale's dense canopies and dangerous beasts provide the ultimate wilderness proving ground for aspiring trackers answering Senani Thunderheart's call.",["race:Tauren"]="Serving under Senani Thunderheart allows tauren adventurers to bring their deep reverence for the great hunt to the untamed northern forest."},kw={"ashenvale","barrens","gorlach","hunt","orgrimmar","senani","splintertree","thunderheart"},rel={"npc:warcaller-gorlach","npc:senani-thunderheart","subzone:splintertree-post","zone:ashenvale","zone:barrens","subzone:zoram-strand","quest:1008","topic:horde"},m={start="Warcaller Gorlach",["end"]="Senani Thunderheart",level="20",faction="Horde",id=235},src={"The Ashenvale Hunt (Orgrimmar)"}}
E["quest:2378"] = {t="quest",n="Find the Shattered Hand",z="orgrimmar",s="Find the Shattered Hand is a journey quest sending promising Forsaken rogues from Tirisfal Glades across the sea to Durotar. Directed by the Deathstalkers, the initiate travels to Orgrimmar's shadowy underbelly to learn specialized arts from the Shattered Hand clan.",h="Find the Shattered Hand is a journey quest sending promising Forsaken rogues from Tirisfal Glades across the...",sec={{t="A League of Shadows",b="While the Forsaken cultivate their own covert order in the Deathstalkers, their mutual alliance with the Horde opens avenues of collaboration in darker arts. Mennet Carkad, having seen a rogue prove their worth in Tirisfal Glades, recognizes the need for broader instruction. He directs promising shadows to seek out the Shattered Hand in Orgrimmar, leaning on the quiet partnership between Lordaeron's undead operatives and Kalimdor's orcish guild of assassins.",sp=0},{t="Into the Cleft of Shadow",b="The journey ends deep within the Cleft of Shadow, the subterranean cavern hidden beneath Orgrimmar where warlocks, rogues, and demon-binders ply trades the surface dwellers prefer not to look upon. There awaits Shenthul, a trainer of the Shattered Hand. Unimpressed by reputation alone, the gruff troll assesses the newly arrived undead agent with harsh skepticism, eager to test whether this envoy possesses genuine cunning or merely wasted the voyage across the Great Sea.",sp=0}},faq={{q="Who gives the quest Find the Shattered Hand?",a="Mennet Carkad, a Deathstalker trainer residing in the Rogues' Quarter of the Undercity, gives the quest once a rogue proves their foundational skills in Tirisfal Glades.",al={"who starts find the shattered hand","mennet carkad quest","who sends me to orgrimmar"}},{q="Where is Shenthul located?",a="Shenthul is located in the Cleft of Shadow, the darkened chasm beneath the central pathways of Orgrimmar.",al={"find shenthul","shenthul location","where is shenthul in orgrimmar"}},{q="What is the relationship between the Deathstalkers and the Shattered Hand?",a="The Deathstalkers act as the intelligence network and assassination guild for the Forsaken, while the Shattered Hand serves a similar clandestine role for the Horde in Orgrimmar. They cooperate as formal allies, sharing advanced training and clandestine contracts across the factions of the Horde.",al={"deathstalkers and shattered hand","forsaken rogues orc rogues","why sent to orgrimmar"}},{q="Why does Shenthul call me uninspiring?",a="The Shattered Hand values physical resilience and ruthless cunning above all. Shenthul regularly insults and downplays newcomers to shatter their pride and test whether they have the resolve to endure rigorous assassin training.",al={"shenthul dialogue","why is shenthul mean","shenthul completion text"}},{q="What happens after reaching Shenthul?",a="Shenthul puts the operative directly to work, offering the quest Zando'zan and eventually sending them south toward Ratchet to undertake hands-on field operations in the Barrens.",al={"what comes after find the shattered hand","next quest after shenthul","shattered hand chain"}},{q="Can non-Forsaken rogues get this quest?",a="No. Find the Shattered Hand is the Forsaken variant handed out by the Deathstalkers. Orc and troll rogues operating in Durotar receive an equivalent transition quest called 'To Orgrimmar!'.",al={"orc rogue find the shattered hand","troll version","to orgrimmar alternate"}}},ang={["class:Rogue"]="This quest bridges local training with the broader criminal and covert network of the Horde, introducing rogues to the primary underworld trainers in Kalimdor.",["race:Undead"]="For young Forsaken rogues, this marks the official transition from fighting local Scourge remnants in Lordaeron to integrating with the Horde's heartland in Durotar.",["faction:Horde"]="The mission illustrates that Horde cooperation extends beyond frontline grunts and shamans, showing deep coordination between the secret services of Orgrimmar and Undercity."},kw={"cleft of shadow","deathstalkers","mennet carkad","orgrimmar","rogue quest","shattered hand","shenthul"},rel={"npc:shenthul","subzone:cleft-of-shadow","zone:orgrimmar","quest:2379","quest:2380","quest:1886","quest:1858","quest:2382"},m={start="Mennet Carkad",["end"]="Shenthul",level="16",faction="Horde",id=2378},src={"Find the Shattered Hand"}}
E["quest:2379"] = {t="quest",n="Zando'zan",z="orgrimmar",s="This errand directs promising Horde rogues to introduce themselves to Zando'zan deep within Orgrimmar's Cleft of Shadow. Sent by trainer Shenthul, the initiate takes the first steps into the covert ranks and illicit techniques of the Shattered Hand.",h="This errand directs promising Horde rogues to introduce themselves to Zando'zan deep within Orgrimmar's Cleft...",sec={{t="A Walk into the Shadows",b="Orgrimmar may appear to be a fortress of brute strength and martial discipline, but its rulers know that raw muscle alone cannot win every war. Down in the subterranean gloom of the Cleft of Shadow operates the Shattered Hand, the covert guild handling espionage, sabotage, and theft for the Horde. When the rogue trainer Shenthul decides an initiate has shown enough promise, he dispatches them to report directly to Zando'zan for dedicated operative training.",sp=0},{t="Proving One's Worth",b="Zando'zan does not automatically hand out respect to every green rogue wandering down into the cavern. Approaching him is a formal initiation into finer clandestine arts, beginning with the delicate skills of stealth, subterfuge, and thievery. Meeting Zando'zan bridges the gap between rough street cutpurses and organized intelligence operatives, preparing the rogue for tricky fieldwork beyond the safety of the capital's red canyon walls.",sp=0}},faq={{q="Who is Zando'zan?",a="Zando'zan is a rogue trainer and handler for the Shattered Hand residing in Orgrimmar's subterranean Cleft of Shadow. He evaluates new recruits and instructs them in practical stealth, burglary, and operative tradecraft.",al={"zandozan","who is zando'zan","zando'zan cleft of shadow"}},{q="Why does Shenthul send rogues to see Zando'zan?",a="Shenthul recognizes when a fledgling rogue has outgrown basic brawling and needs specialized training as a Shattered Hand operative. Zando'zan oversees the lessons in burglary and lock-manipulation required for clandestine field operations.",al={"why do i talk to zando'zan","shenthul zando'zan","purpose of quest"}},{q="What is the Shattered Hand in Orgrimmar?",a="Originally a brutal orcish clan from Draenor known for ritual self-mutilation, the Shattered Hand in Durotar has evolved into the covert intelligence and assassination arm of the Horde. They operate from the shadows of Orgrimmar, dealing in espionage, poison, and scouting.",al={"what is shattered hand","shattered hand orgrimmar","horde rogues shattered hand"}},{q="Where does this training chain lead next?",a="After presenting yourself to Zando'zan, he directs you outward to Ratchet on the coast of the Barrens to consult a goblin contact named Wrenix, beginning practical field work in lockpicking.",al={"next quest","what comes after zando'zan","wrenix of ratchet"},sp=1},{q="Where can I find Zando'zan?",a="He lurks within the Cleft of Shadow, the deep cavern network carved beneath the center of Orgrimmar where warlocks, shadow priests, and rogue operatives gather out of broad daylight.",al={"zando'zan location","where is zando'zan","how to find zando'zan"}},{q="Why does Zando'zan apologize upon meeting me?",a="Zando'zan likely had misgivings or doubted your nerve before your arrival. Seeing you stand before him ready to train forces him to acknowledge your commitment and retract his initial skepticism.",al={"why zandozan apologize","completion dialogue zando'zan"}}},ang={["class:Rogue"]="This task marks your formal induction into the covert apparatus of the Shattered Hand, transitioning you from an untrained knifefighter into a recognized operative of the Horde.",["faction:Horde"]="While the warchief speaks often of honor and frontal assault, the Shattered Hand provides the essential espionage and covert dirty work that keeps the young Horde safe from unseen threats."},kw={"cleft of shadow","lockpicking","orgrimmar","rogue","shattered hand","shenthul","stealth","wrenix","zando'zan"},rel={"npc:shenthul","subzone:cleft-of-shadow","quest:2378","quest:2380","quest:2382","quest:2381","quest:1858","zone:orgrimmar"},m={start="Shenthul",["end"]="Zando'zan",level="16",faction="Horde",id=2379},src={"Zando'zan (quest)"}}
E["quest:2380"] = {t="quest",n="To Orgrimmar!",z="orgrimmar",s="To Orgrimmar! is an introductory summons dispatching a developing Horde rogue from Razor Hill to the capital city. Acting on orders from Kaplak, the initiate is sent beneath the surface into the Cleft of Shadow to present themselves before Shenthul and deeper within the network of the Shattered Hand.",h="To Orgrimmar!",sec={{t="A Summons to the Shadows",b="After cutting their teeth across Durotar, novice rogues eventually catch the attention of more prominent handlers. In Razor Hill, Kaplak bluntly acknowledges that an operative's budding talents—while unpolished—have earned notice. Rather than remaining out among the red crags, the operative is directed north into the cavernous alleys of Orgrimmar.",sp=0},{t="Under Thrall's Watchful Eye",b="Meeting Shenthul in the subterranean Cleft of Shadow reveals a deeper tension beneath the Horde's founding ideals. Shenthul makes no secret of his vigilance regarding Warchief Thrall's political reforms. For the Shattered Hand, brute force and open defiance will never suffice to safeguard their interests; survival and influence require patience, subterfuge, and refined deception.",sp=1}},faq={{q="Who sends me on this quest?",a="Kaplak, a rogue trainer stationed in Razor Hill, delivers the summons after determining that your skills have caught the attention of superiors in Orgrimmar.",al={"quest giver","who gives to orgrimmar","kaplak quest"}},{q="Where do I find Shenthul?",a="Shenthul is located in the Cleft of Shadow, the shadowy underground district carved deep beneath Orgrimmar where rogues, warlocks, and other outcasts gather.",al={"shenthul location","where is shenthul","cleft of shadow shenthul"}},{q="What is the Shattered Hand's agenda in Orgrimmar?",a="The Shattered Hand operates as an intelligence and assassination guild within the Horde. While nominally part of the new capital, leaders like Shenthul remain wary of Thrall's honorable reforms and emphasize stealth to maintain leverage and survival.",al={"shattered hand motives","why shattered hand in orgrimmar","shattered hand thrall"}},{q="Why am I being sent specifically at this stage?",a="Novice operatives who prove capable in basic reconnaissance and skirmishes are drawn into more formal guild duties, beginning with lockpicking and covert fieldwork assigned in the capital.",al={"level 16 rogue quest","why go to orgrimmar now","rogue training summons"}},{q="Does this quest differ from 'Find the Shattered Hand'?",a="Both serve as introductory breadcrumbs leading rogues to Shenthul in Orgrimmar; depending on where you train or take orders, you receive one or the other to advance the same training chain.",al={"find the shattered hand vs to orgrimmar","alternate breadcrumb quest"}},{q="What happens after reporting to Shenthul?",a="Shenthul tests your competence and directs you further down the chain, introducing contacts such as Zando'zan and eventually covert work involving goblin contacts in Ratchet.",al={"next quest after to orgrimmar","what does shenthul give"}}},ang={["class:Rogue"]="This mission marks your formal induction into the capital's covert network, moving you beyond crude frontier scuffles into the craft of poisons, thievery, and deception overseen by Shenthul.",["faction:Horde"]="The quiet discontent voiced by Shenthul highlights the friction between Thrall's honorable new path and the shadowy remnants of older clan organizations surviving beneath Orgrimmar."},kw={"cleft of shadow","kaplak","razor hill","rogue","shattered hand","shenthul","to orgrimmar"},rel={"npc:shenthul","npc:kaplak","subzone:cleft-of-shadow","quest:2378","quest:2379","quest:2382","quest:2381","zone:orgrimmar"},m={start="Kaplak",["end"]="Shenthul",level="16",faction="Horde",id=2380},src={"To Orgrimmar!"}}
E["quest:2382"] = {t="quest",n="Wrenix of Ratchet",z="orgrimmar",s="Wrenix of Ratchet is a Horde rogue assignment directing aspiring agents out of Orgrimmar and down to the goblin port of Ratchet. The manic troll Zando'zan sends operatives south to assist a disreputable goblin named Wrenix the Wretched.",h="Wrenix of Ratchet is a Horde rogue assignment directing aspiring agents out of Orgrimmar and down to the...",sec={{t="A Prophet in the Shadows",b="Within the winding crevices of the Cleft of Shadow in Orgrimmar, the rogue guild conducts its operations largely unseen. Operatives visiting Zando'zan are met with wild ramblings and ominous portents, including dark visions of Warchief Thrall's assassination by poison and blade. Rather than explain his prophecy, the eccentric troll swiftly dispatches agents to the port town of Ratchet in the Barrens.",sp=0},{t="Ratchet's Problem Solver",b="Sitting on the coast east of the Crossroads, the neutral port of Ratchet hosts all manners of scoundrels, mercenaries, and tinkerers. Wrenix the Wretched operates out of this bustling haven, though he has little patience for Zando'zan's eccentricities. According to Wrenix, the troll's previous recruits met unfortunate ends in the bay's predator-infested waters.",sp=0}},faq={{q="Who sends you to Ratchet?",a="Zando'zan, a troll associated with the Shattered Hand in Orgrimmar's Cleft of Shadow, sends you on this errand after blurting out strange visions.",al={"who gives quest","quest giver","zandozan"}},{q="Who is Wrenix the Wretched?",a="Wrenix the Wretched is a goblin contact operating in the port town of Ratchet. He handles covert tasks and mechanical supplies for rogues operating across the Barrens.",al={"who is wrenix","wrenix ratchet","wrenix identity"}},{q="What happened to the operatives sent before me?",a="According to Wrenix, the previous five agents dispatched by Zando'zan failed their assignments and ended up as shark food off the coast of Ratchet.",al={"previous rogues","shark food","other recruits"}},{q="What was Zando'zan talking about regarding Thrall?",a="Zando'zan claims to have had a vision of Thrall being struck down by a poisoned dagger in the back, though he quickly cuts himself off and changes the subject.",al={"thrall prophecy","thrall poisoned","zandozan thrall vision"}},{q="Where is Ratchet located?",a="Ratchet is located on the eastern coast of the Barrens, directly east of the Crossroads. It is connected to Durotar by roads leading south from the Southfury River.",al={"where is ratchet","find ratchet","ratchet location"}},{q="What comes next after meeting Wrenix?",a="Upon greeting Wrenix, he tasks you with 'Plundering the Plunderers,' which involves infiltrating the Southsea Freebooters along the coast south of Ratchet.",al={"next quest","after wrenix","ratchet follow up"},sp=1}},ang={["class:Rogue"]="This journey is an essential step in a Horde rogue's training, guiding young operatives away from the safety of Orgrimmar and into neutral pirate territory.",["faction:Horde"]="The Shattered Hand maintains eyes and ears beyond Durotar's borders, frequently relying on neutral ports like Ratchet to handle sensitive contracts."},kw={"ratchet","rogue","shattered hand","the barrens","thrall","wrenix","zando'zan"},rel={"quest:2379","quest:2381","quest:2378","npc:wrenix-the-wretched","subzone:ratchet","subzone:crossroads","zone:orgrimmar","npc:thrall"},m={start="Zando'zan",["end"]="Wrenix the Wretched",level="16",faction="Horde",id=2382},src={"Wrenix of Ratchet"}}
E["quest:2458"] = {t="quest",n="Deep Cover",z="orgrimmar",s="Deep Cover is an undercover assignment given to promising Horde rogues by Shenthul in Orgrimmar. The mission dispatches the operative to the Venture Company drilling grounds at Sludge Fen to establish secret contact with an embedded agent of the Shattered Hand.",h="Deep Cover is an undercover assignment given to promising Horde rogues by Shenthul in Orgrimmar.",sec={{t="A Spy Among Profiteers",b="The Shattered Hand operates as the clandestine intelligence and assassin guild of the Horde, answering quietly to Warchief Thrall while guarding Orgrimmar's interests through ruthlessly practical means. For an entire year, the guild labored to slip an operative into the hierarchy of the rapacious Venture Company. That asset, Taskmaster Fizzule, managed to ingratiate himself into their industrial drilling outpost north of Sludge Fen.",sp=0},{t="Signs and Signals",b="Operating deep within mercenary lines leaves no margin for error. Because Fizzule maintains a ruthless persona to satisfy his corporate overseers, any unannounced visitor risks immediate attack. To verify their identity, arriving rogues must fire twin flares from a designated signaling gun within sight of his tower, approach quietly, and perform the secret salute of the Shattered Hand before receiving his report on the Venture Company's escalating schemes.",sp=0}},faq={{q="Who is Taskmaster Fizzule?",a="Taskmaster Fizzule is a deep-cover operative of the Shattered Hand planted within the Venture Company hierarchy north of Sludge Fen. He spent a full year climbing into a position of authority among the mercenaries, watching their operations and feeding intelligence back to Orgrimmar.",al={"fizzule","who is fizzule","taskmaster fizzule identity"}},{q="Why does Fizzule attack if you do not signal him properly?",a="Fizzule is maintaining cover as an abrasive, hard-nosed Venture Company taskmaster. If anyone approaches his post without providing the exact two-flare signal and the Shattered Hand salute, he must assume they are hostile intruders or rival corporate agents, attacking them on sight to preserve his disguise.",al={"why does fizzule attack","fizzule hostile","fizzule kills me"}},{q="Where is the Venture Company tower located?",a="The tower stands overlooking the industrial operations just north of Sludge Fen, located in the central northern expanse of the Barrens.",al={"fizzule location","tower location","where is sludge fen tower"}},{q="Why is the Horde spying on the Venture Company?",a="The Venture Company is notorious for reckless resource stripping, exploitation, and ruthless violence across Kalimdor. Recent intelligence gathered by the Shattered Hand revealed the cartel is planning a major scheme in the Barrens, prompting Shenthul to activate his contact.",al={"why spy on venture co","venture co threat"}},{q="What happens after making contact with Fizzule?",a="Once contact is safely established, Fizzule gives the rogue instructions to infiltrate the nearby Venture Company tower, slay its inhabitants including Grand Foreman Puzik Gallywix, and steal the cache of Zanzil's Altered Mixture, proving their worth to the guild.",al={"what next after deep cover","after fizzule"},sp=1},{q="What is the Shattered Hand?",a="The Shattered Hand is the shadowy network of rogues, spies, and assassins operating out of the Cleft of Shadows in Orgrimmar. While once an infamous clan on Draenor, in the new Horde they serve as Thrall's covert intelligence arm.",al={"shattered hand","who are shattered hand"}}},ang={["class:Rogue"]="This assignment marks a critical milestone for growing rogues in the Horde, transitioning them from simple street scouts into trusted operatives capable of covert field coordination.",["faction:Horde"]="The Venture Company's relentless clear-cutting and drilling in the Barrens threatens Horde territorial control and natural resources, necessitating aggressive espionage."},kw={"barrens rogue","deep cover","flare gun","shattered hand","shenthul","sludge fen","taskmaster fizzule","venture company"},rel={"npc:shenthul","quest:2460","quest:2478","subzone:sludge-fen","topic:venture-company","quest:1858"},m={start="Shenthul",["end"]="Taskmaster Fizzule",level="20",faction="Horde",id=2458},src={"Deep Cover"}}
E["quest:2460"] = {t="quest",n="The Shattered Salute",z="orgrimmar",s="The Shattered Salute is an initiation ritual overseen by Shenthul within the Cleft of Shadows in Orgrimmar. By learning this distinct sign of recognition, budding rogues are taught how to safely identify fellow operatives of the Shattered Hand in the field.",h="The Shattered Salute is an initiation ritual overseen by Shenthul within the Cleft of Shadows in Orgrimmar.",sec={{t="Signs and Shadows",b="Within the dark tunnels of the Cleft of Shadows, the Shattered Hand operates as the clandestine intelligence and assassination arm of Thrall's Horde. Given the dangerous and secretive nature of their assignments, operatives cannot rely on overt banners or standard military heraldry. Shenthul instructs newly inducted rogues in the Shattered Salute, a specific gesture meant to serve as an unmistakable, silent signal among allies.",sp=0},{t="Preparation for the Field",b="Mastering the salute is not merely a ceremonial exercise; it is vital tradecraft. Rogue agents sent into perilous territory or tasked with infiltrating rival factions must verify contacts without alerting bystanders or targets. Shenthul insists that an operative be able to recognize and mirror the gesture effortlessly before entrusting them with covert fieldwork.",sp=0}},faq={{q="What is the purpose of the Shattered Salute?",a="The Shattered Salute serves as a covert recognition signal among members of the Shattered Hand. It allows operatives to identify one another in deep cover or hostile territory without exposing their true affiliations to outsiders.",al={"why do i need the salute","shattered salute purpose","what does the salute do"}},{q="Who teaches the Shattered Salute?",a="The salute is taught by Shenthul, a rogue trainer stationed deep within the Cleft of Shadows beneath Orgrimmar.",al={"who gives the quest","who is shenthul","where do i learn the salute"}},{q="What organization uses this gesture?",a="It is used by the Shattered Hand, an order of orcish rogues, spies, and assassins that serves the modern Horde from the shadows of Orgrimmar.",al={"shattered hand clan","who are the shattered hand","what guild uses this"}},{q="Why is learning the salute necessary before going into the field?",a="Operatives sent on infiltration assignments, such as making contact with undercover agents, rely on the salute to avoid blowing their cover or mistaking an enemy for an ally.",al={"why practice salute","is the salute required"}},{q="Where does this training take place?",a="The training takes place in the Cleft of Shadows, the subterranean district beneath Orgrimmar where rogues, warlocks, and other practitioners of forbidden arts gather away from public scrutiny.",al={"salute location","where is shenthul located"}},{q="What assignment follows after mastering the salute?",a="Once Shenthul is satisfied with an operative's mastery of the salute, he assigns them to deep cover operations, testing their ability to use the signal to contact agents in the field.",al={"what comes next","next quest after salute","deep cover quest"}}},ang={["class:Rogue"]="For a Horde rogue, mastering the Shattered Hand's secret signals represents the transition from an ordinary cutpurse to a trusted agent of Orgrimmar's intelligence network.",["faction:Horde"]="Though Warchief Thrall leads with honor, the Horde relies heavily on the clandestine methods of the Shattered Hand to neutralize threats before they reach the surface."},kw={"cleft of shadows","covert","deep cover","orgrimmar","rogue","shattered hand","shattered salute","shenthul"},rel={"npc:shenthul","quest:2458","quest:1858"},m={start="Shenthul",level="20",faction="Horde",id=2460},src={"The Shattered Salute"}}
E["quest:2478"] = {t="quest",n="Mission: Possible But Not Probable",z="orgrimmar",s="This critical assignment tests a Horde rogue's stealth, thievery, and combat skills against a rogue Venture Company outpost in the northern Barrens. Operatives infiltrate an oil tower, assassinate Grand Foreman Puzik Gallywix, and seize a potent chemical concoction for the Shattered Hand.",h="This critical assignment tests a Horde rogue's stealth, thievery, and combat skills against a rogue Venture...",sec={{t="Infiltration of the Venture Co.",b="North of the Sludge Fen oil rigs, the Venture Company maintains an isolated drilling tower. Under orders from Taskmaster Fizzule, an embedded Shattered Hand operative posing as a Venture Company supervisor, rogues are instructed to use classic underworld methods rather than outright assault. Entering the tower requires pickpocketing the outpost key directly off Foreman Silixiz before mounting an ascent through heavily altered workers and sentries.",sp=0},{t="A Chemical Catastrophe",b="The inhabitants of the tower have been profoundly affected by an experimental substance: Zanzil's Altered Mixture. While the venom has weakened the guards—making them unusually susceptible to swift strikes, bleeding attacks, and sudden ambush—it has also left the facility highly volatile. At the summit lurks Grand Foreman Puzik Gallywix, guarding a lockbox containing the volatile brew itself.",sp=1},{t="The Price of Duty",b="Cracking Gallywix's lockbox inevitably exposes the rogue to the insidious vapors of the altered mixture, inflicting a debilitating, long-lasting affliction that breaks stealth and saps vitality. The mission concludes back in Orgrimmar with the Shattered Hand mentor Shenthul, who receives Gallywix's head and the chemical sample, while quietly mourning Fizzule's compromised position and dispatching the dying agent to find a cure.",sp=2}},faq={{q="Where is the Venture Co. Tower located?",a="The tower sits in the northern reaches of the Barrens, just north of the Sludge Fen drilling operation. It stands surrounded by hostile Venture Company workers, with Taskmaster Fizzule hiding near a tree immediately to the east.",al={"venture co tower location","where is gallywix tower","sludge fen tower"}},{q="How do you obtain the key to the tower?",a="The tower key belongs to Foreman Silixiz, who wanders the grounds outside the tower base. You must use stealth and pick his pockets to acquire the key; slaying him will not yield the item.",al={"silixiz tower key","how to get tower key","where is the key"}},{q="What is Zanzil's Altered Mixture?",a="It is an alchemical concoction derived from the notorious troll witch doctor Zanzil's formulas. The Venture Company acquired the substance, but its unstable fumes poisoned the workforce in the tower, rendering them sickly, mutated, and vulnerable to rogue combat arts.",al={"zanzil mixture","what is the poison","altered mixture"}},{q="Why am I unable to stealth after opening the lockbox?",a="Opening Gallywix's lockbox releases concentrated fumes of the altered mixture. The resulting toxic debuff persists for days, sapping your attributes and breaking your ability to remain hidden until cured by an experienced apothecary.",al={"touch of zanzil","poisoned after chest","can't stealth rogue quest","7 day poison"},sp=1},{q="Who is Taskmaster Fizzule?",a="Fizzule is a deep-cover operative for the Shattered Hand, the rogue guild of the Horde. A Dark Iron dwarf posing as a ruthless Venture Company taskmaster in the Barrens, he directs recruits to sabotage Venture Company assets without blowing his own cover.",al={"fizzule","who gave this quest","fizzule lore"}},{q="Who is Grand Foreman Puzik Gallywix?",a="Grand Foreman Puzik Gallywix is the goblin overseer commanding the Venture Company tower near Sludge Fen. He safeguards the stolen cache of Zanzil's concoction until slain by Shattered Hand operatives.",al={"puzik gallywix","is gallywix in barrens","foreman gallywix"}}},ang={["class:Rogue"]="This rite of passage teaches practical fieldwork in lockpicking, pickpocketing, and vulnerability exploitation, serving as the gateway to the Shattered Hand's deadly tradecraft and poisons.",["faction:Horde"]="The Shattered Hand operates out of the shadows of Orgrimmar, keeping tabs on dangerous corporate intruders like the Venture Company who exploit the Barrens."},kw={"barrens","fizzule","lockpicking","poisons","puzik gallywix","shattered hand","shenthul","silixiz","sludge fen","zanzil"},rel={"quest:2458","quest:2479","quest:1858","npc:shenthul","subzone:sludge-fen","quest:764","zone:barrens","zone:orgrimmar"},m={start="Taskmaster Fizzule",["end"]="Shenthul",level="21",faction="Horde",id=2478},src={"Mission: Possible But Not Probable"}}
E["quest:2479"] = {t="quest",n="Hinott's Assistance",z="orgrimmar",s="Hinott's Assistance is an urgent journey undertaken by Horde rogues suffering from a debilitating tropical toxin. Contracted during an infiltration mission in the Barrens, the affliction requires the specialized expertise of Serge Hinott in Tarren Mill. Seeking his aid promises both a life-saving cure and instruction in the art of concocting deadly poisons.",h="Hinott's Assistance is an urgent journey undertaken by Horde rogues suffering from a debilitating tropical...",sec={{t="A Toxic Predicament",b="Following the daring infiltration of the Venture Company's tower north of the Sludge Fen, rogues find themselves afflicted by Zanzil's altered mixture. The poison wreaks havoc on the body, dulling reflexes and threatening life itself. Recognizing the severity of the affliction, rogue trainer Shenthul in Orgrimmar admits that local remedies are inadequate and directs the poisoned operative across the sea to the Eastern Kingdoms.",sp=0},{t="Journey to Tarren Mill",b="The search for a cure leads south through the continent of Lordaeron to the village of Tarren Mill in Hillsbrad Foothills. There resides Serge Hinott, an apothecary whose fascination with virulent brews makes him ideally suited to analyze the exotic sample. While ordinary healers recoiled from Zanzil's venom, Hinott treats the deadly compound with professional glee, eager to dissect the foul concoction and instruct worthy rogues in brewing their own venoms.",sp=0}},faq={{q="Why do I need to see Serge Hinott?",a="Serge Hinott is an expert apothecary residing in Tarren Mill who specializes in rare toxins and their antidotes. Ordinary healers cannot purge Zanzil's altered mixture, making Hinott the only contact capable of analyzing the compound, saving your life, and teaching the art of poisoncraft.",al={"why hinott","who cures the poison","serge hinott role"}},{q="Where is Tarren Mill located?",a="Tarren Mill is a Forsaken settlement in northern Hillsbrad Foothills. From Orgrimmar, take the zeppelin to the Undercity in Tirisfal Glades, then travel south through Silverpine Forest and turn east along the road into Hillsbrad.",al={"tarren mill location","how to get to tarren mill","where is hinott"}},{q="How did I get poisoned in the first place?",a="You were infected during the covert task Mission: Possible But Not Probable at the Venture Company tower north of the Sludge Fen in the Barrens. Opening the high-security chest exposed you to Zanzil's altered mixture, leaving a lingering, debilitating affliction.",al={"how did i get zanzil poison","mission possible poison","why am i poisoned"}},{q="What happens after Serge Hinott receives the sample?",a="Once Hinott receives the sample, he examines its properties and prepares an antidote to cleanse your system. After curing the toxin, he shares his expertise, allowing rogues to master the brewing and application of their own poisons.",al={"hinott quest follow up","do i get cured","after hinotts assistance"},sp=1},{q="Who is Shenthul and why did he send me away?",a="Shenthul is the rogue trainer of the Shattered Hand, located in the Cleft of Shadow in Orgrimmar. He oversaw your test of skill in the Barrens and recognized that Zanzil's concoction was far beyond Orgrimmar's medical knowledge, requiring a specialist in Hillsbrad.",al={"who is shenthul","shenthul orgrimmar","why did trainer send me"}},{q="Can any other class complete this quest?",a="No. This mission is part of the dedicated rogue training lineage that unlocks the fundamental discipline of brewing poisons and remedies.",al={"rogue only quest","can warriors do hinotts assistance"}}},ang={["class:Rogue"]="This rite of passage bridges the gap between simple stealth and the alchemical arts, testing a rogue's stamina while opening the door to self-crafted venoms.",["faction:Horde"]="The mission illustrates the practical cooperation binding Kalimdor's orc and troll rogues with the sinister alchemical knowledge of the Forsaken in Lordaeron."},kw={"hillsbrad foothills","hinott's assistance","rogue poison quest","serge hinott","shenthul","tarren mill","undercity zeppelin","zanzil","zanzil's mixture"},rel={"npc:serge-hinott","quest:2478","npc:shenthul","subzone:tarren-mill","zone:hillsbrad","zone:undercity"},m={start="Shenthul",["end"]="Serge Hinott",level="21",faction="Horde",id=2479},src={"Hinott's Assistance"}}
E["quest:2751"] = {t="quest",n="Barbaric Battlements",z="orgrimmar",s="Barbaric Battlements is the opening trial set by Orokk Omosh, an aging blacksmith in Orgrimmar desperate to preserve his ancestral legacy. Having no heirs, Orokk demands that an aspiring smith demonstrate fundamental mastery over bronze and basic craftsmanship before he reveals the secrets of his craft.",h="Barbaric Battlements is the opening trial set by Orokk Omosh, an aging blacksmith in Orgrimmar desperate to...",sec={{t="The End of the Omosh Line",b="Orokk Omosh stands over the anvils of Orgrimmar bearing a heavy burden. For twenty generations, his family has worked the forge, shaping countless tons of ore into devastating weapons and rugged armor for the Horde. Tragically, Orokk considers himself a personal failure of his lineage, being kinless and unable to sire offspring. Facing the absolute extinction of the Omosh craft, he has chosen to set aside bloodline pride and seek out an apprentice capable of carrying forward his family's armory traditions.",sp=0},{t="A Test of Metal and Tooth",b="Orokk refuses to pass down his secrets to an amateur. To prove their basic competence at the anvil, he demands two patterned bronze bracers, two bronze greatswords, and a pair of sharp beast claws. For Orokk, true blacksmithing is not an art of idle luxury; its highest honor is seeing armor and steel bathed in the blood of enemies. Fulfilling his demands convinces the old smith that his lineage's legacy might endure in spirit, opening the door to deeper metalworking techniques.",sp=0}},faq={{q="Who is Orokk Omosh?",a="Orokk Omosh is a master blacksmith residing in Orgrimmar. He represents the twentieth generation of blacksmiths in the Omosh line, but lacking kin or heirs, he is determined to train an outsider rather than allow his clan's trade secrets to vanish.",al={"orokk omosh","who is orokk","omosh blacksmith"}},{q="Why does Orokk need someone else to teach?",a="Orokk cannot produce offspring and has no surviving kin to inherit his workshop. Without an apprentice to pass his blueprints and techniques to, twenty generations of hard-won smithing knowledge would die with him.",al={"why apprentice","orokk heir","why omosh legacy dying"}},{q="What items are required to prove competence to Orokk?",a="Orokk demands two patterned bronze bracers, two forged bronze greatswords, and two sharp claws taken from fierce predatory beasts.",al={"what do i need for barbaric battlements","items for barbaric battlements","barbaric battlements turn in"}},{q="What comes after completing Barbaric Battlements?",a="Satisfied with your fundamental mastery of bronze, Orokk continues your training with 'On Iron Pauldrons', advancing toward heavier iron forging and complex plate armor crafting.",al={"next quest","chain after barbaric battlements","what follows"}}},ang={["profession:Blacksmithing"]="For Horde blacksmiths, this task marks a major milestone in transitioning from basic bronze and copper crafting to intermediate armor traditions.",["faction:Horde"]="The Omosh legacy reflects the Horde's martial ethos: metalwork is meant to be tested in combat and drenched in the blood of foes."},kw={"barbaric battlements","blacksmithing","bronze","legacy","omosh","orgrimmar","orokk omosh"},rel={"npc:orokk-omosh","quest:2753","quest:2755","zone:orgrimmar","zone:thousandneedles"},m={faction="Horde",id=2751},src={"Barbaric Battlements"}}
E["quest:2753"] = {t="quest",n="Trampled Under Foot",z="orgrimmar",s="Trampled Under Foot is an advanced blacksmithing trial assigned by Orokk Omosh in the Valley of Honor in Orgrimmar. By forging an array of green iron armor pieces, smiths prove their endurance and master the craft of heavy iron boots. Completion of the task earns the secret techniques passed down through the Omosh bloodline.",h="Trampled Under Foot is an advanced blacksmithing trial assigned by Orokk Omosh in the Valley of Honor in...",sec={{t="The Trials of Omosh",b="Orokk Omosh trains armorsmiths in Orgrimmar with relentless, physical demands. To Orokk, metalworking is not merely heating ore and hammering shapes; it is an endurance test designed to honor his ancestral clan. Trampled Under Foot represents the third trial in his rigorous chain of tasks, demanding repeated crafting of tempered green iron armor to forge muscle and discipline in the artisan.",sp=0},{t="Legacy of Chief Gorokk",b="Smiths who deliver the requested suits of green iron gear earn rare praise from the gruff armorsmith. Orokk likens an artisan who survives this grueling workload to his grandfather, Chief Gorokk of Omosh. In exchange for the crafted armor, Orokk imparts the ancestral design for sturdy iron boots—footwear intended to ensure Horde warriors crush their enemies beneath their heel.",sp=0}},faq={{q="Who offers the quest Trampled Under Foot?",a="The quest is given by Orokk Omosh, an orc armorsmith located in the Valley of Honor within Orgrimmar.",al={"quest giver","who gives trampled under foot","orokk omosh location"}},{q="What does Orokk Omosh require for this trial?",a="Orokk requires four Green Iron Helms, four Green Iron Bracers, and two Green Iron Leggings, proving the smith's mastery over green iron craftsmanship.",al={"trampled under foot turn in","what items needed","materials needed"}},{q="What is the lore behind the Omosh training chain?",a="Orokk Omosh tests young smiths through punishing physical labor to uphold the martial heritage of his ancestors. He believes that grueling armorsmithing builds the strength necessary to create gear that withstands brutal warfare.",al={"why does orokk make you craft armor","omosh clan lore"}},{q="Who is Chief Gorokk of Omosh?",a="Chief Gorokk of Omosh is the grandfather of Orokk Omosh. Orokk holds his grandfather's martial prowess in high esteem, comparing any smith who endures his heavy ironwork trials to the legendary chieftain.",al={"chief gorokk","orokk grandfather"}},{q="What quest precedes Trampled Under Foot?",a="Trampled Under Foot directly follows the quest On Iron Pauldrons, continuing Orokk's multi-part series of armorsmithing challenges.",al={"prerequisite quest","previous quest in chain"}},{q="What is the next quest after completing Trampled Under Foot?",a="Upon completing this task, Orokk Omosh offers Horns of Frenzy, the next of his two remaining lessons before the series ends with Joys of Omosh.",al={"next quest","what comes after trampled under foot"}}},ang={["profession:Blacksmithing"]="This quest represents a key milestone for aspiring armorsmiths in the Horde, requiring extensive iron smelting and green dye preparation to unlock exclusive boot plans.",["faction:Horde"]="Orokk's lessons supply durable iron armor patterns tailored to the brutal combat doctrine favored across Horde warfronts."},kw={"armorsmithing","blacksmithing","gorokk","green iron","orgrimmar","orokk omosh","trampled under foot","valley of honor"},rel={"npc:orokk-omosh","quest:2751","zone:orgrimmar"},m={start="Orokk Omosh",faction="Horde",id=2753},src={"Trampled Under Foot"}}
E["quest:2755"] = {t="quest",n="Joys of Omosh",z="orgrimmar",s="Joys of Omosh is a heartwarming closing moment between the blacksmith Orokk Omosh and an adventurer who has helped him in Orgrimmar. Moved to tears, the veteran smith insists that soot is just in his eye before demonstrating a cherished family tradition. By performing the vigorous Omosh dance of joy, he passes down an unusual bit of family heritage.",h="Joys of Omosh is a heartwarming closing moment between the blacksmith Orokk Omosh and an adventurer who has...",sec={{t="A Soot-Stained Tear",b="Orokk Omosh is a burly blacksmith working near the scorching heat of the forge in Orgrimmar, known more for heavy strikes on the anvil than emotional displays. Yet after receiving great aid from an adventurer, even this rugged craftsman finds himself overwhelmed. He stubbornly insists that a stray bit of soot got into his eye rather than admitting to weeping openly.",sp=0},{t="The Omosh Tradition",b="Rather than parting ways quietly, Orokk insists on sharing one final secret of the Omosh lineage before he can die happy. He immediately launches into the vigorous and exhausting Omosh dance of joy, demonstrating the animated tradition for his apprentice before teaching them to strike with an iron fist.",sp=0}},faq={{q="Who is Orokk Omosh?",a="Orokk Omosh is an orc blacksmith located in the Valley of Honor in Orgrimmar. He is fiercely proud of his family's craft and lineage, blending smithing expertise with lively personal traditions.",al={"who is orokk","orokk omosh backstory","orokk blacksmith"}},{q="Why is Orokk crying?",a="Orokk insists that he is not crying and that it is simply forge soot trapped in his eye. In truth, he is deeply moved and touched by the adventurer's assistance, having found someone worthy to share his family's traditions with.",al={"why orokk cry","is orokk sad","soot in eye"}},{q="What is the Omosh dance of joy?",a="The dance of joy is a vigorous physical routine passed down through the Omosh family line. Performing it is deeply tiring for Orokk, who has not practiced the celebratory dance in a very long time.",al={"omosh dance","dance of joy","what is the dance"}},{q="Where does this quest take place?",a="The quest takes place in Orgrimmar, specifically around the blacksmithing forge in the Valley of Honor where Orokk Omosh works his metal.",al={"quest location","where is joys of omosh","orgrimmar forge"}},{q="What does Orokk teach you?",a="Beyond demonstrating the energetic Omosh dance of joy, Orokk promises to pass on the knowledge of the fist of iron, cementing the bond between smith and adventurer.",al={"omosh reward","what do i learn","fist of iron"}},{q="Can Alliance players participate in this quest?",a="No. Orokk Omosh is allied with the Horde and resides within the fortified walls of Orgrimmar, making this interaction exclusive to Horde adventurers.",al={"alliance joys of omosh","is this horde only"}}},ang={["profession:Blacksmithing"]="For smiths accustomed to the harsh, stoic heat of the forge, Orokk's sentimental family dance offers an unusually humorous and tender look into the personal life of a veteran craftsman.",["faction:Horde"]="The Valley of Honor is a hub of martial pride, making Orokk's tearful joy and spirited dance an endearing sight amidst Orgrimmar's clashing steel."},kw={"blacksmith","dance of joy","joys of omosh","orgrimmar","orokk omosh","soot in eye","valley of honor"},rel={"npc:orokk-omosh"},m={start="Orokk Omosh",level="15-30",faction="Horde",id=2755},src={"Joys of Omosh"}}
E["quest:2950"] = {t="quest",n="Nogg's Ring Redo",z="orgrimmar",s="Nogg's Ring Redo concludes the investigation of a grime-encrusted trinket brought back from the ruins of Gnomeregan to Orgrimmar. In exchange for rare materials and valuable intel on Dark Iron dwarven activity, the goblin engineer Nogg refines the recovered jewelry, eager to prove goblin craft superior to gnomish design.",h="Nogg's Ring Redo concludes the investigation of a grime-encrusted trinket brought back from the ruins of...",sec={{t="Goblin Superiority",b="When an adventurer returns a cleaned gold ring recovered from Gnomeregan's depths to Nogg's workshop in the Valley of Honor, the engineer's natural pride takes over. Snubbing the original craftsmanship as the modest work of a gnome, Nogg offers a deal. For raw materials and a modest fee, he promises to improve upon the Alliance trinket, fashioning an intricate silver and moss agate lattice designed to amplify the magic running through the band.",sp=0},{t="A Dwarven Angle",b="Nogg's sudden willingness to enhance the ring is not entirely driven by commercial interest. The reports of Dark Iron dwarves lurking within the besieged gnome city catch his keen attention. To Nogg, the dwarven presence explains why gnomes managed to construct sudden bursts of mechanical sophistication—something goblins consider uniquely their own domain. Gathering that intelligence earns the adventurer an upgraded piece of jewelry and Nogg's grudging respect.",sp=1}},faq={{q="Who is Nogg?",a="Nogg is a prominent goblin engineer operating in the Valley of Honor within Orgrimmar. He works closely with fellow tinkerers in the Drag and the Valley of Honor, frequently handling curious mechanical artifacts and schematics recovered from dangerous expeditions.",al={"who is nogg","nogg orgrimmar","nogg npc"}},{q="What materials are needed to reforge the ring?",a="Nogg requires the original Brilliant Gold Ring, one Silver Bar, one Moss Agate, and thirty silver coins to pay for his labor and workshop expenses.",al={"ring materials","nogg materials","what does nogg need"}},{q="Why is Nogg interested in Gnomeregan?",a="Gnomeregan holds immense technological value. Goblins fiercely compete with gnomes in technical fields, and Nogg is especially intrigued by rumors that Dark Iron dwarves were involved in the technological anomalies inside the fallen techno-city.",al={"why nogg care about gnomeregan","gnomeregan goblin interest"}},{q="What does Nogg actually do to the ring?",a="Nogg constructs a silver and moss agate lattice directly around the golden band. This delicate framework channels and stabilizes the latent enchantments resting within the jewelry, yielding a stronger, more potent piece than the original gnomish design.",al={"ring upgrade lore","what changes on the ring"}},{q="Where does this quest chain start?",a="The quest chain begins deep inside Gnomeregan when an adventurer loots a Grime-Encrusted Ring from one of the Dark Iron dwarves and washes it off using the Sparklematic 5200 machine.",al={"chain start","how to start nogg quest","ring questline start"}},{q="Why does Nogg suspect Dark Iron dwarves?",a="Goblin engineers view gnomish innovation with deep skepticism. To Nogg, any sudden spark of radical mechanical insight among gnomes must have been influenced or supplied by outside meddlers—namely the scheming Dark Iron clan.",al={"why dark irons","dark iron dwarf connection"}}},ang={["profession:Engineering"]="The quest illustrates the constant ideological rivalry between goblin ingenuity and gnomish gadgetry, highlighting the goblin approach of aggressively modifying existing tech for maximum output.",["faction:Horde"]="Recovering technology from Alliance-aligned halls like Gnomeregan and turning it over to Orgrimmar's tinkers provides the Horde with crucial insights into enemy capabilities.",["profession:Mining"]="Refining the recovered ring requires valuable earth extracts—a refined silver bar and a moss agate—demanding the services of skilled miners and gem-cutters."},kw={"brilliant gold ring","dark iron","gnomeregan","goblin engineering","moss agate","nogg","orgrimmar","silver bar"},rel={"quest:2947","quest:2945","npc:nogg","zone:orgrimmar","topic:goblin","topic:gnome","topic:horde"},m={start="Nogg",faction="Horde",id=2950},src={"Nogg's Ring Redo"}}
E["quest:2985"] = {t="quest",n="Call of Water",z="orgrimmar",s="Call of Water marks the beginning of a shaman's communion with the fluid element of healing and adaptability. Having already proved their mastery over earth and fire, an initiate is directed by Searn Firewarder in Orgrimmar to seek out the recluse Islen Waterseer on the eastern coast of the Barrens.",h="Call of Water marks the beginning of a shaman's communion with the fluid element of healing and adaptability.",sec={{t="A Shift in the Elements",b="A shaman's training demands balance. After learning the steadfast resilience of earth and enduring the wild ferocity of fire, initiates are called toward the flowing, adaptable nature of water. In Orgrimmar, the troll shaman Searn Firewarder assesses his students' spiritual growth. When an initiate has proven their command of flame without being consumed by it, Searn recognizes that their spirit is tempered enough to seek out the teachings of water.",sp=0},{t="The Recluse of the Merchant Coast",b="To learn the secrets of the water spirits, the shaman must travel south along the Southfury River into the Barrens and push east toward the coast, just beyond the bustling goblin port of Ratchet. There, by the ocean shore near the carcass of a massive shark, dwells Islen Waterseer. Unlike the cloistered trainers in the Valley of Spirits, Islen lives where the salt waves relentlessly meet the land, serving as the Horde's principal guide for communion with water.",sp=0}},faq={{q="Who gives this quest?",a="Searn Firewarder, a troll shaman trainer residing in the Valley of Spirits in Orgrimmar, gives this task once you have proven your command over fire and earth.",al={"quest giver","who starts call of water","searn firewarder"}},{q="Where can I find Islen Waterseer?",a="Islen Waterseer lives along the eastern coast of the Barrens, just south of Ratchet. Follow the Southfury River south out of Durotar, head toward the shore past Ratchet, and look for her camp marked by a large beached shark.",al={"where is islen","islen location","how to find islen waterseer"}},{q="Why must a shaman learn the elements in a specific order?",a="Shamanic tradition requires an initiate to build spiritual balance step by step. Grounded by earth and tempered by fire, the soul becomes steady enough to withstand the fluid, shifting purity of water without being swept away.",al={"element order","why water after fire","shaman progression"}},{q="Is this quest available to other classes?",a="No. The Call of Water quests are exclusive to shamans seeking to earn the favor of the water spirits and manifest their Water Totem.",al={"can non shaman do this","is call of water shaman only"}},{q="What landmark should I look for when searching for Islen?",a="Searn advises travelers to look for a massive beached shark along the shoreline south of Ratchet. Islen has made her dwelling right beside it.",al={"shark landmark","how to spot islen's camp","islen coast"}},{q="What happens after reaching Islen Waterseer?",a="Speaking to Islen begins the true trials of water, requiring the shaman to journey across Kalimdor to gather pure drops of water and confront spirits before earning the totem.",al={"next step","what does islen do","after call of water"},sp=1}},ang={["class:Shaman"]="This summons marks the critical transition from destructive fire and stalwart earth toward the restorative, restorative powers of water, unlocking the spiritual conduit required to cast healing totems.",["faction:Horde"]="Horde shamans across Kalimdor—whether orc, troll, or tauren—are directed to Islen Waterseer on the Barrens coast to undertake their watery communion."},kw={"call of water","islen waterseer","orgrimmar","ratchet","searn firewarder","shaman","southfury river","the barrens","water totem"},rel={"npc:islen-waterseer","npc:searn-firewarder","zone:barrens","subzone:ratchet","subzone:southfury-river"},m={start="Searn Firewarder",["end"]="Islen Waterseer",level="20",faction="Horde",id=2985},src={"Call of Water (Orgrimmar)"}}
E["quest:2996"] = {t="quest",n="Seeking Strahad",z="orgrimmar",s="Seeking Strahad is an essential rite of passage for Horde warlocks who have outgrown their basic summoning arts. Instructed by Gan'rul Bloodeye in the shadowy clefts of Orgrimmar, practitioners must travel south to Ratchet to study beneath a renegade human summoner.",h="Seeking Strahad is an essential rite of passage for Horde warlocks who have outgrown their basic summoning...",sec={{t="Leaving the Shadows of Orgrimmar",b="Within the dark crevices of the Cleft of Shadows, the orcish warlock trainer Gan'rul Bloodeye guides young practitioners in the treacherous art of commanding the Nether. Eventually, an apprentice warlock reaches a threshold where tribal tutelage is no longer sufficient. Gan'rul acknowledges that more volatile entities require specialized instruction, pointing his pupils outside the city walls to a figure possessing deeper mastery over dark arcana.",sp=0},{t="An Unorthodox Alliance",b="The tutor chosen by Gan'rul is Strahad Farsan, a human sorcerer dwelling in an isolated tower overlooking the goblin port of Ratchet. Despite the enduring hatred between the Horde and humankind, warlocks exist in a realm beyond conventional faction loyalties. Power, discipline, and ritual knowledge supersede ancestry, and Strahad cares far more for an apprentice's inner hatred and aptitude for subjugation than the color of their skin.",sp=0}},faq={{q="Why is an orc warlock sending me to a human?",a="Warlocks share a pragmatic philosophy that values dark knowledge over racial allegiances. Gan'rul Bloodeye recognizes that Strahad Farsan holds rare and formidable expertise in advanced demonology. In the pursuit of dangerous summons, a tutor's skill matters far more than faction boundaries.",al={"why learn from human","strahad human warlock","why strahad"}},{q="Where can I find Strahad Farsan?",a="Strahad Farsan resides on the high bluffs immediately overlooking the goblin port of Ratchet in the Barrens, standing outside his personal tower above the bustling docks.",al={"strahad location","where is strahad","strahad tower ratchet"}},{q="What power does Strahad teach?",a="Strahad guides warlocks through the complex rituals required to bind a felhunter—a voracious, magic-devouring demon of the Twisting Nether. His lessons delve into deep occult texts before testing your ability to enslave the beast.",al={"what does strahad unlock","what do i get from strahad","seeking strahad reward"},sp=1},{q="Who is Gan'rul Bloodeye?",a="Gan'rul Bloodeye is a prominent orc warlock mentor located in the Cleft of Shadows beneath Orgrimmar. He trains burgeoning Horde warlocks in the fundamentals of fel magic and summoning lesser minions.",al={"who is ganrul","ganrul bloodeye","orgrimmar warlock trainer"}},{q="Is there another way to start this quest?",a="Yes. Forsaken warlocks receive a parallel summons from the Magic Quarter in the Undercity, which directs them to the exact same human mentor above Ratchet.",al={"seeking strahad undercity","forsaken seeking strahad","undercity version"}},{q="Does Ratchet pose any danger to Horde warlocks?",a="Ratchet is operated by the Steamwheedle Cartel and functions as a strictly neutral port. As long as you maintain peace and do not attack fellow travelers within city bounds, goblin bruisers will leave you alone.",al={"is ratchet safe","ratchet guards hostile","neutral port"}}},ang={["class:Warlock"]="This quest marks your transition into mastering mid-tier demonic entities, testing your readiness to subjugate the magic-consuming felhunter.",["faction:Horde"]="The willingness of Horde masters to send apprentices to a solitary human demonstrates how warlock covens operate independently of the Warchief's formal diplomacy."},kw={"barrens","cleft of shadows","felhunter quest","gan'rul bloodeye","ratchet","seeking strahad","strahad farsan","tome of the cabal"},rel={"npc:strahad-farsan","npc:gan-rul-bloodeye","quest:1758","quest:1471","quest:1798","subzone:ratchet","zone:orgrimmar","topic:horde"},m={start="Gan'rul Bloodeye",["end"]="Strahad Farsan",level="30",faction="Horde",id=2996},src={"Seeking Strahad (Orgrimmar)"}}
E["quest:3923"] = {t="quest",n="Rilli Greasygob",z="orgrimmar",s="This quest sends an adventurer carrying a damaged samophlange from the tinkering tinker Wenikee Boltbucket directly to Orgrimmar. Seeking a specialist who truly understands the device's origins, Wenikee directs you to Rilli Greasygob, a former Venture Company engineer stationed in Nogg's Machine Shop.",h="This quest sends an adventurer carrying a damaged samophlange from the tinkering tinker Wenikee Boltbucket...",sec={{t="When Tinkering Fails",b="Wenikee Boltbucket tried her hand at diagnosing the samophlange recovered from the Venture Company drilling site in the Barrens. Unfortunately, adding extra gauges only confirmed that the apparatus was on the verge of total collapse. Recognizing that piling on more levers and dials might destroy the device entirely, Boltbucket admitted defeat and decided to refer the problem to someone with proprietary expertise.",sp=0},{t="A Former Company Man",b="To decipher the inner workings of the contraption, Boltbucket sends travelers into Orgrimmar's Valley of Honor to visit Nogg's Machine Shop. There works Rilli Greasygob, an engineer who once earned his trade within the cutthroat ranks of the Venture Company. Greasygob instantly recognizes the machine, marveling that anyone survived poking around the cartel's contested operations in the Barrens.",sp=0}},faq={{q="Who is Rilli Greasygob?",a="Rilli Greasygob is a goblin engineer working out of Nogg's Machine Shop in Orgrimmar's Valley of Honor. Having previously worked for the Venture Company, he possesses rare firsthand knowledge of the cartel's proprietary technology, including mysterious devices like the samophlange.",al={"rilli greasygob","who is rilli","nogg machine shop rilli"}},{q="Why couldn't Wenikee Boltbucket fix the samophlange herself?",a="Wenikee Boltbucket attempted to diagnose the samophlange by attaching extra gauges, but they revealed its structural integrity was rapidly deteriorating. Realizing that haphazard tinkering would only ruin the delicate apparatus, she decided it needed someone with direct Venture Company manufacturing experience.",al={"why send to rilli","boltbucket failure","wenikee cant fix"}},{q="Where is Rilli Greasygob located?",a="Rilli Greasygob is located inside Nogg's Machine Shop in the Valley of Honor, situated in the northeastern district of Orgrimmar.",al={"rilli greasygob location","where is greasygob","find rilli"}},{q="What is the Venture Company's role in this?",a="The samophlange was recovered from the Venture Company's strip-mining operation at the Sludge Fen in the northern Barrens. Because it is custom Venture Company technology, former company personnel like Rilli Greasygob are the only ones capable of properly servicing and interpreting it.",al={"venture co connection","why venture company","who made the samophlange"}},{q="What happens after giving the samophlange to Rilli?",a="Recognizing the device, Rilli Greasygob determines that to fully operate or reconstruct it, he will require the Venture Company's official operational instructions, leading adventurers to recover the Samophlange Manual.",al={"what next after rilli","samophlange questline continuation"},sp=1},{q="What is a samophlange anyway?",a="Nobody involved seems quite sure. It is an intricate, bizarre Venture Company device full of gears; even Wenikee Boltbucket had to ask what a samophlange was, and Rilli needs the company's own manual to make sense of it.",al={"what is a samophlange","samophlange explained"}}},ang={["profession:Engineering"]="Every engineer knows when to put down the wrench; Boltbucket's realization that more dials would only make matters worse leads straight to specialized trade secrets preserved by former corporate technicians.",["faction:Horde"]="The Horde relies on urban workshops like Nogg's in Orgrimmar to repurpose enemy machinery captured from predatory syndicates exploiting Kalimdor."},kw={"broken and battered samophlange","nogg's machine shop","orgrimmar","rilli greasygob","samophlange","valley of honor","venture company","wenikee boltbucket"},rel={"npc:nogg","quest:3921","quest:894","subzone:valley-of-honor","zone:orgrimmar","topic:venture-company","zone:barrens"},m={start="Wenikee Boltbucket",["end"]="Rilli Greasygob",level="18",faction="Horde",id=3923},src={"Rilli Greasygob (quest)"}}
E["quest:3924"] = {t="quest",n="Samophlange Manual",z="orgrimmar",s="Samophlange Manual is a quest given by goblin engineer Rilli Greasygob in Orgrimmar. Determined to repair a broken samophlange, Rilli sends adventurers back into the Barrens to wrest the device's proprietary operating instructions from his former Venture Company rival.",h="Samophlange Manual is a quest given by goblin engineer Rilli Greasygob in Orgrimmar.",sec={{t="Corporate Rivalries and Trade Secrets",b="Within the mercenary ranks of the Venture Company, technical knowledge is currency. Rilli Greasygob previously worked alongside Boss Copperplug, an overseer who guarded the internal mechanics of the mysterious samophlange with paranoid secrecy. Rather than sharing the manual, Copperplug parceled out individual pages only to trusted underlings, leaving peers like Rilli completely in the dark regarding its inner workings.",sp=0},{t="Infiltration of Boulder Lode",b="To decipher the complex contraption brought to him from the Barrens, Rilli sends travelers to infiltrate the Boulder Lode Mine in the northeastern Barrens. Recovering the manual requires tracking down Boss Copperplug directly and gathering whatever scattered pages he distributed among the mine's operations, finally assembling a complete guide to repairing the baffling device.",sp=1}},faq={{q="What is the Samophlange Manual?",a="It is the technical user's guide detailing the mechanics and repair procedures of the samophlange, a complex and eccentric mechanical device utilized by the Venture Company.",al={"what is the manual","samophlange manual item","user manual"}},{q="Who is Boss Copperplug?",a="Boss Copperplug is a Venture Company overseer stationed at the Boulder Lode Mine in the northeastern Barrens. He is a former rival of Rilli Greasygob who jealously hoarded the operating secrets and manual pages of the samophlange.",al={"copperplug","who is copperplug","boss copperplug"}},{q="Where is the Boulder Lode Mine located?",a="The Boulder Lode Mine is carved into the mountains in the northeastern region of the Barrens, north of the Crossroads and west of the coastline.",al={"boulder lode location","where is boulder lode","find boulder lode mine"}},{q="Why does Rilli Greasygob need the manual?",a="Rilli believes he can successfully repair and operate the broken samophlange brought to him from the Barrens, but the contraption's proprietary and convoluted design requires its official operating instructions.",al={"why rilli wants manual","why fix samophlange"}},{q="How does Sputtervalve fit into this task?",a="Sputtervalve is an associate based in Ratchet who originally sought information about the device and stays in touch with Rilli, sending word of gratitude and compensation for securing the machine's schematics.",al={"sputtervalve connection","ratchet goblin sputtervalve"}},{q="What happens after the manual is returned?",a="Rilli enthusiastically takes the manual to study its contents in hopes of finally getting the machine working, though fixing such an arcane contraption remains an ongoing mechanical puzzle.",al={"quest conclusion","does rilli fix it"}}},ang={["profession:Engineering"]="Engineers can appreciate the absurd secrecy of goblin corporate intellectual property, where complex schematics are torn apart and hoarded to prevent colleagues from duplicating inventions.",["faction:Horde"]="Assisting goblin specialists inside Orgrimmar helps secure valuable technical salvage while striking back against the predatory operations of the Venture Company in nearby territories."},kw={"barrens","boss copperplug","boulder lode mine","manual","orgrimmar","rilli greasygob","samophlange","sputtervalve","venture company"},rel={"quest:3923","quest:894","npc:sputtervalve","subzone:boulder-lode-mine","topic:venture-company","zone:orgrimmar","subzone:ratchet"},m={start="Rilli Greasygob",level="19",faction="Horde",id=3924},src={"Samophlange Manual (quest)"}}
E["quest:4737"] = {t="quest",n="In Search of Menara Voidrender",z="orgrimmar",s="Zevrost, a cynical warlock trainer lurking in Orgrimmar's Cleft of Shadow, directs seasoned practitioners to seek out Menara Voidrender in the Barrens. Despite his harsh warnings about the inevitable price of demonic corruption, he points ambitious warlocks toward an expert mentor capable of fashioning powerful arcane vestments.",h="Zevrost, a cynical warlock trainer lurking in Orgrimmar's Cleft of Shadow, directs seasoned practitioners to...",sec={{t="Warnings in the Shadows",b="Deep beneath Orgrimmar in the Cleft of Shadow, warlocks operate under a veil of uneasy tolerance. Zevrost is among the more bitter tutors in the dark arts, quick to sneer at ambitious acolytes striving for mastery. In his eyes, anyone delving deeper into fel magic is merely racing toward their own enslavement. He insists that it is only a matter of time before demonic addiction overtakes the practitioner completely, reducing even the most disciplined scholar into a thrall of the Twisting Nether.",sp=0},{t="The Path to Ratchet",b="Despite his contemptuous predictions, Zevrost concedes that other practitioners do not share his dreary outlook. Word has reached Orgrimmar of Menara Voidrender, a skilled warlock stationed on the bluffs overlooking the neutral goblin port of Ratchet. Menara seeks promising disciples to aid in crafting specialized implements to harness their arcane might. For warlocks eager to push their craft further, this summons marks the beginning of forging the legendary Enchanted Gold Bloodrobe.",sp=0},{t="A Pragmatic Fellowship",b="Upon finding Menara high above Ratchet, the nature of warlock society becomes starkly apparent. Menara observes that warlocks must set aside racial and cultural rivalries to support one another, as the demons they bargain with harbor no prejudice and show no mercy to anyone who falters. Sharing expertise and fashioning protective vestments is not done out of noble charity, but as a practical necessity to survive the hostile entities they bind to their service.",sp=0}},faq={{q="Who is Zevrost?",a="Zevrost is an orc warlock trainer residing in the Cleft of Shadow beneath Orgrimmar. He is deeply cynical regarding the pursuit of fel power, viewing all ambitious warlocks as fools destined to become slaves to demonic corruption.",al={"zevrost","zevrost lore","who starts in search of menara voidrender"}},{q="Who is Menara Voidrender?",a="Menara Voidrender is an accomplished warlock residing in the Barrens on the cliffs overlooking the goblin port of Ratchet. She acts as a mentor for rising warlocks, helping them gather rare reagents to construct potent ceremonial robes.",al={"menara voidrender","where is menara voidrender","who is menara"}},{q="Why does Zevrost think all warlocks are fools?",a="Zevrost believes that fel magic inevitably corrupts and enslaves anyone who attempts to master it. In his view, no practitioner has the will to avoid addiction, and striving for greater power merely accelerates their downfall.",al={"zevrost corruption","why does zevrost warn me"}},{q="Where can Menara Voidrender be found?",a="Menara is stationed in the Barrens, positioned on the high hills overlooking the coastal port of Ratchet. Warlocks must travel east across the arid savannah to reach her overlooking camp.",al={"menara location","find menara voidrender"}},{q="Why do warlocks from different races work together?",a="As Menara explains, the demonic forces summoned by warlocks show indiscriminately cruel malice to anyone who fails to control them. Because survival depends on absolute precision, warlocks regularly share knowledge and tools across cultural boundaries.",al={"warlock solidarity","why do warlocks band together"}},{q="What happens after finding Menara Voidrender?",a="Menara Voidrender immediately enlists the warlock to gather exotic and potent materials across Azeroth to construct the Enchanted Gold Bloodrobe, a protective garment attuned to fel energies.",al={"next quest after menara","what does menara want"}}},ang={["class:Warlock"]="This quest represents a pivotal rite of passage for Horde warlocks, sending them to assemble their own iconic Enchanted Gold Bloodrobe under Menara Voidrender's guidance.",["faction:Horde"]="Horde warlocks must constantly navigate the contempt of traditional shamans and warriors, finding shelter only in hidden recesses like Orgrimmar's Cleft of Shadow or neutral ground near Ratchet."},kw={"barrens","bloodrobe","cleft of shadow","fel magic","menara voidrender","ratchet","warlock robe","zevrost"},rel={"npc:zevrost","npc:menara-voidrender","subzone:ratchet","zone:barrens","quest:1796"},m={start="Zevrost",["end"]="Menara Voidrender",level="31",faction="Horde",id=4737},src={"In Search of Menara Voidrender (Orgrimmar)"}}
E["quest:5502"] = {t="quest",n="A Warden of the Horde",z="orgrimmar",s="A Warden of the Horde marks the heartwarming conclusion to Children's Week in Orgrimmar. Having shown young Grunth the wonders and heroes of Kalimdor, you fulfill his selfless final wish to bring foam swords back to his fellow orphans before safely returning him to Orphan Matron Battlewail.",h="A Warden of the Horde marks the heartwarming conclusion to Children's Week in Orgrimmar.",sec={{t="A Selfless Final Wish",b="Throughout Children's Week, adventurers escort young Grunth across the lands of the Horde, sharing adventures that orphaned youths in Orgrimmar rarely experience. Rather than asking for another personal adventure or grand souvenir, Grunth's final request looks outward to his peers. Remembering the toys sold by the goblin vendor Blax Bottlerocket along the busy avenues of the Drag, he asks for a rack of foam swords so that every child at the orphanage can play and train together.",sp=0},{t="Home to the Drag",b="Returning to the orphanage nestled in the Drag, adventurers deliver both the toys and their young charge back into the care of Orphan Matron Battlewail. Taking responsibility for the young is considered a profound duty in the new Horde, where war has left countless children without parents. Battlewail commends your compassion as the true measure of a hero of the Horde, and Grunth parts ways with a beloved pet to ensure you remember the bond forged during your travels.",sp=0}},faq={{q="What is the purpose of this quest?",a="This quest concludes the Horde's Children's Week festivities. After journeying together, you buy a foam sword rack for the other orphans from Blax Bottlerocket and return Grunth to Orphan Matron Battlewail in the Drag.",al={"warden of the horde summary","childrens week ending horde"}},{q="Who is Grunth?",a="Grunth is an orcish youth residing at the Orgrimmar Orphanage in the Drag. During Children's Week, he is paired with a Horde champion who takes him across Kalimdor to see legendary figures and grand sights.",al={"who is the orc orphan","grunth lore"}},{q="Where can I find Blax Bottlerocket?",a="Blax Bottlerocket is a goblin wandering vendor who pushes his toy cart up and down the main thoroughfare of the Drag in Orgrimmar.",al={"blax bottlerocket location","where is the toy vendor"}},{q="Who oversees the orphans in Orgrimmar?",a="Orphan Matron Battlewail manages the Orgrimmar Orphanage in the Drag, dedicating her life to sheltering and raising the Horde's war orphans.",al={"orphan matron horde","who runs the orphanage"}},{q="Why does Grunth want a foam sword rack?",a="Grunth feels fortunate to have seen the world during the festival and wants to bring joy back to the other orphans. A rack of foam swords allows all the children to play and practice their martial skills together.",al={"why foam swords","grunth final wish"}},{q="Why is Children's Week important to the Horde?",a="Decades of relentless warfare against demons, humans, and centaur have left countless Horde children without families. Children's Week is a time for warriors to step away from the battlefield and honor the future generations of Durotar and beyond.",al={"childrens week lore","why care for orphans horde"}}},ang={["faction:Horde"]="For the Horde, strength is not merely martial prowess; it is the collective will to protect and uplift the vulnerable who will one day carry the banner of the Warchief.",["race:Orc"]="Orcish culture prizes courage and honor, and showing compassion to an orphaned child like Grunth exemplifies the nobility Thrall seeks to instill in the new Horde."},kw={"battlewail","blax bottlerocket","children's week","drag","foam sword rack","grunth","orgrimmar","orphan"},rel={"npc:orphan-matron-battlewail","npc:grunth","zone:orgrimmar","subzone:drag","topic:horde"},m={start="Orcish Orphan",["end"]="Orphan Matron Battlewail",faction="Horde",id=5502},src={"A Warden of the Horde"}}
E["quest:5643"] = {t="quest",n="Shadowguard",z="orgrimmar",s="Shadowguard is a priestly calling issued to Darkspear troll priests who find themselves far from home in the Forsaken capital of Undercity. Aelthalyste recognizes that the young troll has matured enough for their tribe's sacred rites and sends them back to Orgrimmar. In the Valley of Spirits, the priest trainer Ur'kyo awaits to guide them into a vital tier of spiritual protection.",h="Shadowguard is a priestly calling issued to Darkspear troll priests who find themselves far from home in the...",sec={{t="A Summons Across Continents",b="Even in the gloom of the Undercity, the bonds of faith and tribal tradition remain strong. Forsaken priest trainer Aelthalyste observes visiting troll priests closely, noting when an initiate has grown potent enough to face their culture's trials. Rather than imposing the bleak philosophy of the Cult of Forgotten Shadow upon them, she directs the troll back across the Great Sea to the ancestral ways of their own elders.",sp=0},{t="The Valley of Spirits",b="Upon arriving in Durotar, the priest makes their way to the mystic enclave of the Valley of Spirits in Orgrimmar. There, Ur'kyo tends to the spiritual needs and ancient rituals of the Darkspear tribe. He welcomes the returning initiate, preparing them for an essential rite of passage that bridges the priest's bond to the loa with practical spells vital for warding off harm.",sp=0}},faq={{q="Who starts this quest?",a="The quest is given by Aelthalyste, a priest trainer residing in the War Quarter of the Undercity. She recognizes when a troll priest has reached the maturity needed for their tribe's spiritual trials.",al={"quest giver","where do i start","who gives shadowguard"}},{q="Why does an Undercity trainer send me to Orgrimmar?",a="While Forsaken priests practice the Cult of Forgotten Shadow, Darkspear trolls draw their spiritual power from the loa and their tribal traditions. Aelthalyste respects this divide and sends developing troll priests home to learn their unique racial arts from their own elder.",al={"why go to orgrimmar","undercity to orgrimmar","why ur'kyo"}},{q="Who is Ur'kyo?",a="Ur'kyo is a prominent Darkspear troll priest trainer stationed in the Valley of Spirits within Orgrimmar. He serves as an instructor and mentor in troll spiritual customs and rites of passage.",al={"ur'kyo lore","who is urkyo","priest trainer ur'kyo"}},{q="What is the significance of the Shadowguard ability?",a="Shadowguard is a protective ward unique to troll priests. Calling upon shadowy spirits and loa blessings, it manifests as orbiting shadows that retaliate and strike any enemy foolish enough to attack the caster.",al={"what is shadowguard","shadowguard spell lore","why is it important"}},{q="Do other races receive this quest?",a="This particular summons is exclusively for Darkspear troll priests who happen to visit the Undercity around their twentieth season of experience. Forsaken priests have their own separate rites and training under the Cult of Forgotten Shadow.",al={"can undead do this","is this troll only","priest race quest"}},{q="Where in Orgrimmar is Ur'kyo located?",a="Ur'kyo can be found in the Valley of Spirits, the southern district of Orgrimmar set aside for the Darkspear trolls and their mystical practices.",al={"where is ur'kyo","urkyo location","find ur'kyo"}}},ang={["class:Priest"]="This rite marks a defining milestone in a priest's path, separating the universal basics of holy and shadow magic from the distinct cultural traditions of their people.",["race:Troll"]="For the Darkspear, training in the priesthood is inseparable from communion with the loa and the defense of the tribe, an inheritance preserved by Ur'kyo in the Valley of Spirits.",["race:Undead"]="Trainers like Aelthalyste acknowledge the distinct traditions of their living allies, ensuring visiting trolls receive instruction from their own elders rather than forcing Forsaken doctrine upon them."},kw={"aelthalyste","orgrimmar","rite of passage","shadowguard","troll priest","undercity","ur'kyo","valley of spirits"},rel={"npc:ur-kyo","npc:aelthalyste","subzone:valley-of-spirits","zone:orgrimmar"},m={start="Aelthalyste",["end"]="Ur'kyo",level="20",faction="Horde",id=5643},src={"Shadowguard (Undercity)"}}
E["quest:5646"] = {t="quest",n="Devouring Plague",z="orgrimmar",s="Devouring Plague is a rite-of-passage quest for Forsaken priests who have ventured to Kalimdor to learn from the Darkspear tribe. The troll priest trainer Ur'kyo in Orgrimmar directs promising Forsaken initiates to return home to Undercity, where Aelthalyste waits to impart deeper teachings of the Cult of Forgotten Shadow.",h="Devouring Plague is a rite-of-passage quest for Forsaken priests who have ventured to Kalimdor to learn from...",sec={{t="A Exchange of Faiths",b="While the orcs and tauren have little inclination toward priestly worship, the Darkspear trolls and the Forsaken share a curious theological bond within the Horde. In Orgrimmar, the troll priest trainer Ur'kyo guides those drawn to spiritual power. Yet he recognizes that Forsaken initiates must ultimately master the sinister arts unique to their own condition. In a mutual show of respect between their peoples, Ur'kyo directs wandering Forsaken back to Lordaeron to complete their training.",sp=0},{t="The War Quarter of Undercity",b="Beneath the ruins of Lordaeron, Priestess Aelthalyste tends to the flock in the Undercity's War Quarter. Forsaken priests walk a solitary, grueling path shaped by the Cult of Forgotten Shadow, tempering the painful touch of the Holy Light with the devastating affliction of Shadow magic. When an initiate attains sufficient prowess, Aelthalyste gathers them close to bestow the affliction known to their kind as the Devouring Plague.",sp=0}},faq={{q="Who sends me on this quest?",a="Ur'kyo, the troll priest trainer found among the spirits in Orgrimmar, offers this quest to Forsaken priests who have reached their twentieth circle of power.",al={"quest giver","who starts devouring plague","ur'kyo location"}},{q="Where do I need to go?",a="You must travel across the Great Sea to the Undercity in Tirisfal Glades. Seek out Priestess Aelthalyste, who presides over Forsaken priest training in the War Quarter.",al={"where do i turn this in","aelthalyste location","undercity priest trainer"}},{q="Why does Ur'kyo send Forsaken back to Lordaeron?",a="Ur'kyo honors an understanding with Priestess Aelthalyste. While troll shadow priests understand loa and spirits, the Forsaken wield dark arts tied specifically to their undead nature, requiring instruction directly from their own leaders.",al={"why go back to undercity","why does troll priest send me away"}},{q="What is the significance of the Devouring Plague?",a="Devouring Plague is a potent affliction unique to Forsaken practitioners of the Shadow. It inflicts devastating disease upon targets while siphoning their life force directly back to the caster.",al={"what is devouring plague lore","forsaken priest plague"}},{q="Can other Horde races accept this quest?",a="No. This quest is exclusively offered to Forsaken priests, representing their communion with their homeland's unique shadow disciplines.",al={"can trolls do this","is this quest undead only"}},{q="How does this fit into Horde priest relations?",a="The Horde relies on a mutual exchange between Darkspear witch doctors and hex priests on Kalimdor and Forsaken shadow priests in the Eastern Kingdoms, each directing travelers to the masters best suited to their culture.",al={"trolls and undead priests","horde priest lore"}}},ang={["class:Priest"]="Forsaken priests draw upon unique racial doctrines of shadow and decay, learning to channel their physical torment into devastating curses like the Devouring Plague.",["race:Undead"]="Returning to the War Quarter in Undercity reminds Forsaken adventurers that their true allegiance and spiritual roots lie beneath the ruins of Lordaeron, regardless of how far Horde duties take them.",["faction:Horde"]="The shared training duties between Ur'kyo in Durotar and Aelthalyste in Tirisfal illustrate the practical cooperation and mutual respect tying the distant Horde capitals together."},kw={"aelthalyste","devouring plague","forsaken priest","orgrimmar","shadow priest","undercity","ur'kyo","war quarter"},rel={"npc:ur-kyo","npc:aelthalyste","zone:undercity","subzone:war-quarter"},m={start="Ur'kyo",["end"]="Aelthalyste",level="20",faction="Horde",id=5646},src={"Devouring Plague (Orgrimmar)"}}
E["quest:5654"] = {t="quest",n="Hex of Weakness",z="orgrimmar",s="Hex of Weakness is an early rite of passage quest given to young Darkspear troll priests who have proven their initial worth in Razor Hill. Sent north into Orgrimmar by Tai'jin, the initiate seeks out Ur'kyo to be welcomed deeper into the tribe's spiritual circle and instructed in the loa's darker arts.",h="Hex of Weakness is an early rite of passage quest given to young Darkspear troll priests who have proven...",sec={{t="A Summons to the Circle",b="For a fledgling troll priest in Durotar, lessons continue in the barracks of Razor Hill under the watchful eye of Tai'jin. Once an acolyte displays sufficient mastery over the basic balance of spiritual communion and shadow magic, basic tutelage ends. Tai'jin directs the promising priest away from Razor Hill and northward across the red dirt canyons toward the Horde capital, where elder practitioners oversee the tribe's broader magical traditions.",sp=0},{t="The Old Ways in the Valley of Spirits",b="Within Orgrimmar, the Darkspear maintain their own distinct cultural sanctuary in the Valley of Spirits, separated from the clanging forge-works and warrior grounds of the orcs. Here, amidst towering totems and shaded huts, the elder priest Ur'kyo awaits new initiates. To be brought into his circle means embracing the ancestral traditions of the jungle trolls—balancing reverence for ancestral loa with the potent curses and hexes that sap an adversary's strength in battle.",sp=0}},faq={{q="What is the purpose of this quest?",a="The quest represents an initiate's formal advancement within the Darkspear priesthood. Tai'jin sends developing troll priests from Durotar's coast to Ur'kyo in Orgrimmar, formally inducting them into the tribe's inner circle of spiritual practitioners.",al={"why do this quest","hex of weakness purpose","what does hex of weakness quest do"}},{q="Who is Tai'jin?",a="Tai'jin is a troll priest trainer stationed in the barracks of Razor Hill in Durotar. She guides the youngest Darkspear spellcasters through their early trials before sending them onward to the capital.",al={"who is quest giver","tai'jin lore","taijin"}},{q="Who is Ur'kyo?",a="Ur'kyo is an elder troll priest trainer residing in the Valley of Spirits within Orgrimmar. He oversees advanced spiritual training, passing down tribal hexes and deep ancestral rites to Darkspear priests.",al={"who is ur'kyo","urkyo priest trainer","ur-kyo"}},{q="Where is the Valley of Spirits?",a="The Valley of Spirits is a secluded, swampy district in western Orgrimmar. It serves as the primary home for the Darkspear trolls within the orcish fortress-city, housing their trainers, lodgings, and totems.",al={"valley of spirits location","where is ur'kyo","where to find ur'kyo"}},{q="What kind of magic does this training focus on?",a="Darkspear priests invoke the 'old ways,' drawing power from the loa and ancient jungle troll traditions. Rather than relying solely on the Holy Light favored by humans or dwarves, troll priests balance restorative spirit magic with debilitating curses like the Hex of Weakness.",al={"troll priest magic","what are the old ways","hex lore"}},{q="Can non-trolls undertake this quest?",a="No. This quest is specifically tied to the cultural traditions and unique spells of the Darkspear trolls. Undead priests are directed toward their own mentors and shadow philosophies in Tirisfal and the Undercity.",al={"can undead do this","is this troll only"}}},ang={["race:Troll"]="This rite marks your transition from a novice in Razor Hill to a recognized priest of the Darkspear tribe, learning ancient curses passed down through generations.",["class:Priest"]="Unlike the dogma of the Holy Light or the Forgotten Shadow, troll priesthood draws on deep communion with primal spirits, weaving tribal hexes alongside traditional shadow and restorative spells.",["faction:Horde"]="The journey from Razor Hill to the Valley of Spirits reflects the integration of troll culture into the fortified walls of Thrall's growing capital."},kw={"darkspear","durotar","hex of weakness","loa","orgrimmar","sen'jin village","tai'jin","ur'kyo","valley of spirits"},rel={"npc:ur-kyo","npc:tai-jin","subzone:valley-of-spirits","zone:orgrimmar"},m={start="Tai'jin",["end"]="Ur'kyo",level="10",faction="Horde",id=5654},src={"Hex of Weakness (Durotar)"}}
E["quest:5726"] = {t="quest",n="Hidden Enemies",z="orgrimmar",s="Hidden Enemies is the opening chapter of Warchief Thrall's investigation into cultist infiltration within Durotar. Aware that demonic sympathizers are operating right under the Horde's nose, Thrall tasks a promising young adventurer with recovering a Lieutenant's Insignia from Skull Rock to initiate a covert operation.",h="Hidden Enemies is the opening chapter of Warchief Thrall's investigation into cultist infiltration within...",sec={{t="The Rot Within Durotar",b="While the nascent Horde struggles to carve out a secure home in Durotar, Warchief Thrall faces an insidious threat far deadlier than centaur raids or quilboar incursions: internal betrayal. The demonic cult known as the Burning Blade has rooted itself right outside the gates of Orgrimmar, preying on lingering demonic corruption and thirst for dark power. Thrall recognizes that sending his official Kor'kron guards or known commanders would merely scatter the cultists into deeper hiding. He needs someone untainted by high-profile associations to serve as his discreet eyes and ears.",sp=0},{t="Infiltrating Skull Rock",b="East of Orgrimmar lies Skull Rock, a rugged cavern infested with warlocks, voidwalkers, and fanatical cultists. Thrall sends the adventurer straight into this nest with a specific mission: claim a Lieutenant's Insignia from one of the Burning Blade leaders. This emblem is far more than a battlefield trophy; it is a vital credential meant to grant the bearer access to the cult's shadowy hierarchy, enabling a deeper sting operation designed to reveal who directs the cult's movements from behind the scenes.",sp=0}},faq={{q="Who gives the quest Hidden Enemies?",a="The quest is offered by Warchief Thrall himself, situated inside the Valley of Wisdom within Orgrimmar, once you have reported to Orgnil Soulweaver.",al={"hidden enemies questgiver","who starts hidden enemies","where to start hidden enemies"}},{q="What is the goal of Hidden Enemies?",a="Thrall tasks you with journeying to Skull Rock, located east of Orgrimmar, to slay Burning Blade cultists and bring back a Lieutenant's Insignia.",al={"hidden enemies objective","what do i need for hidden enemies"}},{q="Why doesn't Thrall just send his elite guards to purge Skull Rock?",a="Thrall fears open military intervention would cause the true conspirators to slip away and bury the corruption deeper. An unknown adventurer can quietly acquire credentials and infiltrate the network without tipping off the high-ranking traitors pulling the strings.",al={"why thrall needs adventurers","why not send the army"}},{q="What is Skull Rock?",a="Skull Rock is a secluded cavern system located along the eastern coast of Durotar, northeast of Orgrimmar. It serves as a covert stronghold and summoning den for the Burning Blade cult.",al={"where is skull rock","what is skull rock cave"}},{q="What is the Lieutenant's Insignia used for?",a="The insignia serves as proof of rank among the cultists. Thrall plans to use it to disguise and establish an operative inside the Burning Blade's ranks to discover who orchestrates their operations.",al={"what is the insignia for","lieutenants insignia purpose"}},{q="What other quests can be completed alongside this one?",a="Adventurers entering Skull Rock often complete the quest Skull Rock to collect cultist collars, and can loot the Eye of Burning Shadow from the cult leader Gazz'uz to begin the quest Burning Shadows.",al={"skull rock quests","quests in skull rock"}}},ang={["faction:Horde"]="This mission marks a critical moment where an adventurer is personally entrusted by Warchief Thrall to safeguard the heart of the new Horde from demonic subversion.",["race:Orc"]="For orcs striving to overcome the blood-haze and shame of the demon curse, hunting down the Burning Blade is a personal battle to keep the demonic blight from poisoning their people a second time.",["class:Warlock"]="Horde warlocks must tread carefully: while practicing fel arts under Thrall's strict oversight, they are summoned to root out cultists whose unbridled demonic servitude threatens the survival of Orgrimmar."},kw={"burning blade","durotar","hidden enemies","lieutenant's insignia","orgrimmar","skull rock","thrall"},rel={"npc:thrall","topic:burning-blade-clan","quest:827","quest:832","quest:823","zone:orgrimmar","topic:horde"},m={start="Thrall",level="12",faction="Horde",id=5726},src={"Hidden Enemies"}}
E["quest:5727"] = {t="quest",n="Hidden Enemies",z="orgrimmar",s="Following the discovery of cult activity in Skull Rock, Warchief Thrall directs you to infiltrate the Burning Blade within Orgrimmar itself. By presenting a cult lieutenant's insignia to the warlock Neeru Fireblade, you test his loyalties and pierce the veil of the Shadow Council operating right under the city's surface.",h="Following the discovery of cult activity in Skull Rock, Warchief Thrall directs you to infiltrate the Burning...",sec={{t="The Warchief's Gambit",b="Rather than strike directly at the sinister elements harboring in the Cleft of Shadow, Thrall chooses cunning over haste. He is well aware that Neeru Fireblade feigns loyalty while quietly serving the cultists. Striking Neeru immediately would merely alert his masters and sever any trail leading deeper into the conspiracy. Instead, Thrall provides the insignia taken from the cult in Durotar, bidding you to masquerade as an initiate to discover what Neeru knows.",sp=0},{t="The Cleft's Hidden Master",b="Down in the murky caverns of the Cleft of Shadow, outside the entrance to Ragefire Chasm, Neeru Fireblade quickly takes the bait. Believing you to be a newly promoted lieutenant of his order, the warlock openly scoffs at Thrall's ignorance. He reveals that the Burning Blade and offshoots like the Searing Blade are merely front organizations answering directly to the Shadow Council, who serve the will of the Burning Legion. He boasts of manipulating the Warchief into throwing loyal soldiers against the cultists in the chasm, using Thrall's own armies to weed out the weak.",sp=1}},faq={{q="Why does Thrall keep Neeru alive if he knows he is a traitor?",a="Thrall allows Neeru to live because an exposed traitor is more valuable than a dead one. If executed immediately, the Shadow Council would simply replace him with someone harder to detect. By keeping Neeru under watchful eyes, Thrall turns the warlock into an unwitting conduit for intelligence regarding cult movements in Orgrimmar.",al={"why thrall trust neeru","why keep neeru alive","neeru traitor"},sp=1},{q="Who is Neeru Fireblade?",a="Neeru Fireblade is an orc warlock residing in the Cleft of Shadow. Outwardly, he pretends to help Thrall reform warlocks into dutiful servants of the Horde. In secret, he is the leader of the Burning Blade cult, orchestrating treachery beneath the city in the name of the Shadow Council.",al={"neeru backstory","who is neeru"},sp=1},{q="What is the relationship between the Burning Blade and the Shadow Council?",a="As Neeru reveals, the Burning Blade is not an independent sect; it is an arm of the Shadow Council itself. The Council maintains several subsidiary cults—including the Searing Blade inside Ragefire Chasm—to divide, mislead, and control ambitious practitioners under the ultimate dominion of the Burning Legion.",al={"burning blade shadow council connection","are burning blade shadow council"},sp=1},{q="Who leads the cultists inside Ragefire Chasm?",a="The Searing Blade cult operating in the chasm below Orgrimmar is spearheaded by a satyr named Bazzalan alongside an orc warlock named Jergosh the Invoker. Neeru uses Thrall's adventurers to battle them, using the conflict both to thin Horde loyalists and to test his subordinates.",al={"ragefire chasm leaders","searing blade leaders"}},{q="How did I obtain the Lieutenant's Insignia?",a="The insignia was recovered during Thrall's initial investigation into cult activity within Durotar, specifically from the Burning Blade cultists operating out of Skull Rock.",al={"where lieutenant insignia comes from","insignia source"}}},ang={["faction:Horde"]="The revelation that demonic cults openly operate beneath the foundational rock of Orgrimmar threatens the very survival of the young Horde nation.",["class:Warlock"]="Neeru claims to advocate for warlocks seeking legitimate standing in the Horde, but his treachery risks bringing severe condemnation upon all who practice the fel arts under Thrall's rule.",["race:Orc"]="For orcs striving to shake off the legacy of bloodlust and demonic corruption, the Shadow Council's resurgence beneath their capital is a chilling echo of their dark past on Draenor."},kw={"burning blade","cleft of shadow","insignia","neeru fireblade","orgrimmar","ragefire chasm","shadow council","thrall"},rel={"quest:5726","quest:829","quest:5761","npc:thrall","npc:bazzalan","subzone:cleft-of-shadow","zone:ragefire","topic:shadow-council"},m={start="Thrall",level="12",faction="Horde",id=5727},src={"Hidden Enemies (2)"}}
E["quest:5729"] = {t="quest",n="Hidden Enemies",z="orgrimmar",s="Hidden Enemies is a pivotal step in Warchief Thrall's investigation into cultist infiltration within Orgrimmar. Having executed the ringleaders of the Burning Blade beneath the city, the player is sent to embed themselves further as a confidant to Neeru Fireblade.",h="Hidden Enemies is a pivotal step in Warchief Thrall's investigation into cultist infiltration within...",sec={{t="Thrall's Gambit",b="Following the assassination of Bazzalan and Jergosh the Invoker in Ragefire Chasm, Thrall recognizes an opening. Rather than exposing Neeru Fireblade directly, the Warchief chooses to play the long game. Neeru is distressed by the sudden loss of his underground lieutenants, creating a void of leadership within the local cult. Thrall dispatches you back to the shadowy recesses of the Cleft of Shadow to present yourself as a dependable ally who can fill that vacuum.",sp=0},{t="The Warlock's Deception",b="When approached in the Cleft of Shadow, Neeru Fireblade is visibly furious over the sudden defeat of his conspirators. Unaware that the very adventurer standing before him carried out the executions on Thrall's orders, Neeru curses the 'do-gooders' who brought ruin to Ragefire Chasm. Caught off guard by the swift strike, Neeru begins to lower his guard around the player, paving the way for Thrall to monitor the Shadow Council's influence directly from within Orgrimmar.",sp=1}},faq={{q="Why doesn't Thrall just execute Neeru Fireblade immediately?",a="Thrall prefers keeping an exposed enemy where he can watch them. By leaving Neeru in place while thinking his cover is intact, Thrall can monitor the Burning Blade's communications and trace their ties back to the Shadow Council, using the player as an inside operative.",al={"why spare neeru","why does thrall let neeru live","neeru alive"}},{q="Who were Bazzalan and Jergosh?",a="Bazzalan was a satyr and Jergosh the Invoker was an orc warlock. Operating deep within Ragefire Chasm beneath Orgrimmar, they served as field leaders and conspirators for the Burning Blade cult before Thrall ordered their deaths.",al={"bazzalan","jergosh","who died in ragefire"}},{q="Does Neeru realize you killed his lieutenants?",a="No. Neeru vents his fury believing unknown agents of Thrall surprised and slaughtered them, entirely unaware that the adventurer offering him condolences and aid is the assassin responsible.",al={"does neeru know","neeru knows who killed them"}},{q="Where is Neeru Fireblade located?",a="Neeru Fireblade resides in the Cleft of Shadow, a subterranean cavern tucked beneath the heart of Orgrimmar where warlocks, rogues, and shadow casters gather away from the rest of the city.",al={"neeru location","find neeru","where is neeru fireblade"}},{q="What is the Burning Blade?",a="Originally a fierce clan from Draenor, the Burning Blade degenerated into a demonic cult manipulated by the Shadow Council. In Kalimdor, its remnants seek to undermine Thrall's new Horde and restore demonic servitude.",al={"burning blade","burning blade cult"}},{q="What happens after speaking to Neeru?",a="After securing Neeru's confidence and hearing his dismay over the losses in Ragefire Chasm, you return to Thrall in Grommash Hold to report your success and conclude the infiltration chain.",al={"what next","quest continuation"},sp=1}},ang={["class:Warlock"]="Neeru Fireblade stands openly among the warlock trainers in the Cleft of Shadow, demonstrating how close Thrall's new Horde walks alongside darker magics without succumbing to outright corruption.",["class:Rogue"]="This task is a textbook infiltration mission: eliminating an asset's network and immediately stepping in to become their most trusted confidant.",["faction:Horde"]="The mission underscores Thrall's pragmatic diplomacy and statecraft, using counter-espionage to secure Orgrimmar from within rather than relying solely on brute force.",["race:Orc"]="For orcs striving to shake off the demonic legacy of the old Horde, rooting out the Burning Blade from Orgrimmar's bedrock is essential to protecting their honor."},kw={"bazzalan","burning blade","cleft of shadow","hidden enemies","jergosh","neeru fireblade","orgrimmar","ragefire chasm","shadow council","thrall"},rel={"quest:5726","npc:thrall","quest:829","zone:ragefire","npc:bazzalan","subzone:cleft","zone:orgrimmar","topic:horde"},m={start="Thrall",["end"]="Neeru Fireblade",level="15",faction="Horde",id=5729},src={"Hidden Enemies (4)"}}
E["quest:5730"] = {t="quest",n="Hidden Enemies",z="orgrimmar",s="Hidden Enemies is the culmination of Warchief Thrall's operation to infiltrate and assess the Burning Blade coven lurking inside Orgrimmar. By returning to Thrall after securing the trust of Neeru Fireblade, you provide critical intelligence on the cult's widening reach across Kalimdor.",h="Hidden Enemies is the culmination of Warchief Thrall's operation to infiltrate and assess the Burning Blade...",sec={{t="A Cult Unveiled",b="Following the disruption of the Searing Blade deep within Ragefire Chasm, Warchief Thrall sent agents to discover who commanded the sect from within the city walls. The trail pointed directly to Neeru Fireblade, a warlock dwelling openly in the Cleft of Shadows. By playing the role of a willing recruit and bearing the insignias of fallen cultists, the operative earns Fireblade's trust, leading the warlock to inadvertently reveal the broader network backing his operations.",sp=1},{t="Whispers of the Shadow Council",b="Thinking he has gained a loyal lieutenant, Neeru Fireblade admits that the loss in Ragefire Chasm is a setback for the Searing Blade, but declares that the Shadow Council's greater designs remain intact. He reveals that his masters have active agents operating not only in the Barrens, but deeper in the forests of Ashenvale. Reporting this news to Thrall catches the Warchief off-guard, revealing that the demonic conspiracy extends far beyond the subterranean tunnels of the capital.",sp=2},{t="The Warchief's Vigilance",b="Rather than executing Neeru immediately, Thrall chooses a cautious path. Keeping Neeru unaware of his compromise allows the Horde to monitor his communications and track the cult's tentacles across Durotar, the Barrens, and Ashenvale. The Warchief prepares his scouts and spies to investigate these regional branches, recognizing that rooting out demonic corruption requires precision rather than reckless haste.",sp=1}},faq={{q="What is the goal of this quest?",a="You must travel from the Cleft of Shadows to the Valley of Wisdom in Orgrimmar and speak with Warchief Thrall, reporting what Neeru Fireblade disclosed about the Shadow Council's plans.",al={"hidden enemies goal","what to do hidden enemies 5","thrall turn in"}},{q="Why does Neeru Fireblade trust me?",a="Throughout the Hidden Enemies chain, you recovered a Lieutenant's Insignia from the Burning Blade at Skull Rock and presented it to Neeru under the guise of an ambitious cult initiate, convincing him you were a loyal asset.",al={"why neeru trusts me","tricking neeru","fireblade infiltration"},sp=1},{q="Why doesn't Thrall arrest or execute Neeru Fireblade right away?",a="Neeru is far more useful alive and oblivious. By allowing him to think his cover is intact, Thrall's scouts can monitor Neeru's messages and trace his contacts back to larger Shadow Council cells across Kalimdor.",al={"why is neeru alive","why not kill neeru","why thrall leaves neeru"},sp=1},{q="What new information does Thrall learn from this report?",a="Thrall learns that the cult beneath Orgrimmar is backed by the Shadow Council and that their agents are actively plotting operations in both the Barrens and the forests of Ashenvale.",al={"what did thrall learn","shadow council ashenvale","neeru secret"},sp=1},{q="Is the Burning Blade the same thing as the Searing Blade?",a="The Searing Blade is a local sect operating inside Ragefire Chasm beneath Orgrimmar, serving as an arm of the wider Burning Blade cult, which is orchestrated by the demonic Shadow Council.",al={"burning blade vs searing blade","ragefire chasm cults","cult differences"}},{q="Does this quest chain continue anywhere?",a="Thrall tells you to rest and promises to call upon you later, but there is no direct quest immediately continuing this specific undercover infiltration line.",al={"hidden enemies followup","next quest after hidden enemies","where does thrall send you next"}}},ang={["faction:Horde"]="Uncovering treason within Orgrimmar's own borders proves that the nascent Horde must guard against ancient demonic corruption from within while battling outside enemies.",["class:Warlock"]="Neeru Fireblade represents the dangerous fringe of fel practice, showing how easily dark arts can slip from state-sanctioned utility into outright subservience to the Shadow Council.",["class:Rogue"]="This mission represents the Horde's early espionage tradecraft, prioritizing deep cover, counter-intelligence, and patience over immediate confrontation."},kw={"ashenvale","barrens","burning blade","cleft of shadows","hidden enemies","neeru fireblade","ragefire chasm","searing blade","shadow council","thrall"},rel={"npc:thrall","quest:829","quest:5726","zone:ragefire","topic:shadow-council","zone:orgrimmar","zone:barrens","zone:ashenvale"},m={start="Neeru Fireblade",["end"]="Thrall",level="16",faction="Horde",id=5730},src={"Hidden Enemies (5)"}}
E["quest:6384"] = {t="quest",n="Ride to Orgrimmar",z="orgrimmar",s="This errand introduces Horde adventurers to aerial travel across Kalimdor by commissioning a wind rider from the Crossroads to Orgrimmar. Entrusted with Zargh's fresh cuts of meat, travelers land at the capital's Skytower to deliver the package directly to Innkeeper Gryshka.",h="This errand introduces Horde adventurers to aerial travel across Kalimdor by commissioning a wind rider from...",sec={{t="Wings Over the Savanna",b="Crossing the arid expanse between the Crossroads and the red cliffs of Durotar on foot is grueling, but the Horde maintains a reliable network of trained wind riders to bridge the distance. Devrak, the Crossroads flight master, oversees these wyverns, dispatching messengers and travelers high above the dusty canyon trails to deliver vital dispatches and trade goods directly into the capital.",sp=0},{t="Special Delivery for Gryshka",b="The flight is not merely a sight-seeing trip; it carries a personal touch. Zargh of the Crossroads prepared a parcel of prime raw cuts destined for Innkeeper Gryshka in Orgrimmar's Valley of Strength. Once the wind rider touches down upon Orgrimmar's central Skytower, Gryshka's inn is only a brief walk away, where she eagerly accepts the gift—noting with fondness that Zargh certainly knows his way into a lady's heart.",sp=0}},faq={{q="What is the purpose of this flight?",a="The journey serves as a practical introduction to the Horde's wind rider travel network. You are paying Devrak for passage from the Crossroads to Orgrimmar to deliver Zargh's fresh cuts of meat to Innkeeper Gryshka.",al={"why fly to orgrimmar","flight to orgrimmar purpose","why meat to orgrimmar"}},{q="Where does the wind rider land in Orgrimmar?",a="The wind rider lands at the Orgrimmar Skytower, perched high above the Valley of Strength. From the tower platform, you can descend ramps to reach the main square, nearby vendors, and Gryshka's inn.",al={"where do i land in org","skytower location","orgrimmar flight landing"}},{q="Who is Gryshka?",a="Innkeeper Gryshka manages the busy tavern located in Orgrimmar's Valley of Strength. She welcomes tired travelers into the capital and maintains a fond friendship with Zargh, who regularly supplies her with choice raw cuts for her kitchen.",al={"innkeeper gryshka","who is gryshka","gryshka location"}},{q="Who is Devrak?",a="Devrak is the wind rider master stationed at the Crossroads in the Barrens. He tends the wyverns and coordinates air transport connecting the Barrens outpost to Durotar and other Horde settlements.",al={"devrak crossroads","who is devrak","crossroads wind rider master"}},{q="Why is Zargh sending raw meat to Gryshka?",a="Zargh considers fresh game from the Barrens a prized offering. Gryshka appreciates the gift immensely, noting that prime rare cuts are a surefire way into her heart.",al={"zargh meats","why send meat to gryshka","zargh and gryshka"}},{q="What should I do after delivering the meat?",a="After completing the delivery at the inn, Gryshka directs travelers back toward the Skytower to speak with Doras, Orgrimmar's wind rider master, in preparation for the return trip.",al={"what next after ride to orgrimmar","next quest after gryshka","where to go after delivery"}}},ang={["faction:Horde"]="The wind rider flight between the Crossroads and Orgrimmar is the foundational lifeline connecting the central Barrens to the seat of Warchief Thrall's power.",["profession:Cooking"]="Gryshka makes her culinary preferences unmistakable upon receiving Zargh's gift: the finest beasts of Kalimdor should be served rare to preserve their flavor."},kw={"barrens","crossroads","devrak","doras","gryshka","orgrimmar","skytower","wind rider","zargh"},rel={"quest:6365","quest:6385","quest:6386","npc:devrak","npc:innkeeper-gryshka","npc:zargh","npc:doras","zone:orgrimmar"},m={start="Devrak",["end"]="Innkeeper Gryshka",level="10",faction="Horde",id=6384},src={"Ride to Orgrimmar (Classic)"}}
E["quest:6385"] = {t="quest",n="Doras the Wind Rider Master",z="orgrimmar",s="Innkeeper Gryshka of Orgrimmar has written a letter of gratitude to Zargh at the Crossroads and needs a courier to fly it back to the Barrens. To arrange passage, she directs travelers up to the city's skytower to consult Doras, the Horde's chief wind rider master.",h="Innkeeper Gryshka of Orgrimmar has written a letter of gratitude to Zargh at the Crossroads and needs a...",sec={{t="A Courier's Reply",b="After receiving a fresh shipment of bulk meat flown in from the hunting grounds of the Barrens, Innkeeper Gryshka drafts a formal letter of thanks to the butcher Zargh. Lacking the time to make the overland journey through Durotar herself, she relies on the aerial courier network established between Kalimdor's major Horde settlements to speed her message back across the frontier.",sp=0},{t="The Master of the Roost",b="Doras oversees Orgrimmar's wind rider roost atop the towering mesa overlooking the Valley of Strength. His trained wyverns are the lifeblood of Horde military communication and logistics, bridging the perilous gap between the capital and outlying outposts like the Crossroads in a fraction of the time required by foot or kodo cart.",sp=0}},faq={{q="Who is Doras?",a="Doras is the primary wind rider master stationed in Orgrimmar. He manages the city's stable of trained wyverns and coordinates aerial travel to distant Horde hubs throughout central Kalimdor.",al={"doras","who is doras","orgrimmar flight master"}},{q="Why is Innkeeper Gryshka sending this letter?",a="Gryshka is sending a written note of thanks to Zargh, the butcher at the Crossroads, acknowledging the safe arrival of meat supplies delivered to her tavern in Orgrimmar.",al={"why send letter","gryshka letter","what is the letter for"}},{q="Where can Doras be found?",a="Doras is stationed atop the central flight tower above the Valley of Strength in Orgrimmar, reachable via the wooden lifts and walkways climbing the surrounding mesas.",al={"where is doras","doras location","find doras"}},{q="What happens after giving Gryshka's letter to Doras?",a="Once you consult Doras, he prepares a wind rider to carry you back to the Barrens so you can hand-deliver Gryshka's letter directly to Zargh at the Crossroads.",al={"what next","after doras","next quest"}},{q="Who is Zargh?",a="Zargh is an orc butcher based at the Crossroads in the Barrens and a friend of Gryshka, who sent her a gift of choice cuts of Barrens meat.",al={"zargh","who is zargh"}},{q="Why use wind riders instead of walking?",a="The overland journey from Orgrimmar through Durotar and across the Southfury River into the Barrens is slow and fraught with perils. Tamed wind riders provide the Horde with a swift, reliable means to send scouts, orders, and couriers between settlements.",al={"why fly","wind rider purpose","flight path lore"}}},ang={["faction:Horde"]="The wind rider network connects Orgrimmar to key regional garrisons, serving as the connective sinew that lets the young Horde project force and move supplies across Kalimdor's wilderness.",["race:Orc"]="Orcs have forged a strong bond with the native wyverns of Kalimdor since arriving on the continent, relying on their agility and strength as flying mounts and beast-of-burden couriers."},kw={"barrens","crossroads","doras","flight master","gryshka","orgrimmar","wind rider","wyvern","zargh"},rel={"npc:doras","npc:innkeeper-gryshka","quest:6384","quest:6386","quest:6365","npc:zargh","subzone:crossroads","zone:orgrimmar"},m={start="Innkeeper Gryshka",["end"]="Doras",level="10",faction="Horde",id=6385},src={"Doras the Wind Rider Master (Classic)"}}
E["quest:6386"] = {t="quest",n="Return to the Crossroads.",z="orgrimmar",s="This errand concludes a courier delivery between Durotar and the Barrens, carrying Gryshka's reply back to Zargh at the Crossroads. It demonstrates how wind riders serve as the vital aerial backbone linking the Horde's settlements across Kalimdor.",h="This errand concludes a courier delivery between Durotar and the Barrens, carrying Gryshka's reply back to...",sec={{t="A Winged Return",b="Having delivered a parcel of prime meat to Gryshka in Orgrimmar, you are entrusted with her written reply for Zargh. Doras, the wind rider master roosted atop Orgrimmar's high bluffs, provides a mount back to the Barrens. Because you have already established contact with Devrak at the Crossroads, Doras's wyverns know the flight path, turning an arduous overland march across the Southfury River into a swift ride through the desert sky.",sp=0},{t="A Match Made in the Barrens",b="Zargh's bold culinary courtship succeeds. Gryshka's warm response confirms that nothing impresses an orc quite like quality provisions, prompting Zargh to celebrate and even muse over an impending wedding. Beyond the romantic triumph, the journey solidifies a traveler's access to the Barrens' central transit hub.",sp=0}},faq={{q="Why do I have to use a wind rider to return?",a="Doras uses this delivery to demonstrate the Horde's flight network. Since you previously visited Devrak at the Crossroads, the wyverns can fly directly between the two roosts, saving time and keeping supply lines secure.",al={"why fly back","wind rider required","can i walk"}},{q="Who is Gryshka?",a="Gryshka is the innkeeper in the Valley of Strength in Orgrimmar. Zargh sent her a selection of choice Barrens meat in hopes of winning her favor.",al={"gryshka lore","who is gryshka","orgrimmar meat lady"}},{q="What was Zargh's goal in sending meat to Orgrimmar?",a="Zargh wanted to court Gryshka. In orcish culture, gifting hearty, quality game from the wild plains of the Barrens is considered a grand romantic gesture.",al={"why did zargh send meat","zargh motivation","zargh letter"}},{q="Where does this quest end?",a="The quest completes at the Crossroads in the Barrens, where you hand Gryshka's Letter back to Zargh near the watchtower and stables.",al={"where to turn in","return location","who gets gryshka letter"}},{q="Who is Doras?",a="Doras is the wind rider master stationed at the flight roost above the Valley of Strength in Orgrimmar, managing the aerial mounts that travel across Kalimdor.",al={"doras wind rider","doras location","orgrimmar flight master"}},{q="What happens after this quest?",a="This delivery marks the end of the Meats to Orgrimmar courier chain. Having connected Orgrimmar and the Crossroads, you are fully set up to explore deeper into the Barrens.",al={"chain follow up","next quest after return","meats to orgrimmar continuation"}}},ang={["faction:Horde"]="The wind rider roosts of Orgrimmar and the Crossroads form the economic and logistical spine connecting the Horde capital to the perilous plains of Kalimdor.",["race:Orc"]="Hearty cuts of fresh game remain one of the finest tokens of affection and respect an orc hunter can offer a prospective mate."},kw={"barrens","crossroads","devrak","doras","gryshka","letter","orgrimmar","wind rider","wyvern","zargh"},rel={"quest:6385","quest:6384","quest:6365","npc:zargh","npc:doras","npc:devrak","subzone:crossroads","zone:orgrimmar"},m={start="Doras",["end"]="Zargh",level="10",faction="Horde",id=6386},src={"Return to the Crossroads."}}
E["quest:6608"] = {t="quest",n="You Too Good.",z="orgrimmar",s="\"You Too Good.\" is a Horde quest offered by the Orgrimmar fishing trainer, Lumak, once an angler has surpassed ordinary training. Lumak sends his accomplished pupil to track down his human friend, Nat Pagle, camped along the remote shores of Dustwallow Marsh. It marks the transition from standard instruction to the demanding art of artisan fishing.",h="\"You Too Good.\" is a Horde quest offered by the Orgrimmar fishing trainer, Lumak, once an angler has...",sec={{t="Lumak's Limits",b="Lumak serves as Orgrimmar's primary fishing trainer down in the Valley of Honor, but even the patient orc recognizes when a student has matched his own understanding of the rod and reel. Rather than pretending to have further wisdom to bestow, Lumak candidly confesses that the angler has become 'too good' for ordinary lessons. To reach the rank of artisan, one must look beyond city walls and racial boundaries.",sp=0},{t="An Unlikely Friendship",b="Despite the simmering friction between the Horde and the Alliance across Kalimdor, fishing often bridges divides where diplomacy fails. Lumak points travelers toward his personal acquaintance, Nat Pagle, insisting emphatically that the human is not to be harmed or eaten. Nat makes his camp on an islet south of Theramore Isle in Dustwallow Marsh, content to ignore politics as long as the fish are biting.",sp=0}},faq={{q="Who sends me on this quest?",a="Lumak, the fishing trainer located by the water in Orgrimmar's Valley of Honor, gives you this quest once your fishing skill is high enough to advance beyond expert.",al={"who starts you too good","lumak quest giver","where to get you too good"}},{q="Where is Nat Pagle located?",a="Nat Pagle is stationed on an islet off the coast of Dustwallow Marsh, south of the human settlement of Theramore Isle.",al={"where is nat pagle","nat pagle location","find nat pagle"}},{q="Why does an orc have a human friend?",a="Anglers throughout Azeroth often share a mutual respect that transcends the faction war. Lumak and Nat Pagle bonded purely over fishing, recognizing each other's passion regardless of the bitter rivalry between orcs and humans.",al={"lumak and nat pagle friendship","why is nat pagle friends with an orc"}},{q="What happens when I speak to Nat Pagle?",a="Speaking with Nat Pagle introduces you to his demanding artisan trial, requiring you to travel across Azeroth catching rare fish before he will personally instruct you further.",al={"what does nat pagle teach","artisan fishing quest"}},{q="Is Theramore safe for Horde to pass through?",a="No, Theramore is a strictly Alliance-guarded fortress town. Horde adventurers must detour around the town or skirt the coast to reach Nat's island without drawing the wrath of the Theramore guards.",al={"can horde go through theramore","getting to nat pagle as horde"}},{q="Why can't Lumak train me further himself?",a="Lumak has taught you all he knows. True mastery of artisan fishing requires insight from Nat Pagle, widely regarded as the most legendary angler in the known world.",al={"why lumak stops training","expert to artisan fishing horde"}}},ang={["faction:Horde"]="This quest demonstrates that beneath the faction war, individuals occasionally form cross-faction bonds over harmless craft and common pastimes.",["race:Orc"]="Even within the martial stronghold of Orgrimmar, Lumak proves that patience, good humor, and deep respect for nature can lead an orc to make friends across enemy lines."},kw={"artisan fishing","dustwallow marsh","lumak","nat pagle","orgrimmar","theramore","you too good"},rel={"npc:nat-pagle","zone:dustwallow"},m={start="Lumak",["end"]="Nat Pagle",faction="Horde",id=6608},src={"You Too Good."}}
E["quest:6611"] = {t="quest",n="To Gadgetzan You Go!",z="orgrimmar",s="To Gadgetzan You Go! is a journey undertaken by Horde cooks seeking to advance beyond the limits of their capital city instructors. Directed by Zamja in Orgrimmar, aspiring chefs travel south across Kalimdor to Tanaris to seek out the eccentric goblin butcher Dirge Quikcleave. This breadcrumb marks the transition into true mastery over the culinary arts.",h="To Gadgetzan You Go!",sec={{t="A Cook Outgrows Orgrimmar",b="In the Valley of Strength, the troll cook Zamja feeds countless warriors and travelers passing through the red canyons of Durotar. Yet when a dedicated cook absorbs every recipe and technique Zamja has to offer, the master admits defeat. Having imparted all her culinary mojo, she sends her seasoned pupil south to the sands of Tanaris, admitting that only a true master of strange and exotic meats can push a talented cook any further.",sp=0},{t="The Butcher in the Desert",b="The destination is Gadgetzan, the steam-powered trading hub run by the Steamwheedle Cartel. There, inside the noisy town tavern, operates Dirge Quikcleave. A goblin with an unconventional palate and zero culinary squeamishness, Dirge is legendary across Kalimdor for preparing monstrous desert fauna—and occasional leather scraps—into hearty meals capable of sustaining hardened adventurers.",sp=0}},faq={{q="Who sends you to Gadgetzan?",a="Zamja, the troll expert cooking trainer situated near the fires of the Valley of Strength in Orgrimmar, gives this task to cooks who have mastered everything she knows.",al={"quest giver","who starts this","zamja quest"}},{q="Why does Zamja send you away?",a="Zamja has exhausted all the recipes and culinary techniques she can teach. To achieve artisan-level cooking mastery, she directs promising cooks to Dirge Quikcleave in Tanaris, an eccentric expert renowned for making edible meals out of the harshest desert ingredients.",al={"why gadgetzan","why dirge quikcleave","cooking master"}},{q="Who is Dirge Quikcleave?",a="Dirge Quikcleave is a goblin butcher and artisan cooking trainer located in the inn at Gadgetzan. He is famous for his rough temperament, odd nutritional theories—such as finding protein in old leather boots—and his mastery of high-end, exotic wilderness cooking.",al={"who is dirge","dirge gadgetzan"}},{q="Is this quest required to learn Artisan Cooking?",a="No. The quest is simply a breadcrumb guide directing Horde players toward Tanaris. A cook with sufficient skill can travel directly to Gadgetzan and speak with Dirge Quikcleave without having received Zamja's referral first.",al={"do i need this quest","breadcrumb cooking","is it mandatory"}},{q="Where is Gadgetzan located?",a="Gadgetzan is the walled desert outpost operated by the Steamwheedle Cartel in the northern sands of Tanaris, located far south on the continent of Kalimdor below Thousand Needles.",al={"gadgetzan location","where is dirge"}},{q="Does Zamja actually learn anything when you return?",a="Though Zamja cheekily demands that you return and teach her once you become the big cook on the block, she remains an expert trainer in Orgrimmar, tending her cookfires for the next generation of travelers.",al={"does zamja learn cooking","teach zamja"}}},ang={["profession:Cooking"]="This quest marks the milestone where a cook outgrows capital city instruction and must venture into the dangerous wilds to study under an artisan master.",["faction:Horde"]="Orgrimmar relies on outside specialists like neutral goblin chefs to push its crafters beyond standard tribal staples."},kw={"artisan cooking","cooking","dirge quikcleave","gadgetzan","orgrimmar","tanaris","valley of strength","zamja"},rel={"npc:zamja","npc:dirge-quikcleave","subzone:gadgetzan","zone:tanaris","topic:goblin"},m={start="Zamja",["end"]="Dirge Quikcleave",faction="Horde",id=6611},src={"To Gadgetzan You Go!"}}
E["quest:6623"] = {t="quest",n="Horde Trauma",z="orgrimmar",s="Horde Trauma is a summons directing accomplished Horde medics to report to Hammerfall in the Arathi Highlands. Doctor Gregory Victor, the chief physician of the Horde's trauma division, is looking to recruit and evaluate skilled hands capable of saving lives under extreme pressure. Answering the call places a medic directly into the grim, high-stakes reality of front-line field surgery.",h="Horde Trauma is a summons directing accomplished Horde medics to report to Hammerfall in the Arathi Highlands.",sec={{t="A Summons from Hammerfall",b="In Orgrimmar's Valley of Spirits, the orc first aid trainer Arnok delivers word to proficient healers that they have caught the attention of Doctor Gregory Victor himself. Victor oversees Horde Trauma from the fortified outpost of Hammerfall, tucked away in the contested hills of the Arathi Highlands. Arnok views the summons not merely as an order, but as the pinnacle of professional advancement for any battlefield surgeon.",sp=0},{t="The Brutal Work of Battlefield Triage",b="Reaching Hammerfall reveals that the post is far from comfortable. Operating amidst constant skirmishes with the League of Arathor and local hostile factions, Victor is inundated with wounded grunts, raiders, and scouts. The chief physician wastes no time welcoming newcomers with pleasantries; instead, recruits are immediately ordered into their scrubs to prove their worth during brutal, fast-paced emergency triage.",sp=0}},faq={{q="What is Horde Trauma?",a="Horde Trauma represents the dedicated medical and surgical branch serving the front lines of the Horde. Led by Doctor Gregory Victor out of Hammerfall, its members specialize in battlefield medicine, emergency triage, and treating severe combat injuries under chaotic conditions.",al={"horde trauma faction","what is horde trauma","who are horde trauma"}},{q="Who sends me on this assignment?",a="Arnok, the orc first aid trainer in Orgrimmar's Valley of Spirits, issues the summons. He considers serving under Doctor Gregory Victor to be the highest honor an aspiring field medic could hope to achieve.",al={"quest giver horde trauma","who starts horde trauma","krenk choplimb"}},{q="Where is Doctor Gregory Victor located?",a="Doctor Gregory Victor is stationed in the medical infirmary at Hammerfall, the primary Horde stronghold located in the northeastern Arathi Highlands.",al={"doctor gregory victor location","where is victor","hammerfall doctor"}},{q="What happens after reporting to Hammerfall?",a="Upon arriving, Doctor Victor immediately instructs you to don your scrubs for the follow-up assignment, Triage. You are placed in a high-stress test where you must prioritize and treat rapidly deteriorating wounded soldiers before they succumb to their injuries.",al={"what comes after horde trauma","next quest after horde trauma","triage quest"}},{q="Why is Hammerfall so desperate for field medics?",a="Hammerfall is surrounded by hostilities in Arathi, facing relentless conflict with human forces, syndicate operatives, and local beasts. Casualties stream into the encampment constantly, pushing the base's small medical staff to its limits.",al={"why hammerfall need medics","hammerfall medical situation"}},{q="Can Alliance players take this assignment?",a="No. Horde Trauma is exclusively for members of the Horde. The Alliance operates an equivalent medical evaluation led by Doctor Gustaf VanHowzen in the stronghold of Theramore Isle.",al={"can alliance do horde trauma","alliance version of horde trauma"}}},ang={["faction:Horde"]="The Horde's military strength depends heavily on rugged battlefield surgeons who keep grunts patched up and swinging in brutal frontier conflicts like the Arathi basin.",["class:Priest"]="While divine magic seals wounds instantly, secular triage teaches essential discipline in identifying who can be saved when mana runs bone dry."},kw={"arathi highlands","doctor gregory victor","first aid","hammerfall","horde trauma","krenk choplimb","triage"},rel={"npc:doctor-gregory-victor","subzone:hammerfall","zone:arathi","topic:horde"},m={start="Arnok",["end"]="Doctor Gregory Victor",faction="Horde",id=6623},src={"Horde Trauma (quest)"}}
E["quest:6962"] = {t="quest",n="Treats for Great-father Winter",z="orgrimmar",s="Treats for Great-father Winter is a festive holiday request offered during the Feast of Winter Veil in Orgrimmar. The jolly figurehead seated at the Smokywood Pastures display finds himself exhausted after hearing holiday wishes and asks a helpful adventurer for fresh gingerbread cookies and milk.",h="Treats for Great-father Winter is a festive holiday request offered during the Feast of Winter Veil in...",sec={{t="A Weary Patron of Winter",b="While Greatfather Winter embodies the mythical spirit of winter and abundance across Azeroth, the figure greeting visitors in the Valley of Strength is a hardworking performer employed by Smokywood Pastures. Sitting through long shifts listening to hopeful citizens talk about festive goodies tends to work up an appetite. Tired of simply talking about seasonal treats, the Greatfather gladly enlists passing travelers to satisfy his craving for warm baking and a cold beverage.",sp=0},{t="Culinary Holiday Spirit",b="Satisfying the Greatfather's request requires a touch of home cooking. Adventurers must acquire holiday spices sold directly by the goblin peddlers of Smokywood Pastures, forage small eggs from wild birds across the wilderness, and bake classic gingerbread cookies. Paired with a pitcher of ice cold milk purchased from a local tavern, the modest offering rewards the baker with festive cheer and a small token of gratitude from the feast's organizers.",sp=0}},faq={{q="Who is Greatfather Winter in Orgrimmar?",a="He is an actor hired by Smokywood Pastures to portray the legendary Greatfather Winter during the Feast of Winter Veil. Seated near their holiday trade display in the Valley of Strength, he greets the citizens of the Horde, listens to festive requests, and promotes seasonal merriment.",al={"who is great father winter","orgrimmar greatfather winter","is he the real winter father"}},{q="What treats does Greatfather Winter ask for?",a="Greatfather Winter asks for five freshly baked Gingerbread Cookies and a single serving of Ice Cold Milk to help him get through a long, tiring day of greeting holiday visitors.",al={"what does he want","treats requested","what cookies does he need"}},{q="How do you make Gingerbread Cookies?",a="The recipe and festive spices are sold by Smokywood Pastures vendors stationed around the holiday display. Bakers combine Holiday Spices with Small Eggs gathered from wild birds, then prepare the cookies over a cooking fire.",al={"how to get gingerbread cookies","gingerbread cookie recipe","cookie ingredients"}},{q="Where can Ice Cold Milk be found?",a="Ice Cold Milk can be purchased from virtually any food and drink vendor, innkeeper, or barkeep throughout Orgrimmar and other major settlements.",al={"where to get ice cold milk","buy milk","milk vendor"}},{q="Why is Greatfather Winter asking for food himself?",a="Listening to children and citizens chatter about food, gifts, and festivities all day leaves the performer thoroughly hungry. Since he cannot easily abandon his post in the Valley of Strength, he asks passing adventurers to bring him a quick snack.",al={"why does he want treats","is greatfather winter hungry"}},{q="Does this quest have an Alliance counterpart?",a="Yes. An identical request is made by the Greatfather Winter stationed in Ironforge, who similarly asks Alliance champions for gingerbread cookies and cold milk during the festival.",al={"alliance version","ironforge treats"}}},ang={["profession:Cooking"]="This holiday tradition offers apprentice chefs an easy opportunity to practice simple baking, turning wild eggs and seasonal spices into festive gingerbread.",["faction:Horde"]="Brought to Orgrimmar by the entrepreneurial goblins of Smokywood Pastures, the feast introduces a rare moment of lighthearted domestic cheer to the rugged warrior city."},kw={"gingerbread cookie","greatfather winter","holiday spices","ice cold milk","orgrimmar","smokywood pastures","treats for great-father winter","winter veil"},rel={"npc:greatfather-winter","zone:orgrimmar"},m={start="Great-father Winter",faction="Horde",id=6962},src={"Treats for Great-father Winter"}}
E["quest:6984"] = {t="quest",n="A Smokywood Pastures' Thank You!",z="orgrimmar",s="This festive task marks the conclusion of Smokywood Pastures' winter recovery efforts in Orgrimmar. After retrieving stolen treats from the Abominable Greench, adventurers are directed by goblin merchant Kaymard Copperpinch to receive a formal holiday token of appreciation directly from Great-father Winter.",h="This festive task marks the conclusion of Smokywood Pastures' winter recovery efforts in Orgrimmar.",sec={{t="A Corporate Holiday",b="Smokywood Pastures is keen to capitalize on the spirit of the Feast of Winter Veil, marketing treats, recipes, and seasonal cheer across the capitals of Azeroth. When their shipment of holiday goods was snatched away in the snowy hills of the Alterac Mountains, business stalled. With the treats reclaimed and the thieving Greench dealt with, vendor Kaymard Copperpinch is quick to ensure that helpful champions receive full corporate gratitude—and a suitably grand presentation.",sp=0},{t="Audience with Great-father Winter",b="Rather than handing over a standard coin purse over the counter, the goblins arrange for Great-father Winter himself to deliver the reward. Holding court beside the holiday tree in the Valley of Strength, the festive figure acts as both cultural patron and honorary figurehead for the festivities. He honors those who rescued the holiday supplies with a seasonal blessing and promises of further gifts delivered by post.",sp=0}},faq={{q="Who sends me to speak with Great-father Winter?",a="Kaymard Copperpinch, the Smokywood Pastures representative stationed in Orgrimmar's Valley of Strength, sends you to Great-father Winter once you have successfully recovered the company's stolen holiday treats.",al={"who starts this quest","quest giver","kaymard role"}},{q="What did I do to earn Smokywood Pastures' gratitude?",a="You tracked down the Abominable Greench in the Alterac Mountains, recovered the stolen holiday treats, and rescued Metzen the Reindeer, saving the Feast of Winter Veil supply chain for the goblins.",al={"why do they thank me","what treats were stolen","greench background"}},{q="Where is Great-father Winter located in Orgrimmar?",a="He sits under the large decorated Winter Veil tree in the Valley of Strength, right beside the Smokywood Pastures vendor stalls.",al={"great-father winter location","where is santa in org","winter veil tree org"}},{q="Who is Great-father Winter?",a="In ancient lore, Great-father Winter is an elemental or mythic herald of the changing seasons, draping the land in winter snow. For the Feast of Winter Veil, mortal stand-ins don his traditional red robes to spread goodwill and hand out treats to children and adventurers.",al={"who is great-father winter","is great-father winter real","winter veil lore"}},{q="What is Smokywood Pastures?",a="Smokywood Pastures is a goblin-run culinary and agricultural enterprise. They supply festive foods, seasonal ingredients, and decorative novelties to both the Horde and the Alliance during the Feast of Winter Veil.",al={"smokywood pastures lore","who are smokywood pastures","goblin holiday vendor"}},{q="Do I receive anything else after speaking with him?",a="Beyond Great-father Winter's immediate thanks, Smokywood Pastures arranges for a special Winter Veil Disguise Kit to be delivered to your mailbox a day after reporting in.",al={"quest reward","disguise kit","mail gift"}}},ang={["faction:Horde"]="The Horde's celebration of Winter Veil in Orgrimmar blends ancient shamanic reverence for the changing seasons with rowdy goblin commercialism.",["profession:Cooking"]="Smokywood Pastures' seasonal supplies are central to holiday cooking, providing exotic recipes and festive ingredients that chefs eagerly await each year."},kw={"feast of winter veil","great-father winter","greench","kaymard copperpinch","orgrimmar","smokywood pastures","valley of strength","winter veil"},rel={"npc:great-father-winter","npc:kaymard-copperpinch","zone:orgrimmar","topic:goblin","topic:horde"},m={start="Kaymard Copperpinch",["end"]="Great-father Winter",faction="Horde",id=6984},src={"A Smokywood Pastures' Thank You! (Horde)"}}
E["quest:7493"] = {t="quest",n="The Journey Has Just Begun",z="orgrimmar",s="\"The Journey Has Just Begun\" is a Horde quest offered in Orgrimmar to skilled leatherworkers following the defeat of Onyxia. Overlord Runthak recognizes the hero's craft and imparts the rare technique required to fashion protective cloaks from the broodmother's scales. This vital craft prepares the Horde for the deadly flames of Blackrock Spire.",h="\"The Journey Has Just Begun\" is a Horde quest offered in Orgrimmar to skilled leatherworkers following the...",sec={{t="A Broodmother's Legacy",b="The fall of Onyxia represents a triumph for the Horde, but it does not mark the end of the threat posed by the black dragonflight. The broodmother's scaled hide possesses remarkable resilience against draconic flame. Rather than letting such materials go to waste, Horde leadership seeks craftsmen capable of turning the dragon's remains into defensive armor.",sp=0},{t="Shield Against Shadow Flame",b="Overlord Runthak teaches gifted leatherworkers how to stitch together the Onyxia Scale Cloak. This knowledge is not meant merely for show or prestige. Deep within Blackrock Mountain, Onyxia's brother, Nefarian, wields devastating incendiary breath. Without the enchanted protection offered by their broodmother's own scales, any vanguard confronting the Lord of Blackrock would be reduced to ash.",sp=1}},faq={{q="Who offers this quest and where are they located?",a="The quest is provided by Overlord Runthak in Orgrimmar. He recognizes champions of the Horde who possess master leatherworking expertise and have aided in the downfall of Onyxia.",al={"natoj quest giver","where is overlord natoj","quest start"}},{q="What requirement is needed to receive this quest?",a="This quest is only offered to skilled leatherworkers who have completed the triumphant aftermath of Onyxia's defeat, such as 'Victory for the Horde' or 'A Most Puzzling Circumstance'.",al={"leatherworking requirement","how to get quest","prerequisites"}},{q="What does Overlord Runthak teach?",a="Overlord Runthak instructs the leatherworker in the technique needed to craft the Onyxia Scale Cloak using scales harvested from the fallen broodmother.",al={"quest reward recipe","onyxia cloak pattern","what do i learn"}},{q="Why is the Onyxia Scale Cloak important?",a="The cloak shields its wearer from the deadly, incendiary breath of Nefarian, the Lord of Blackrock. Without its unique protective properties, facing the brood's master would prove fatal.",al={"why make cloak","cloak purpose","nefarian cloak"}},{q="Who is the Lord of Blackrock?",a="The Lord of Blackrock is Nefarian, a powerful black dragon and Onyxia's brother, who plots from the heights of Blackrock Mountain to dominate the mortal races.",al={"who is lord of blackrock","nefarian identity","blackrock lord"}},{q="Why does the quest state that the journey has just begun?",a="Though Onyxia has been slain, the broader war against the black dragonflight and Nefarian's schemes inside Blackrock Mountain has only escalated.",al={"meaning of title","journey just begun why"}}},ang={["faction:Horde"]="For the Horde, securing protective gear forged from their fallen enemies is vital to safeguarding their forces against further draconic devastation."},kw={"blackrock","broodmother","cloak","leatherworking","natoj","nefarian","onyxia","scale"},rel={"npc:onyxia","topic:black-dragonflight","quest:7781","topic:horde","subzone:drag"},m={start="Overlord Runthak",faction="Horde",id=7493},src={"The Journey Has Just Begun (Horde)"}}
E["quest:7660"] = {t="quest",n="Wolf Swapping - Arctic Wolf",z="orgrimmar",s="\"Wolf Swapping - Arctic Wolf\" is an exchange arrangement offered by Ogunaro Wolfrunner in the Valley of Honor in Orgrimmar. Riders who possess the older Arctic Wolf can trade its horn for a swift wolf from the newly trained breeding stock. It allows veteran Horde riders to adopt a wolf with a distinct appearance without losing their riding speed.",h="\"Wolf Swapping - Arctic Wolf\" is an exchange arrangement offered by Ogunaro Wolfrunner in the Valley of Honor...",sec={{t="A Change of Mount",b="In the Valley of Honor, kennel master Ogunaro Wolfrunner oversees the breeding and training of the Horde's war wolves. With the arrival of newly bred swift wolves to the yards, Ogunaro offers an open trade to seasoned orcish riders. Anyone returning with the older Arctic Wolf can swap its horn for one of the newer lineage: a swift brown, gray or timber wolf.",sp=0},{t="The Valley's New Pack",b="The wolves pacing the paddocks in Orgrimmar represent generations of selective rearing since the Horde arrived on Kalimdor. While earlier swift wolves proved their speed on the march, the new stock exhibits striking visual variations and rugged builds suited to the harsh climates of Azeroth. Ogunaro guarantees that the new swift wolf runs just as swiftly as the Arctic Wolf traded in.",sp=0}},faq={{q="Who offers the Wolf Swapping exchange?",a="Ogunaro Wolfrunner, the wolf breeder and riding trainer stationed by the kennels in Orgrimmar's Valley of Honor, handles the swap.",al={"who gives wolf swapping","where to turn in old wolf","arctic wolf quest giver"}},{q="What do I need to trade for the Arctic Wolf?",a="The exchange runs the other way: you present Ogunaro with your old Horn of the Arctic Wolf, and in return he provides the horn of a Swift Brown, Swift Gray or Swift Timber Wolf from his newer pack.",al={"arctic wolf requirements","how to get arctic wolf","wolf trade requirements"}},{q="Is the Arctic Wolf slower than my old mount?",a="No. Ogunaro confirms that the wolves of the new pack are just as fast as the old Arctic Wolf they replace, differing only in breed and physical appearance.",al={"is arctic wolf slower","wolf swap speed difference","arctic wolf speed"}},{q="Can Alliance characters trade for this wolf?",a="No. The kennel and its mounts belong exclusively to the Horde, and Ogunaro Wolfrunner only conducts business with loyal Horde riders.",al={"can alliance get arctic wolf","alliance wolf swapping"}},{q="Can I see what the Arctic Wolf looks like before trading?",a="Yes. Ogunaro keeps representatives of the swift breeds around the yard in the Valley of Honor so riders can inspect the pack before making an exchange.",al={"preview arctic wolf","what does the wolf look like"}},{q="Why is Ogunaro swapping wolves in the first place?",a="Ogunaro introduced a new generation of swift wolves to the Orgrimmar yards and allows veteran riders who purchased the earlier swift breeds to trade for the newer appearances.",al={"why swap wolves","purpose of wolf swapping"}}},ang={["race:Orc"]="Orcs have bonded with wolves since their origins on Draenor, and Ogunaro's kennels continue that tradition right in the heart of Durotar.",["faction:Horde"]="The war wolves trained in Orgrimmar serve as foundational mounts for the Horde's cavalry forces across Kalimdor."},kw={"arctic wolf","horn of the arctic wolf","mount exchange","ogunaro wolfrunner","orgrimmar","swift wolf","valley of honor","wolf swapping"},rel={"npc:ogunaro-wolfrunner"},m={start="Ogunaro Wolfrunner",level="1",faction="Horde",id=7660},src={"Wolf Swapping - Arctic Wolf"}}
E["quest:7661"] = {t="quest",n="Wolf Swapping - Red Wolf",z="orgrimmar",s="Wolf Swapping - Red Wolf is an exchange offered by Ogunaro Wolfrunner in the Valley of Honor in Orgrimmar. It allows experienced Horde riders who possess an older breed of swift red wolf to trade their horn for an armored beast bred for modern warfare. This trade reflects the ongoing efforts of Orcish wolf breeders to better outfit Horde cavalry.",h="Wolf Swapping - Red Wolf is an exchange offered by Ogunaro Wolfrunner in the Valley of Honor in Orgrimmar.",sec={{t="A Change in the Kennels",b="In the Valley of Honor, kennel master Ogunaro Wolfrunner oversees the training and breeding of the Horde's war wolves. As the threats facing Durotar and Kalimdor have grown, wolf breeders have begun equipping their swiftest mounts with reinforced war barding. Rather than forcing veteran riders to purchase a brand-new mount, Ogunaro offers an exchange for those who originally bonded with an older, unarmored swift red wolf.",sp=0},{t="The Bond of Mount and Rider",b="Orcish culture holds wolves in high esteem, viewing them not as beasts of burden, but as loyal partners on the battlefield. Swapping a red wolf is not a matter of discarding an old ally, but trading in the ceremonial horns used to summon and maintain these swift mounts in the Orgrimmar yards. Ogunaro ensures that the new pack wolf provided carries the exact same speed and endurance as the mount it replaces.",sp=0}},faq={{q="Who offers the Wolf Swapping exchange?",a="Ogunaro Wolfrunner, the wolf breeder and mount vendor found in the Valley of Honor in Orgrimmar, offers this exchange.",al={"who gives wolf swapping","ogunaro quest","wolf swapping npc"}},{q="Why would a rider trade in their Red Wolf?",a="Breeders introduced newly armored swift wolves to better withstand the rigors of combat. Riders holding an older swift red wolf can exchange it for one of the newer armored breeds with a refreshed appearance while retaining the mount's speed.",al={"why swap wolf","red wolf swap reason","wolf trade purpose"}},{q="Does the new wolf run faster than the old one?",a="No. As Ogunaro explains, the new wolf runs at the exact same speed as the old swift mount, offering an updated war-ready look rather than a boost in pace.",al={"is new wolf faster","speed difference wolf swap"}},{q="Where can riders preview the new wolf?",a="Ogunaro keeps samples of the new swift pack around his yard in the Valley of Honor so riders can inspect the beasts before deciding to make an exchange.",al={"where to see new wolf","preview swift wolf"}},{q="Is this exchange open to Alliance players?",a="No. The wolf yards in Orgrimmar serve only the Horde, and Ogunaro Wolfrunner deals exclusively with Horde champions.",al={"can alliance swap wolves","alliance wolf swap"}},{q="What item is needed to complete the exchange?",a="Riders must bring the Horn of the Red Wolf, which proves their ownership of the older fast wolf, in order to trade it in.",al={"what item needed","wolf swap requirements"}}},ang={["race:Orc"]="Wolves are the traditional mount and spirit companions of the Orcish people, making Ogunaro's yard in the Valley of Honor a cornerstone of Orgrimmar's martial tradition.",["faction:Horde"]="The Horde relies on swift outrunners and wolf cavalry across Kalimdor to keep watch on encroaching threats and maintain supply lines."},kw={"horn of the red wolf","ogunaro wolfrunner","orgrimmar","red wolf","swift wolf","valley of honor","wolf swapping"},rel={"npc:ogunaro-wolfrunner"},m={start="Ogunaro Wolfrunner",level="1",faction="Horde",id=7661},src={"Wolf Swapping - Red Wolf"}}
E["quest:7783"] = {t="quest",n="The Lord of Blackrock",z="orgrimmar",s="This quest marks the culmination of the assault against Blackwing Lair, tasking champions with returning the severed head of Nefarian to Orgrimmar. Bringing the monstrous trophy to the veteran warrior Eitrigg secures proof that the brood of the Black Dragonflight has been broken. It is a moment of monumental triumph for the Horde against one of their most insidious enemies.",h="This quest marks the culmination of the assault against Blackwing Lair, tasking champions with returning the...",sec={{t="A Trophy of Ruin",b="Nefarian, the mastermind of Blackwing Lair and brood leader of the black dragons in the Eastern Kingdoms, has finally fallen. His colossal, battle-scarred head serves as undeniable proof of his demise. For the warriors of the Horde, hauling such a monumental prize out of the burning heights of Blackrock Mountain and across the Great Sea to Durotar is an act of undeniable glory.",sp=0},{t="Eitrigg's Judgment",b="The trophy is presented directly to Eitrigg, an esteemed veteran and trusted advisor to Warchief Thrall. Eitrigg knows the corruption within Blackrock Mountain better than almost anyone, being a Blackrock orc who went into solitary exile in northern Lordaeron after turning his back on the old, corrupted Horde. Seeing the son of Deathwing struck down validates years of struggle and breaks the dark dragon's cruel dominion over the orcs of the Blackrock clan.",sp=0},{t="Shadows of the Father",b="While Nefarian's death breaks the black dragonflight's twisted genetic experiments, his fall does not eliminate every danger. Upon viewing the decapitated dragon, Eitrigg remarks that Deathwing himself surely stirs at the news of his son's destruction. The victory is real, but it serves as a stark reminder of the greater terrors sleeping beneath the surface of the world.",sp=1}},faq={{q="Who is Nefarian?",a="Nefarian is a great black dragon and the son of Deathwing. From his perch high within Blackwing Lair atop Blackrock Mountain, he conducted twisted experiments to create the chromatic dragonflight and manipulated mortal races—especially the Dark Horde—to do his bidding.",al={"nefarian backstory","who is nefarian","black dragon lord"}},{q="Why is the trophy delivered to Eitrigg instead of Thrall?",a="Eitrigg is a seasoned Blackrock orc veteran who rejected the demonic bloodlust of the Old Horde and lived in self-imposed exile in northern Lordaeron. He serves as one of Thrall's most trusted counselors and possesses unmatched personal knowledge of the Blackrock clan and its corrupt masters.",al={"why eitrigg","who is eitrigg"}},{q="What happens in Orgrimmar when the head is turned in?",a="When the head of Nefarian is returned and mounted in Orgrimmar, a city-wide celebration takes place. The entire capital is granted the Rallying Cry of the Dragonslayer, boosting the combat prowess of all Horde members nearby.",al={"head buff","orgrimmar world buff","rallying cry buff"}},{q="Does this quest have an Alliance equivalent?",a="Yes, Alliance heroes complete a matching quest also named 'The Lord of Blackrock', delivering the head of Nefarian to Highlord Bolvar Fordragon in Stormwind Keep to grant their city the same blessing.",al={"alliance version","alliance counterpart"}},{q="What does Eitrigg mean by 'the evil one stirs'?",a="He is referring to Deathwing, the Aspect of Death and patriarch of the Black Dragonflight. Though long vanished and believed dead or hidden by many, Eitrigg fears that slaying Deathwing's powerful offspring will eventually draw the attention of the dread dragonfather.",al={"evil one stirs","who is the evil one"}},{q="Where does the head come from?",a="The quest begins by looting the Head of Nefarian directly from Nefarian's corpse after defeating him at the pinnacle of Blackwing Lair.",al={"how to get head of nefarian","quest starter item"}}},ang={["faction:Horde"]="Striking down Nefarian vindicates the Horde's honor and frees the Blackrock region from the grasp of a dragon who enslaved the renegade Dark Horde.",["race:Orc"]="For the orcs, presenting Nefarian's head to Eitrigg represents retribution against the beast that puppeteered Rend Blackhand and enslaved orcish clans for his experiments.",["class:Warrior"]="Bearing the massive, severed skull of a dragon lord to an old veteran warrior like Eitrigg is among the highest marks of martial renown."},kw={"blackrock","blackwing lair","deathwing","dragonslayer","eitrigg","nefarian","orgrimmar","rallying cry"},rel={"npc:eitrigg","zone:orgrimmar","topic:horde","npc:deathwing","quest:7781"},m={start="Head of Nefarian#Horde",["end"]="Eitrigg",faction="Horde",id=7783},src={"The Lord of Blackrock (Horde)"}}
E["quest:7784"] = {t="quest",n="The Lord of Blackrock",z="orgrimmar",s="This quest marks the final delivery of Nefarian's severed head to the leaders of Orgrimmar. Having proven the black dragon's demise to Eitrigg, champions are directed to Overlord Runthak in the Valley of Strength to display the trophy before the entire Horde.",h="This quest marks the final delivery of Nefarian's severed head to the leaders of Orgrimmar.",sec={{t="A Trophy for the Horde",b="After the black dragon Nefarian is slain atop Blackwing Lair, his head is brought to Orgrimmar as proof of his defeat. Veteran warrior Eitrigg confirms the fall of the son of Deathwing before sending the victor to Overlord Runthak in the Valley of Strength. There, the gruesome remains are prepared to be displayed publicly, serving as a warning to enemies and a rallying cry for the true Horde.",sp=0},{t="Claiming the Legacy",b="Nefarian ruled the heights of Blackrock Mountain, bending the Blackrock orcs and the Dark Horde to his will. By striking him down and hoisting his head high in the Valley of Strength, Warchief Thrall's Horde deals a mighty blow against the Black Dragonflight, and Runthak calls on all of Orgrimmar to revel in the Rallying Cry of the Dragonslayer.",sp=1}},faq={{q="What is the purpose of this quest?",a="It serves as the concluding turn-in for slaying Nefarian. After showing proof to Eitrigg, you report to Overlord Runthak in Orgrimmar's Valley of Strength to receive honors and have the severed head put on public display.",al={"what does this quest do","lord of blackrock turn in","why go to natoj"}},{q="Who is Overlord Runthak?",a="Overlord Runthak is an officer of the Horde stationed in the Valley of Strength within Orgrimmar, responsible for receiving major military trophies and granting recognition to Horde champions.",al={"who is natoj","overlord natoj role"}},{q="Why is Nefarian's head put on display?",a="Mounting the head of the black dragon proves beyond doubt that the master of Blackrock Mountain has fallen. It strengthens the morale of Orgrimmar's defenders, and the Rallying Cry of the Dragonslayer is cast on everyone in the city.",al={"why mount nefarians head","nefarian head display orgrimmar"}},{q="Who was Nefarian?",a="Nefarian was a great black dragon and a son of Deathwing. From Blackwing Lair atop Blackrock Mountain, he commanded the Blackrock orcs and the Dark Horde and bred the chromatic dragonflight.",al={"who was nefarian","nefarian lore"}},{q="Where is Overlord Runthak located?",a="Runthak stands on watch in the Valley of Strength, the central entrance district of Orgrimmar.",al={"where is natoj","natoj location"}},{q="What role does Eitrigg play in this?",a="Eitrigg, the Warchief's advisor and a Blackrock veteran who turned his back on the corrupted Old Horde, receives the head first. Once he confirms Nefarian's death, he sends you to Runthak to have the trophy officially mounted.",al={"why eitrigg","eitrigg involvement"}}},ang={["faction:Horde"]="The public display of Nefarian's head reinforces Thrall's new order and proves the might of the reformed Horde against the black dragon who manipulated the orcs of Blackrock Mountain.",["race:Orc"]="For orcs, witnessing the fall of the dragon who held the Blackrock clan in thrall provides deep catharsis, cleansing a dishonorable shadow cast over their people."},kw={"blackwing lair","eitrigg","head of nefarian","natoj","orgrimmar","nefarian","valley of strength"},rel={"npc:eitrigg","quest:7781","subzone:valley-of-strength","zone:orgrimmar","topic:horde"},m={start="Eitrigg",["end"]="Overlord Runthak",faction="Horde",id=7784},src={"The Lord of Blackrock (Horde 2)"}}
E["quest:809"] = {t="quest",n="Ak'Zeloth",z="orgrimmar",s="Ak'Zeloth is an early Horde quest dispatched by the warlock Neeru Fireblade from deep within Orgrimmar's Cleft of Shadow. Driven by evidence of lingering demonic corruption, Neeru sends adventurers into the Barrens to rendezvous with his field contact stationed near the border.",h="Ak'Zeloth is an early Horde quest dispatched by the warlock Neeru Fireblade from deep within Orgrimmar's...",sec={{t="A Trail of Shadow",b="Following the discovery of a Burning Blade insignia collar in Durotar, Neeru Fireblade claims to hunt down demonic remnants threatening the newly settled Horde. Presenting himself as a watchdog against fel taint, Neeru directs adventurers toward the arid plains of the Barrens, warning that a dark cult is gathering around an artifact of vile power known as the Demon Seed.",sp=0},{t="The Outpost Contact",b="To coordinate the strike against the cult, adventurers must seek out Ak'Zeloth, Neeru's assistant stationed near the Far Watch Post on the Durotar-Barrens border. Yet upon arrival, Ak'Zeloth greets the mission with quiet skepticism, openly musing on why his master would genuinely seek the artifact's demise before providing instructions on how to handle the Demon Seed atop Dreadmist Peak.",sp=1}},faq={{q="Who gives this quest?",a="The quest is given by Neeru Fireblade, a warlock dwelling in the shadowy cavern of the Cleft of Shadow beneath Orgrimmar, immediately after you present him with a Burning Blade collar.",al={"quest starter","where to get ak'zeloth","neeru fireblade quest"}},{q="Where is Ak'Zeloth located?",a="Ak'Zeloth is located just outside the Far Watch Post, right along the eastern border of the Barrens where the bridge crosses over from Durotar.",al={"ak'zeloth location","where is ak'zeloth","find ak'zeloth"}},{q="What is the Demon Seed?",a="The Demon Seed is a foul artifact of demonic power held by the Burning Blade cult atop Dreadmist Peak, an ominous mountain situated in the northern Barrens.",al={"demon seed lore","what is the seed"}},{q="Why does Ak'Zeloth find Neeru's orders strange?",a="Ak'Zeloth does not explain himself. He simply remarks that it is strange Neeru wants the Demon Seed destroyed, then agrees to tell you how to remove it.",al={"why is ak'zeloth surprised","strange reaction ak'zeloth"},sp=1},{q="What quest follows this one?",a="Speaking with Ak'Zeloth immediately leads into the quest 'The Demon Seed', which charges you with ascending Dreadmist Peak to neutralize the corrupting relic.",al={"next quest after ak'zeloth","ak'zeloth followup"}},{q="Is this quest part of the Burning Blade storyline?",a="Yes. It serves as a vital bridge connecting the local cultist conspiracies discovered in Durotar to the wider, organized cult activity entrenched in the Barrens.",al={"burning blade questline","orgrimmar cult quest"}}},ang={["class:Warlock"]="Warlocks familiar with Neeru Fireblade's teachings may recognize the subtle double-dealings of their mentor when his assistant questions the call to destroy a demonic relic.",["race:Orc"]="Orcs have fought bitterly to escape the Burning Legion's grasp, making any sign of the Burning Blade cult and demonic relics on their doorstep an urgent threat.",["faction:Horde"]="Securing the Far Watch Post and clearing Dreadmist Peak is critical to safeguarding the nascent trade and transit routes linking Durotar with the Barrens."},kw={"ak'zeloth","barrens","burning blade","cleft of shadow","demon seed","dreadmist peak","far watch post","neeru fireblade"},rel={"quest:829","quest:924","subzone:far-watch-post","subzone:dreadmist-peak","zone:barrens","topic:burning-legion"},m={start="Neeru Fireblade",["end"]="Ak'Zeloth",level="13",faction="Horde",id=809},src={"Ak'Zeloth (Classic)"}}
E["quest:829"] = {t="quest",n="Neeru Fireblade",z="orgrimmar",s="This quest sends Horde adventurers from Margoz in Durotar to Orgrimmar's shadowy underbelly. Entrusted with a demonic Searing Collar recovered from the Burning Blade cult, you are directed to Neeru Fireblade, a prominent warlock residing in the Cleft of Shadow who claims to study dark arts only to protect the Horde.",h="This quest sends Horde adventurers from Margoz in Durotar to Orgrimmar's shadowy underbelly.",sec={{t="A Shaman's Limits",b="After recovering Searing Collars from the cultists lurking in Skull Rock, the shaman Margoz discovers that unraveling their foul sorcery exceeds his ancestral arts. Shamans commune with elemental spirits and the earth, while these artifacts reek of raw demonic corruption. Recognizing that understanding the Burning Blade's devices requires someone well-versed in the occult, Margoz sends you to seek out a warlock residing in the capital.",sp=0},{t="Into the Cleft of Shadow",b="Beneath the red cliffs of Orgrimmar lies the Cleft of Shadow, a dimly lit cavern where practitioners of forbidden magics ply their trade under Thrall's wary eye. There dwells Neeru Fireblade, an influential orc warlock who insists his mastery of fel power is aimed entirely at thwarting demonic threats. Handing him the example collar draws his immediate curiosity, bringing Durotar's cult investigation straight into the heart of the warlock enclave.",sp=0}},faq={{q="Why does Margoz send me to a warlock?",a="Margoz is a shaman whose powers derive from the elements and the spirits of the ancestors. The Searing Collars retrieved from Skull Rock are purely demonic in nature, and divining their enchantments and origins requires someone trained in fel magic and the dark arts.",al={"why warlock","why neeru","margoz warlock"}},{q="Where can I find Neeru Fireblade?",a="Neeru Fireblade is located in the Cleft of Shadow, the subterranean cavern complex beneath Orgrimmar where warlocks, rogues, and shadow casters gather.",al={"neeru location","where is neeru fireblade","cleft of shadow neeru"}},{q="Can Neeru Fireblade be trusted?",a="Margoz himself harbors doubts, noting that while Neeru claims his occult research is benign and used only to fight demons, whether that is true or false remains to be seen. Thrall allows warlocks in Orgrimmar under strict supervision, but caution is advised.",al={"is neeru evil","neeru trustworthy","can i trust fireblade"}},{q="What is the Example Collar?",a="The Example Collar is one of the Searing Collars taken from the Burning Blade cultists at Skull Rock. Margoz gives it to you to deliver directly to Neeru Fireblade for magical analysis.",al={"example collar","what is the collar","searing collar quest item"}},{q="What happens after giving the collar to Neeru?",a="Neeru examines the collar closely, leading into the quest Ak'Zeloth, where he sends you deeper into the investigation of the cult's shadowy presence in Durotar.",al={"next quest after neeru","what does neeru do","quest chain after neeru"}},{q="Why does the Horde allow warlocks in Orgrimmar?",a="Warchief Thrall tolerates warlocks out of pragmatic necessity, keeping them contained within the subterranean Cleft of Shadow so their dangerous research can be watched, controlled, and occasionally used to understand demonic enemies.",al={"why are warlocks allowed","warlocks in cleft of shadow","thrall warlocks"}}},ang={["class:Shaman"]="Margoz's admission marks a clear boundary between shamanism and demonic magic: the elements will not commune with fel artifacts, requiring the aid of a warlock.",["class:Warlock"]="Entering the Cleft of Shadow to consult Neeru Fireblade brings you into direct contact with the most prominent warlock in Orgrimmar, validating the pragmatic value of your forbidden craft to the Horde.",["faction:Horde"]="This mission demonstrates the fragile truce within Orgrimmar, where the Warchief's shamans must occasionally turn to shadowy outcasts in the Cleft of Shadow to protect Durotar from extinction."},kw={"burning blade","cleft of shadow","durotar","margoz","neeru fireblade","orgrimmar","searing collar","skull rock","warlock"},rel={"quest:827","quest:828","quest:809","quest:924","quest:806","subzone:cleft-of-shadow","zone:orgrimmar","zone:durotar"},m={start="Margoz",["end"]="Neeru Fireblade",level="12",faction="Horde",id=829},src={"Neeru Fireblade (quest)"}}
E["quest:8359"] = {t="quest",n="Flexing for Nougat",z="orgrimmar",s="During the festive autumn celebration of Hallow's End, Innkeeper Gryshka in Orgrimmar offers sweet seasonal confections to those willing to play along. To earn a piece of Orgrimmar Nougat for a bedridden child, champions of the Horde must swallow their warrior pride and show off their muscles on command.",h="During the festive autumn celebration of Hallow's End, Innkeeper Gryshka in Orgrimmar offers sweet seasonal...",sec={{t="Tricks for Treats",b="Hallow's End brings high spirits, pranks, and confection gathering to the bustling capitals of Azeroth. While adventuring heroes often face dragons and dark sorcery, the traditions of the autumn holiday require a much lighter touch. Innkeeper Gryshka, presiding over the common room of Orgrimmar's inn, is happy to share her supply of holiday sweets, but only if patrons adhere to the oldest rule of the season: perform a trick, or leave empty-handed.",sp=0},{t="Muscle on Display",b="Taking amusement in whatever disguise or armor an adventurer arrives in, Gryshka demands a show of raw Orcish strength. Before parting with a single piece of Orgrimmar Nougat meant for young Spoops, she insists on seeing the mighty traveler strike a muscular pose. It is a lighthearted reminder that even the most feared combatants in the Horde can be made to entertain the common folk for candy.",sp=0}},faq={{q="Who is asking for the flex?",a="Innkeeper Gryshka, the proprietor of the main tavern in the Valley of Strength within Orgrimmar, demands the trick before handing over her holiday sweets.",al={"who gives the quest","gryshka","innkeeper gryshka"}},{q="Why do I need to flex for candy?",a="Hallow's End custom dictates that trick-or-treaters must perform a small trick in exchange for treats. Gryshka decides to tease the adventurer by requesting a display of sheer physical power before rewarding them.",al={"why flex","what is the trick","nougat condition"}},{q="What is the Orgrimmar Nougat used for?",a="The nougat is one of four distinct sweets gathered across the Horde's capitals to cheer up Spoops, a sick orphan boy unable to go trick-or-treating on his own.",al={"why do i need nougat","nougat use","spoops candy"}},{q="Where does Innkeeper Gryshka reside?",a="She can be found behind the counter of the main inn located in Orgrimmar's Valley of Strength, serving weary travelers and locals alike.",al={"where is gryshka","orgrimmar innkeeper location"}},{q="Can any Horde member participate in this?",a="Yes, any member of the Horde can visit Innkeeper Gryshka during Hallow's End to strike a pose and claim the seasonal confection.",al={"who can flex","faction restrictions","horde only"}},{q="What holiday is this a part of?",a="This task is part of Hallow's End, an autumn festival celebrating the end of the harvest and the defiance of mortality through costume, pranks, and sweets.",al={"which event","what holiday","hallows end quest"}}},ang={["faction:Horde"]="Even veteran champions who face down deadly warlords are reduced to flexing their biceps for tavernkeepers to gather festive sweets for the children of the Horde.",["race:Orc"]="Orgrimmar's innkeeper expects an impressive display of muscle, a quintessential Orcish test of pride turned into lighthearted holiday theater.",["class:Warrior"]="Warriors who pride themselves on devastating frontline feats may find it amusing—or mildly humbling—to pose like stage performers for a square of festive candy."},kw={"candy","flexing","gryshka","hallow's end","nougat","orgrimmar","spoops","trick or treat"},rel={"npc:innkeeper-gryshka","zone:orgrimmar"},m={start="Innkeeper Gryshka",faction="Horde",id=8359},src={"Flexing for Nougat (Horde)"}}
E["quest:8677"] = {t="quest",n="Darkhorn the Elder",z="orgrimmar",s="Darkhorn the Elder is a seasonal quest completed by seeking out Elder Darkhorn in Orgrimmar during the Lunar Festival. Travelers pay their respects to the honored ancestor, receiving a token of wisdom and celebration in return. She stands in the heart of the Horde capital as a testament to age, survival, and ancestral pride.",h="Darkhorn the Elder is a seasonal quest completed by seeking out Elder Darkhorn in Orgrimmar during the Lunar...",sec={{t="Honoring the Ancestor",b="During the Lunar Festival, the spirits of revered ancestors manifest across Azeroth to share their wisdom with the living. Elder Darkhorn rests within the fortified ramparts of Orgrimmar, observing the bustle of the young warrior city. Approaching her offers champions of the Horde—and any Alliance adventurer brave enough to slip through the gates—a chance to pay formal homage to those who walked the earth generations before.",sp=0},{t="The Spirit of the Festival",b="Upon receiving greeting and reverence from passing travelers, Elder Darkhorn acknowledges the vibrant spark of life within them. In exchange for honoring the ways of old, she grants a Coin of Ancestry and her personal blessing. These tokens celebrate the triumph over ancient perils and remind the living to cherish the strength passed down through unbroken bloodlines.",sp=0}},faq={{q="Who is Elder Darkhorn?",a="Elder Darkhorn is an ancestral spirit who appears in Orgrimmar during the Lunar Festival. She serves as an emissary of the past, offering blessings and tokens to travelers who take time to pay homage to the elders.",al={"elder darkhorn","who is darkhorn","darkhorn lore"}},{q="Where can I find Elder Darkhorn?",a="She can be found resting within Orgrimmar, in the Valley of Wisdom just outside Grommash Hold, where she observes the daily life of the Horde capital during the festival season.",al={"darkhorn location","where is darkhorn","elder darkhorn orgrimmar"}},{q="What is the purpose of the Lunar Festival elders?",a="The elders manifest during the Lunar Festival so the living may honor ancestral wisdom, courage, and sacrifice. Paying respect to an elder yields a Coin of Ancestry, a symbol of heritage and communal remembrance.",al={"why find elders","lunar festival elders","ancestor coins"}},{q="Can Alliance players honor Elder Darkhorn?",a="Yes, ancestral elders welcome respect from all living mortals regardless of faction. However, because Elder Darkhorn resides deep within the Horde stronghold of Orgrimmar, Alliance visitors must brave hostile guards and players to reach her.",al={"can alliance talk to darkhorn","alliance elder darkhorn","alliance orgrimmar elder"}},{q="What reward does Elder Darkhorn grant?",a="Acknowledging Elder Darkhorn awards a Coin of Ancestry, along with ancestral blessings and lucky red envelopes during the festival.",al={"darkhorn reward","what does darkhorn give","coin of ancestry darkhorn"}},{q="Is this quest repeatable?",a="No, each ancestral elder may only be honored once per character during the annual Lunar Festival celebration.",al={"can i do darkhorn again","is darkhorn repeatable","darkhorn daily"}}},ang={["faction:Horde"]="For Horde champions, visiting Elder Darkhorn is a convenient opportunity to honor ancestral tradition right within the safety and bustling heart of their capital.",["faction:Alliance"]="Reaching Elder Darkhorn requires daring infiltration through the heavily defended gates and streets of Orgrimmar, turning ancestral homage into a dangerous test of stealth or force.",["class:Shaman"]="Shaman revere the communion between the living world and ancient spirits, making visits to ancestral elders like Darkhorn a profound spiritual duty."},kw={"ancestor","coin of ancestry","darkhorn","elder darkhorn","elders","lunar festival","orgrimmar","valley of strength"},m={start="Elder Darkhorn",id=8677},src={"Darkhorn the Elder"}}
E["quest:8828"] = {t="quest",n="Winter's Presents",z="orgrimmar",s="Winter's Presents is an invitation extended to adventurers in Orgrimmar during the Feast of Winter Veil. Guided by holiday organizers and goblin apparatus tenders, Horde heroes are directed to visit Great-father Winter beneath the decorated festive tree to claim gifts prepared for them.",h="Winter's Presents is an invitation extended to adventurers in Orgrimmar during the Feast of Winter Veil.",sec={{t="Season of Generosity",b="As the chill winds of late year sweep across Durotar, the Feast of Winter Veil brings a rare moment of peace and celebration to the harsh red stones of Orgrimmar. Promoters from Smokywood Pastures, alongside holiday enthusiasts, ensure that every warrior, hunter, and wanderer resting in the capital knows that gifts await them beneath the decorated tree.",sp=0},{t="The Patron and the Peddlers",b="Seated amidst holiday ribbons and packaged cartons near the Smokywood Pastures market stands Great-father Winter himself. While the ancient figure embodies the renewal of the season, the savvy merchant goblins never miss an opportunity to remind visitors that the holiday spirit pairs exceptionally well with their stock of seasonal wares and festive treats.",sp=0}},faq={{q="Where do I turn in Winter's Presents?",a="You turn in this quest to Great-father Winter, who sits near the Smokywood Pastures festive area and decorated tree in the Valley of Strength in Orgrimmar.",al={"where is great father winter","turn in location","presents hand in"}},{q="Who sends you to see Great-father Winter?",a="Either a Holiday Enthusiast or a goblin Wonderform Operator tending to the PX-238 Winter Wondervolt machines around the holiday setups will direct you to the tree.",al={"who gives quest","quest starter","holiday enthusiast"}},{q="What is Smokywood Pastures?",a="Smokywood Pastures is an entrepreneurial goblin merchant organization that sponsors and supplies the festivities, food, treats, and gift goods across major capitals during Winter Veil.",al={"smokywood pastures lore","who are smokywood pastures"}},{q="What does Great-father Winter do once you speak with him?",a="Great-father Winter welcomes you personally to the Feast of Winter Veil, directs you to the wrapped parcels waiting under the tree, and warmly suggests checking out Smokywood Pastures merchandise for your companions.",al={"great-father winter greeting","quest completion dialogue"}},{q="Why does the Horde celebrate Winter Veil in Orgrimmar?",a="While rooted in ancient legends of winter's renewal, the modern festival is embraced by the Horde as a time of respite, feasting, and community amid their struggle to build their new home in Kalimdor.",al={"horde winter veil lore","why orcs celebrate winter veil"}},{q="What is the PX-238 Winter Wondervolt mentioned by the operator?",a="It is a whimsical goblin contraption placed near the festival grounds that temporarily transforms volunteers into festively dressed Little Helpers.",al={"winter wondervolt","px 238 wondervolt"}}},ang={["faction:Horde"]="For the Horde, the bustling holiday camp within Orgrimmar offers a joyful, warm gathering spot away from the ongoing border conflicts across Kalimdor.",["race:Orc"]="Even in the austere seat of the Warchief, orcs pause their duties to share winter feasts and accept hospitality beneath the boughs of the Winter Veil tree."},kw={"great-father winter","holiday enthusiast","orgrimmar","presents","smokywood pastures","winter veil","winter's presents","wonderform operator"},rel={"npc:great-father-winter","zone:orgrimmar"},m={start="Wonderform Operator / Holiday Enthusiast",["end"]="Great-father Winter",faction="Horde",id=8828},src={"Winter's Presents (Horde)"}}
E["quest:8851"] = {t="quest",n="Five Signets for War Supplies",z="orgrimmar",s="Five Signets for War Supplies is a logistical exchange coordinated by Warlord Gorchuk in Orgrimmar. By turning in commendation signets earned during the Horde's massive military mobilization, champions receive personal supplies to keep them equipped for the coming conflict.",h="Five Signets for War Supplies is a logistical exchange coordinated by Warlord Gorchuk in Orgrimmar.",sec={{t="A Continent-Wide Effort",b="Across Kalimdor, the Horde is marshaling vast quantities of raw goods, munitions, and provisions for a massive campaign. While ordinary gatherers and tradesfolk haul crates of bandages, metals, and herbs into the city centers, military overseers issue commendation signets to honor their service. These tokens signify direct contribution to the grand stockpile accumulating in Orgrimmar's central avenues.",sp=0},{t="Materiel for the Frontlines",b="Warlord Gorchuk recognizes that while collecting supplies for the greater war effort is critical, individual warriors also require gear and provisions to stay alive when marching into battle. Through this requisition, fighters can forego personal recognition and trade their commendation signets back into the war machine in exchange for field-ready supplies and surplus materiel.",sp=0}},faq={{q="What is the purpose of turning in five signets?",a="It allows soldiers aiding the Horde's war mobilization to exchange their earned commendation tokens directly for personal survival gear and field supplies rather than holding them for political recognition.",al={"why turn in 5 signets","signet turn in purpose","what do i get for 5 signets"}},{q="Who is Warlord Gorchuk?",a="Warlord Gorchuk is a Horde military coordinator stationed in Orgrimmar, responsible for managing supplies and authorizing requisitions for warriors preparing for impending conflict.",al={"gorchuk identity","who is gorchuk"}},{q="How do you obtain Horde Commendation Signets?",a="Signets are awarded by quartermasters and logistics officers across the Horde when adventurers contribute raw materials, food, bandages, and crafting resources to the faction's war effort.",al={"get signets","where do signets come from","commendation signet source"}},{q="Can this requisition be repeated?",a="Yes. Warlord Gorchuk is willing to authorize repeated exchanges as long as you continue to deliver the required batches of signets to support the troops.",al={"is this repeatable","can i do this again"}},{q="Why does Gorchuk say I won't receive recognition for this exchange?",a="Spending your commendation signets directly on personal supplies draws from the quartermaster's caches rather than archiving your deeds, meaning you trade away formal accolades in favor of immediate, practical field materiel.",al={"no recognition meaning","why no rep"}},{q="Where does this exchange take place?",a="The requisition is handled directly in Orgrimmar, where stockpiles and logistics coordinators gather to prepare the Horde for the war effort.",al={"where is this quest","turn in location"}}},ang={["faction:Horde"]="Every crate and bundle collected in Orgrimmar ensures the Horde stands fully supplied against the catastrophic threats lurking on the horizon.",["class:Warrior"]="Frontline brawlers who value practical survival over ceremonial recognition will find Gorchuk's supply crates well worth their accumulated signets."},kw={"commendation","gorchuk","materiel","orgrimmar","requisition","signets","supplies","war effort"},rel={"npc:warlord-gorchuk","topic:horde"},m={start="Warlord Gorchuk",level="19",faction="Horde",id=8851},src={"Five Signets for War Supplies (Horde)"}}
E["quest:8852"] = {t="quest",n="Ten Signets for War Supplies",z="orgrimmar",s="Ten Signets for War Supplies is a logistical exchange coordinated by Warlord Gorchuk in Orgrimmar. Champions of the Horde can trade surplus commendation signets for practical battlefield equipment and supplies. While this trade forfeits official glory and recognition, it directly equips front-line soldiers for the looming conflicts ahead.",h="Ten Signets for War Supplies is a logistical exchange coordinated by Warlord Gorchuk in Orgrimmar.",sec={{t="Materiel for the Front",b="As the Horde mobilizes its legions for war, gathering supplies is just as vital as assembling warriors. Warlord Gorchuk oversees logistics in the Valley of Spirits, ensuring that crates of weapons, rations, and armor flow toward the front lines. Those who have proven their dedication can surrender commendation signets to draw useful equipment from the army's reserves.",sp=0},{t="Practical Survival over Glory",b="Horde Commendation Signets are typically surrendered as proof of service, earning a soldier prestige and renown among the leadership. Exchanging them directly for gear bypasses this formal recognition in favor of raw survival. Gorchuk understands that an extra satchel of supplies or a sturdy weapon can mean the difference between life and death once the clash of armies begins.",sp=0}},faq={{q="What are Horde Commendation Signets?",a="Horde Commendation Signets are official tokens awarded to champions who gather critical raw materials and resources for the Horde's war mobilization.",al={"commendation signet","horde signets","war signets"}},{q="Who is Warlord Gorchuk?",a="Warlord Gorchuk is a Horde logistics officer stationed in Orgrimmar, responsible for collecting war resources and distributing battlefield provisions to mobilized troops.",al={"gorchuk","warlord gorchuk location","who is gorchuk"}},{q="Why turn signets in for supplies instead of faction reputation?",a="Trading signets for supplies sacrifices political standing and formal recognition in exchange for practical items, bandages, and gear that aid immediate survival on the front lines.",al={"signets vs supplies","why supplies","commendation rewards"}},{q="Can this exchange be repeated?",a="Yes. Warlord Gorchuk will continue to trade field supplies as long as you have the required batches of commendation signets to offer.",al={"is this repeatable","repeat signets","turn in again"}},{q="Where does this exchange take place?",a="The exchange takes place in the capital city of Orgrimmar, where the Horde's war preparations and stockpiles are centered.",al={"where to turn in signets","signet turn in location","gorchuk location"}},{q="What kind of war is the Horde preparing for?",a="The Horde is amassing massive stockpiles of metal, cloth, herbs, and rations to arm an expeditionary force capable of facing an impending, cataclysmic threat.",al={"what war","why gathering supplies","war effort"}}},ang={["faction:Horde"]="Every crate of supplies gathered in Orgrimmar directly fuels the Horde's readiness for the brutal battles on the horizon.",["class:Warrior"]="Front-line fighters know that cold steel and ample rations win prolonged wars just as reliably as martial courage."},kw={"commendation","gorchuk","logistics","orgrimmar","signets","supplies","war effort","warlord gorchuk"},rel={"npc:warlord-gorchuk","topic:horde"},m={start="Warlord Gorchuk",level="29",faction="Horde",id=8852},src={"Ten Signets for War Supplies (Horde)"}}
E["quest:9263"] = {t="quest",n="Investigate the Scourge of Orgrimmar",z="orgrimmar",s="The Scourge has brazenly established an encampment right outside the gates of Orgrimmar under the shadow of a floating necropolis. Lieutenant Dagel tasks defenders with repelling the undead, recovering necrotic stones, and probing the mysterious runic circles humming with necromantic energy. This sudden intrusion brings the Lich King's reach directly to the heart of Durotar.",h="The Scourge has brazenly established an encampment right outside the gates of Orgrimmar under the shadow of a...",sec={{t="Undead at the Gates",b="The threat of the Scourge is no longer confined to the ruined kingdoms of Lordaeron or the icy wastes of the north. Floating necropolises have appeared across Azeroth, casting dark shadows even over Durotar. At Orgrimmar's very threshold, undead forces have gathered, carving out encampments and threatening the capital of the Horde. Lieutenant Dagel and the Argent Dawn are coordinating defensive efforts, calling upon local champions to push the invaders back before they can establish an unbreakable siege.",sp=0},{t="Necrotic Relics and Dark Whispers",b="Beyond simply slaying the encroaching monstrosities and gathering their dim necrotic stones, the defense hinges on understanding the invaders' methods. Encircling their camp are glowing runic sigils, resonant with the same dark power suffusing the necropolis above. Those brave enough to step into the runes encounter unnatural voices echoing through the ether—sinister conduits of communication bridging the vanguard directly to the malevolent wills guiding the Scourge invasion.",sp=1}},faq={{q="Why is the Scourge attacking Orgrimmar?",a="The Lich King has dispatched his undead forces and floating necropolises across the world to strike at major population centers. By placing troops right outside the gates of Durotar, the Scourge seeks to overwhelm and divide the Horde's forces directly at their seat of power.",al={"why scourge orgrimmar","undead outside org","lich king attacks orgrimmar"}},{q="Who is Lieutenant Dagel?",a="Lieutenant Dagel is an officer working in coordination with the Argent Dawn to rally defenders against the invasion. Stationed near the threat, Dagel directs fighters to eliminate the undead and examine the arcane tools they use on the battlefield.",al={"lieutenant dagel","dagel questgiver","who is dagel"}},{q="What are the dim necrotic stones?",a="Dim necrotic stones are foul remnants carried by the invading undead soldiers. They serve both as tangible proof of slain Scourge aberrations and as artifacts infused with the dark magic sustaining the invasion.",al={"necrotic stones","what are dim necrotic stones","dim stones"}},{q="What are the glowing runic circles outside the city?",a="The runic circles are mystical conduits inscribed by the Scourge. Stepping into them reveals eerie whispers, indicating that they function as unnatural communication nodes linking the foot soldiers to commanding minds elsewhere.",al={"runic circles","glowing runes org","scourge circles"}},{q="Why is the Argent Dawn involved in Durotar?",a="The Argent Dawn is an independent order dedicated to eradicating the Scourge wherever it manifests. Because the invasion threatens every living civilization, the order cooperates with Horde defenders to secure Orgrimmar's borders.",al={"argent dawn in orgrimmar","why argent dawn here","argent dawn horde"}},{q="Is the necropolis overhead dangerous to the city?",a="Yes. A floating necropolis acts as a staging ground, bastion, and transport for Scourge troops. Its presence directly over Durotar's doorstep allows the undead to replenish their ground assault and project dark magic across the terrain.",al={"floating citadel org","necropolis above durotar"}}},ang={["faction:Horde"]="An invasion force camped within sight of Orgrimmar's towers is an unbearable insult to the Horde. Defending Durotar against the Lich King's minions is a vital duty for any sworn champion.",["race:Orc"]="The dry red soil of Durotar was won through hardship and blood. Orcs will not allow mindless monstrosities to blight the home they carved out with their bare hands.",["race:Undead"]="For the Forsaken, the Scourge is a reminder of their former enslavement. Crushing these invaders is a personal vendetta against the Lich King's continuing reach."},kw={"argent dawn","dagel","durotar","invasion","lich king","necrotic stone","orgrimmar","runic circle","scourge"},rel={"zone:orgrimmar","topic:scourge","topic:lich-king","topic:argent-dawn"},m={start="Lieutenant Dagel",level="10",faction="Horde",id=9263},src={"Investigate the Scourge of Orgrimmar"}}
E["subzone:broken-tusk"] = {t="subzone",n="Broken Tusk",z="orgrimmar",s="The Broken Tusk is the bustling main tavern in Orgrimmar's Valley of Strength. Sitting right at the crossroads of the city's gates, bank, and auction house, it provides weary Horde champions with hearth, drink, and a place to rest. It is also famously home to the hapless tauren Gamon.",h="The Broken Tusk is the bustling main tavern in Orgrimmar's Valley of Strength.",sec={{t="Heart of the Valley",b="Situated directly within the Valley of Strength, the Broken Tusk serves as the primary gathering place for travelers freshly arriving through Orgrimmar's massive front gates. Inside its timber-and-hide walls, patrons share grog, trade rumors from Durotar and the Barrens, and listen to traditional orcish songs of valor and sacrifice echoing over the din. Its central location beside the city's trade hub makes it perpetually crowded with adventurers binding their hearthstones before marching out to battle.",sp=0},{t="Gamon's Misfortune",b="Among the merchants, bartenders, and rowdy patrons, the tavern's most recognizable permanent resident is Gamon. This solitary tauren quietly nurses his drinks, but his presence regularly draws the ire and drunken rowdiness of fellow Horde members. Rogues frequently target him to practice their sleight of hand, and brawlers test their strength against him, making his tenure at the tavern a remarkably dangerous one.",sp=0}},faq={{q="Where is the Broken Tusk located?",a="The Broken Tusk sits in the Valley of Strength, just inside the main southern gates of Orgrimmar. It is located directly across from the bank and auction house.",al={"broken tusk location","where is the orgrimmar inn","valley of strength inn"}},{q="Who is Gamon and why does everyone attack him?",a="Gamon is a quiet tauren patron who stays inside the Broken Tusk. Because he is flagged neutral to Horde players and carries no faction guards to his defense, bored adventurers and rowdy brawlers regularly rough him up. Aspiring Horde rogues also target his pockets to hone their pickpocketing skills.",al={"who is gamon","gamon tavern","why attack gamon"}},{q="What services does the tavern provide?",a="The tavern functions as a major rest area where adventurers can set their hearthstone with the innkeeper, purchase food and strong drink, or log out rested amidst the bustle of the capital city.",al={"what can i do here","broken tusk services"}},{q="What kinds of songs are sung here?",a="Patrons and bards inside the Broken Tusk often sing lok'vadnods—traditional orcish songs celebrating the heroic deeds and heritage of great warriors.",al={"broken tusk songs","inn music","lok'vadnod"}}},ang={["faction:Horde"]="As the foremost tavern greeting new arrivals through the Great Gate of Orgrimmar, the Broken Tusk is an indispensable landmark for setting hearthstones and meeting fellow champions of the Horde.",["class:Rogue"]="The tavern's unfortunate patron, Gamon, serves as a classic early mark for Horde rogues learning to pick pockets in the safety of friendly territory."},kw={"broken tusk","durotar","gamon","inn","innkeeper","orgrimmar","tavern","valley of strength"},rel={"subzone:valley-of-strength","zone:orgrimmar"},src={"Broken Tusk"}}
E["subzone:cleft-of-shadow"] = {t="subzone",n="Cleft of Shadow",z="orgrimmar",s="Tucked deep within the subterranean caverns beneath Orgrimmar, the Cleft of Shadow houses the city's practitioners of stealth, sorcery, and demonology. Far from the proud warrior ethos of Thrall's upper districts, it serves as a necessary haven for rogues, warlocks, and mages operating in the shadows of the Horde.",h="Tucked deep within the subterranean caverns beneath Orgrimmar, the Cleft of Shadow houses the city's...",sec={{t="A Subterranean Sanctuary",b="While Thrall's new Horde champions honor, shamanism, and strength of arms, practical leadership demands a place for subtler arts. Carved into the damp stone caverns below the capital, the Cleft of Shadow hosts the Shadowswift Brotherhood of rogues, the Darkfire Enclave of warlocks, and the scholars of the Arcane Enclave. Kept away from the everyday bustle of the valley districts, this dark quarter allows practitioners of poison, fel energy, and arcane magic to ply their trades out of direct public view while remaining under the watchful eye of Orgrimmar's leadership.",sp=0},{t="A Dangerous Threshold",b="Beyond acting as a center for covert instruction and magical reagents, the Cleft of Shadow descends directly into Ragefire Chasm. This fiery network of volcanic caves honeycombs beneath Orgrimmar itself, posing an ongoing security threat that draws adventurous defenders and sinister cultists alike right to the cavern's edge.",sp=0}},faq={{q="Why are warlocks and rogues kept underground here?",a="Thrall strives to keep the Horde united under honorable shamanic and warrior traditions. While the utility of warlocks and rogues is acknowledged, their practices are distrusted by much of the orcish public. Confining them to the subterranean caverns keeps dangerous fel and illicit activities contained and monitored.",al={"why cleft of shadow","why warlocks underground orgrimmar","cleft of shadow lore"}},{q="What major trainers and services can be found in the Cleft of Shadow?",a="The cavern serves as Orgrimmar's primary hub for rogue, warlock, and mage trainers. It also hosts poison suppliers, reagent vendors, and wand and staff merchants.",al={"trainers in cleft of shadow","who is in cleft of shadow"}},{q="What is the entrance at the bottom of the cavern?",a="The chasm plunging into the cavern floor leads to Ragefire Chasm, a perilous subterranean network of lava tubes beneath Orgrimmar infested with troggs, searing elementals, and rogue cultists.",al={"dungeon in cleft of shadow","cleft cave entrance","what instance is here"}}},ang={["class:Warlock"]="The Darkfire Enclave gives Horde warlocks a sanctioned place to summon demons and bind fel energy beneath Orgrimmar without drawing the immediate wrath of shaman and warriors.",["class:Rogue"]="The Shadowswift Brotherhood gathers here alongside poison merchants and lockpickers, turning this dark recess into the primary den for the Horde's stealth operatives."},kw={"arcane enclave","cleft of shadow","darkfire enclave","mage","orgrimmar","ragefire chasm","rogue","shadowswift brotherhood","warlock"},rel={"zone:orgrimmar","zone:ragefire","zone:blastedlands","subzone:valley-of-spirits"},src={"Cleft of Shadow"}}
E["subzone:drag"] = {t="subzone",n="Drag",z="orgrimmar",s="The Drag is a bustling, shaded thoroughfare carved into the red rock of Orgrimmar, linking the Valley of Strength to the Valley of Honor and the Valley of Wisdom. Known throughout Durotar as the heart of the capital's commerce, its canyon walls are lined with crafters, traders, and artisans. It also conceals the cavernous descent into the notorious Cleft of Shadow.",h="The Drag is a bustling, shaded thoroughfare carved into the red rock of Orgrimmar, linking the Valley of...",sec={{t="The Artisan's Thoroughfare",b="Tucked deep between the red canyon walls of Orgrimmar, the Drag serves as the commercial backbone of the Horde's capital. While the Valley of Strength focuses on military muster and administrative command, the Drag is where daily city life unfolds. Shaded under high cliffs and hides, the street is thick with the smells of tanning vats, bubbling alchemical cauldrons, and the clatter of tinkerers' gears. Craftsmen of almost every discipline gather here to practice their trades and teach aspiring adventurers, from leatherworking and tailoring to goblin-led engineering workshops like Nogg's Machine Shop.",sp=0},{t="A Crossroads of Shadows and Craft",b="Beyond housing merchant storefronts and salvage houses, the Drag occupies an uneasy position within Orgrimmar's social geography. Nestled along its canyon face lies the guarded entrance to the subterranean Cleft of Shadow. This makes the Drag an inescapable crossroads where honest tradesmen, shaman on their way to the Valley of Wisdom, and secretive practitioners of dark arts brush shoulders beneath the dim, dusty overhangs of the canyon.",sp=0}},faq={{q="What is the Drag used for in Orgrimmar?",a="The Drag is Orgrimmar's primary shopping and trade district. It hosts trainers and supply vendors for a wide array of professions, including alchemy, tailoring, leatherworking, skinning, enchanting, and engineering, alongside general salvage and trading goods.",al={"purpose of the drag","what is the drag","what shops are in the drag"}},{q="Where does the Drag lead?",a="The canyon street links the Valley of Strength in the south to the Valley of Honor in the northeast, with pathways also leading toward the Valley of Wisdom. Crucially, the entrance descending into the shadowy caverns of the Cleft of Shadow is located along the western cliffside of the Drag.",al={"drag connections","how to get to cleft of shadow","where does the drag go"}},{q="Who is Nogg?",a="Nogg is an enterprising goblin engineer who operates Nogg's Machine Shop along the Drag, serving as a prominent engineering trainer and gadget supplier for members of the Horde.",al={"noggs machine shop","who runs the machine shop"}},{q="Are all profession trainers located in the Drag?",a="Most crafting and gathering professions maintain shops along the lower and upper shelves of the Drag, but not all of them. Notably, the city's blacksmiths and miners prefer the fiery forges of the Valley of Honor, and first aid instruction is situated near the Orgrimmar Embassy.",al={"where are trainers in orgrimmar","first aid trainer drag"}}},ang={["profession:Engineering"]="The Drag is home to Nogg's Machine Shop, where goblin tinkerers impart schematics, explosives, and specialized engineering knowledge to the Horde.",["faction:Horde"]="Every traveler passing through the capital eventually treads the Drag, as it links Orgrimmar's martial core directly to the communal and mystical quarters."},kw={"alchemy","cleft of shadow","drag","leatherworking","nogg","orgrimmar","salvage","tailoring","the drag"},rel={"zone:orgrimmar","subzone:cleft-of-shadow","subzone:valley-of-strength","subzone:valley-of-honor","npc:nogg","subzone:orgrimmar-embassy"},src={"Drag"}}
E["subzone:gates-of-orgrimmar"] = {t="subzone",n="Gates of Orgrimmar",z="orgrimmar",s="The Gates of Orgrimmar form the imposing southern threshold of the Horde capital, carved directly into the red rock of northern Durotar. Flanked by heavy timber and iron battlements, this grand entryway connects the arid wastes outside to the busy commons of the Valley of Strength. It stands as a physical declaration of orcish endurance and martial strength.",h="The Gates of Orgrimmar form the imposing southern threshold of the Horde capital, carved directly into the...",sec={{t="The Bastion of Durotar",b="Framed by towering wooden palisades, massive iron spikes, and fortified watchtowers, the main gate guards the primary chasm cutting into the mountains sheltering Orgrimmar. For travelers approaching from Razor Hill and the scrublands of Durotar, the entrance serves as both a welcoming monument and a stark deterrent to any who would threaten the new Horde. Heavily armed Orgrimmar Grunts and Darkspear Headhunters patrol the approach, keeping vigilant watch over all traffic entering the city.",sp=0},{t="Threshold to the Valley",b="Passing beneath the shadowed arch of the gates leads directly into the Valley of Strength, the civic and martial heart of Orgrimmar. The gate tunnel acts as an acoustic and tactical bottleneck, funneling envoys, merchants, and warriors past watchful sentries. It represents the realization of Warchief Thrall's dream: a secure sanctuary carved from the harsh desert where the disparate peoples of the Horde can walk united without fear.",sp=0}},faq={{q="Where do the Gates of Orgrimmar lead?",a="The gates connect northern Durotar directly into the Valley of Strength, which serves as the primary entrance and central commons of Orgrimmar.",al={"what do the gates connect","where is the front gate"}},{q="Who guards the gates?",a="The front gates are guarded by seasoned Orgrimmar Grunts and Darkspear Headhunters, maintaining a constant vigil against hostile infiltrators and wild beasts.",al={"who protects the gate","gate guards"}},{q="Why is the entrance fortified with wood and spikes?",a="The architecture reflects traditional orcish frontier fortification, utilizing sturdy timber from nearby lands and iron spikes to create an intimidating, easily defensible choke point within the canyon walls.",al={"why wood and iron spikes","orcish gate design"}},{q="Can Alliance players pass through this gate?",a="Alliance members attempting to walk through the main gate will immediately face hostile veteran guards ready to strike down any enemy of the Horde on sight.",al={"can alliance enter","alliance walk through gate"}}},ang={["faction:Horde"]="The massive gates represent safety, belonging, and a hard-won homeland forged under the leadership of Warchief Thrall.",["faction:Alliance"]="For Alliance scouts and infiltrators, the gate is one of the most heavily guarded bottlenecks on Kalimdor, virtually impossible to breach by frontal assault."},kw={"durotar","gates of orgrimmar","main gate","orgrimmar grunts","thrall","valley of strength"},rel={"zone:orgrimmar","subzone:valley-of-strength","zone:durotar","topic:horde","npc:thrall","topic:alliance"},src={"Gates of Orgrimmar"}}
E["subzone:goblin-slums"] = {t="subzone",n="Goblin Slums",z="orgrimmar",s="In the current era of 25 ADP, the area that would later be associated with goblins does not exist as an independent settlement or slum. The southern canyon remains an open, natural section of the Valley of Spirits inhabited by the Darkspear trolls. Any notion of Bilgewater refugees or oily goblin slums belongs entirely to future eras.",h="In the current era of 25 ADP, the area that would later be associated with goblins does not exist as an...",sec={{t="Part of the Valley of Spirits",b="Presently in Orgrimmar, this southern reach is not separated from the Valley of Spirits. The Darkspear tribe occupies the surrounding plateaus and waterways, keeping the district steeped in ritual totems, shaded huts, and untamed waters. Goblins may pass through the Horde capital as neutral traders, engineers, or Zeppelineers serving the Steamwheedle Cartel, but they hold no sovereign district or permanent residential quarters within Orgrimmar's carved stone ramparts.",sp=0}},faq={{q="Where are the goblin slums in Orgrimmar?",a="There are no goblin slums in Orgrimmar. The southern portion of the city where such an enclave might be sought remains an undivided part of the Valley of Spirits, inhabited and maintained by the Darkspear trolls.",al={"goblin slums location","where is goblin slum","find goblin area"}},{q="Do goblins have their own district in Orgrimmar?",a="No. The goblins living and working across Durotar belong to independent trade cartels like the Steamwheedle Cartel. They operate neutral ventures such as zeppelins and engineering works, but do not possess a segregated neighborhood or residential quarter within the city.",al={"goblin quarter orgrimmar","do goblins live here"}},{q="Who lives in this section of the city right now?",a="The entire southern valley belongs to the Darkspear trolls. Witch doctors, shadow hunters, and troll tradesfolk live and practice their spiritual crafts throughout the water-carved ravines of the Valley of Spirits.",al={"who lives here","valley of spirits inhabitants"}}},ang={["race:Troll"]="The entire Valley of Spirits remains under Darkspear stewardship, free of noisy industrial drill sites or foreign enclaves.",["profession:Engineering"]="While goblin engineering instructors can be encountered operating across neutral settlements, Orgrimmar itself hosts no exclusive goblin workshop district."},kw={"bilgewater","darkspear","goblin district","goblin slums","orgrimmar","valley of spirits"},rel={"subzone:valley-of-spirits","zone:orgrimmar","topic:goblin","topic:troll","topic:horde"},src={"Goblin Slums"}}
E["subzone:grommash-hold"] = {t="subzone",n="Grommash Hold",z="orgrimmar",s="Grommash Hold is the fortified seat of Warchief Thrall, nestled high in the red cliffs of the Valley of Wisdom in Orgrimmar. Named in honor of Grommash Hellscream's sacrifice, the fortress serves as the command center and political heart of the new Horde.",h="Grommash Hold is the fortified seat of Warchief Thrall, nestled high in the red cliffs of the Valley of...",sec={{t="The Seat of the Warchief",b="Perched within the tranquil Valley of Wisdom, Grommash Hold serves as the royal court and strategic sanctum of the Horde. Built into the towering canyon walls, its thick stone interior remains notably dim and chilly—a deliberate choice by Warchief Thrall to keep emissaries, petitioners, and warlords sharp and sober during audiences. Here, Thrall deliberates on the defense of Kalimdor, guided by veteran counselors like Eitrigg and visited by racial chieftains such as Vol'jin.",sp=0},{t="The Monument to Freedom",b="Just outside the stronghold rests the shattered armor and horned skull of the pit lord Mannoroth, mounted upon the trunk of an ancient tree. Placed there to honor Grom Hellscream, who traded his life to slay the demon in Ashenvale, the memorial stands as both a proud symbol of the orcs' liberation from the demonic blood curse and a permanent, solemn warning against falling into reckless savagery again.",sp=0}},faq={{q="Who is inside Grommash Hold?",a="Warchief Thrall holds court here, alongside key Horde leaders and advisors including the orcish elder Eitrigg, the Darkspear leader Vol'jin, and the warrior Nazgrel.",al={"who is in the hold","who lives in grommash hold","who rules here"}},{q="Why is it named Grommash Hold?",a="It is named after Grommash 'Grom' Hellscream, the legendary chieftain of the Warsong clan. Grom struck down the pit lord Mannoroth during the Third War, paying with his life to permanently free the orcish race from demonic servitude.",al={"why grommash hold","who was grommash","named after who"}},{q="What are the giant bones displayed outside?",a="The skull and armor belong to Mannoroth, the demon lord whose blood initially enslaved the orcs on Draenor. The remains were hauled from Ashenvale and mounted on a tree trunk outside the hold as a monument to the Horde's freedom.",al={"demon skull outside","mannoroth skull","bones in front"}},{q="Why do some city signs call it Thrall's Fortress?",a="Many orcish guards and older directional signs still refer to the structure as Thrall's Fortress, after the warchief who holds court inside.",al={"thrall's fortress","thralls fortress","hold vs fortress"}}},ang={["faction:Horde"]="This is the very heart of the Horde's sovereignty, where treaties are forged and campaigns against threats across Kalimdor and the Eastern Kingdoms are directed.",["race:Orc"]="For orcs, the hold and Mannoroth's remains outside are the ultimate testament to their liberation from the demonic blood curse by the sacrifice of Grom Hellscream."},kw={"eitrigg","grommash hold","mannoroth","orgrimmar","thrall","thrall's fortress","valley of wisdom"},rel={"npc:thrall","topic:grommash-hellscream","zone:orgrimmar","npc:vol-jin","npc:eitrigg","topic:burning-legion","topic:third-war"},src={"Grommash Hold"}}
E["subzone:hall-of-legends"] = {t="subzone",n="Hall of Legends",z="orgrimmar",s="The Hall of Legends is the elite military sanctuary and officer barracks of the Horde, nestled within Orgrimmar's Valley of Strength. Behind its warded threshold, champions of the Horde gather around battle plans and arm themselves with premier weapons taken from conflicts across Azeroth and beyond.",h="The Hall of Legends is the elite military sanctuary and officer barracks of the Horde, nestled within...",sec={{t="Sanctuary of Horde Champions",b="Located off the bustling avenues of the Valley of Strength, the Hall of Legends serves as the private redoubt for proven officers of the Horde. Beyond its guarded entrance, strategists and delegates from across the factions—including Chieftain Earthbind of Thunder Bluff, Blood Guard Hini'wana of the Darkspear, and Advisor Willington of the Undercity—confer over maps of contested lands and the military standing of both factions. Here, only warriors who have tested their mettle and achieved the rank of Stone Guard or higher are permitted entry to claim the spoils and armaments befitting their status.",sp=0},{t="The Spoils of War",b="More than just an officer lounge, the hall houses armories containing battle-tested wargear from across Azeroth and the orcs' shattered homeworld of Draenor. Many of these weapons were claimed as spoils from the ongoing clashes against the Alliance and other adversaries. For those climbing the martial ranks, it represents the physical manifestation of Horde honor, martial prowess, and hard-won victory.",sp=0}},faq={{q="Who is allowed inside the Hall of Legends?",a="Only Horde champions who have achieved the rank of Stone Guard (Rank 6) or higher in the military honor system are granted passage through its threshold. Lower-ranking soldiers and ordinary citizens are turned away at the entrance.",al={"can i enter hall of legends","hall of legends requirement","rank required for hall of legends"}},{q="Where is the Hall of Legends located?",a="The Hall of Legends is situated in the Valley of Strength in Orgrimmar, near the city's primary barracks and administrative seat.",al={"where is hall of legends","hall of legends location","how to get to hall of legends"}},{q="What is inside the Hall of Legends?",a="Inside lies a central strategy table flanked by military representatives of the Horde's various races, surrounded by maps of Azeroth and military records. Quartermasters also maintain armories here, distributing prestigious arms, armor, and mounts to accomplished officers.",al={"what is in hall of legends","hall of legends interior"}},{q="Does the Alliance have an equivalent location?",a="Yes. The Alliance counterpart is the Champions' Hall, situated in the Old Town district of Stormwind City, which similarly serves as an officer barracks and armory for honored Alliance combatants.",al={"alliance hall of legends","alliance counterpart"}}},ang={["faction:Horde"]="The Hall of Legends is the ultimate testament to Horde military achievement, offering recognition, strategic council, and prized wargear to those who shed blood for the Warchief.",["class:Warrior"]="For front-line fighters, gaining entry to the Hall of Legends represents the pinnacle of martial respect, granting access to weapons forged in conflicts across multiple worlds."},kw={"hall of legends","officer barracks","orgrimmar","pvp","spoils of war","stone guard","valley of strength"},rel={"subzone:valley-of-strength","zone:orgrimmar","subzone:champions-hall","topic:horde","zone:thunderbluff","zone:undercity","topic:troll","zone:stormwind"},src={"Hall of Legends"}}
E["subzone:hall-of-the-brave"] = {t="subzone",n="Hall of the Brave",z="orgrimmar",s="The Hall of the Brave is the grand warrior barracks situated in the eastern heights of Orgrimmar's Valley of Honor. It serves as the primary training compound and guild house for the Horde's front-line combatants, drillmasters, and battlemasters.",h="The Hall of the Brave is the grand warrior barracks situated in the eastern heights of Orgrimmar's Valley of...",sec={{t="The Warriors' Bastion",b="Overlooking the tranquil waters and training rings of the Valley of Honor, the Hall of the Brave serves as a vital military hub for the burgeoning Horde. Inside, veteran officers and seasoned warriors instruct initiates in the brutal fundamentals of melee combat, stance mastery, and discipline. The hall is lined with training dummies and armaments, housing battlemasters who organize combatants for major military engagements across Azeroth.",sp=0}},faq={{q="What is the purpose of the Hall of the Brave?",a="It serves as the main barracks and guild hall for warriors in Orgrimmar. Here, warriors learn their techniques from veteran trainers, hone their strikes on practice dummies, and consult battlemasters regarding military deployments across contested lands.",al={"what is hall of the brave","what is this building","hall of the brave purpose"}},{q="Where in Orgrimmar is the hall located?",a="The Hall of the Brave is situated on the eastern side of the Valley of Honor, nestled along the red canyon walls overlooking the valley's central pond.",al={"where is hall of the brave","hall of the brave location","find warrior trainer orgrimmar"}},{q="Who can be found inside the hall?",a="The hall houses various warrior class trainers, battlemasters coordinating large-scale conflicts, and Horde grunts resting between active patrols.",al={"who is in hall of the brave","hall of the brave npcs"}}},ang={["class:Warrior"]="The Hall of the Brave is your martial home in the capital, housing trainers who unlock advanced stances and battle maneuvers as your prowess grows.",["faction:Horde"]="This barracks stands as a living demonstration of the Horde's frontline discipline, housing battlemasters who muster troops to fight across the continent."},kw={"barracks","battlemaster","hall of the brave","orgrimmar","valley of honor","warrior trainer","warriors guild"},rel={"subzone:valley-of-honor","zone:orgrimmar","subzone:hall-of-legends","topic:horde"},src={"Hall of the Brave"}}
E["subzone:orgrimmar-embassy"] = {t="subzone",n="Orgrimmar Embassy",z="orgrimmar",s="In the current era of 25 ADP, no formal Orgrimmar Embassy exists within the red canyon walls of Durotar. The craggy district west of the Valley of Strength is currently undeveloped canyon terrain rather than a hall of diplomacy. Thrall instead conducts all statecraft and hosts emissaries directly inside Grommash Hold in the Valley of Wisdom.",h="In the current era of 25 ADP, no formal Orgrimmar Embassy exists within the red canyon walls of Durotar.",sec={{t="Diplomacy in the Red City",b="Travelers seeking a designated embassy district in Orgrimmar will find only barren red rock and quiet bluffs above the city's thoroughfares. In this early age following the Third War, the Horde maintains no detached diplomatic bureau or sprawling embassy quarter. Warchief Thrall coordinates the fragile confederation of orcs, Darkspear trolls, and tauren directly from Grommash Hold in the Valley of Wisdom. Messengers, envoys from the Undercity, and visiting chieftains bring their petitions straight to the Warchief's throne rather than congregating in an external consulate.",sp=0}},faq={{q="Where is the Orgrimmar Embassy?",a="It does not exist in 25 ADP. The area west of the Valley of Strength where later legends speak of an embassy is simply unoccupied canyon land and hills overlooking the main valley.",al={"embassy location","find orgrimmar embassy","where is embassy"}},{q="Where do foreign envoys and emissaries meet Horde leaders right now?",a="All major diplomacy and high-level council meetings occur in Grommash Hold, situated in the Valley of Wisdom. Thrall and his advisors host visiting emissaries, such as representatives from the Forsaken, directly within the stronghold.",al={"where are horde leaders","where to find thrall","diplomacy in orgrimmar"}},{q="Why would someone look for an embassy in Orgrimmar?",a="Rumors from other lands or eras describe an assembly hall dedicated to gathering allied factions and overseas representatives. However, the fledgling Horde in Durotar functions as a tight, unified frontier force ruled directly by the Warchief rather than an expansive diplomatic council.",al={"what is the embassy","why look for embassy"}}},ang={["faction:Horde"]="All internal Horde politics flow directly through Warchief Thrall in the Valley of Wisdom rather than any secondary civic building."},kw={"durotar","embassy","grommash hold","orgrimmar","thrall","valley of strength"},rel={"zone:orgrimmar","npc:thrall","subzone:valley-of-strength","topic:horde"},src={"Orgrimmar Embassy"}}
E["subzone:ragefire-chasm"] = {t="subzone",n="Ragefire Chasm",z="orgrimmar",s="Ragefire Chasm is a network of volcanic caverns situated directly beneath the Horde capital of Orgrimmar. Accessible through the Cleft of Shadow, its magma-lit tunnels harbor feral troggs and a hidden sect of the Shadow Council bent on unraveling the young orcish nation from within.",h="Ragefire Chasm is a network of volcanic caverns situated directly beneath the Horde capital of Orgrimmar.",sec={{t="A Threat Beneath the Streets",b="While Thrall works to secure Durotar above, subterranean dangers fester directly beneath Orgrimmar's foundation. Ragefire Chasm is an unstable network of volcanic vents and magma rivers that has become infested with savage Ragefire troggs. Rising from unknown depths below the tunnels, these hostile creatures violently rebuffed diplomatic overtures made by Magatha Grimtotem. Left unchecked, their sheer numbers threaten to undermine and overrun the capital.",sp=0},{t="The Searing Blade",b="Far more dangerous than the troggs is the Searing Blade, an insurgent sect of the demonic Shadow Council operating from the shadows of the chasm. Directed by the warlock Jergosh the Invoker, the satyr Bazzalan, and a towering felguard known as Taragaman the Hungerer, these cultists plot the ruin of Thrall's Horde. Though Neeru Fireblade claims to oppose them, the cult works actively to test their forces and sabotage the orcs' new home from below.",sp=1}},faq={{q="Where is the entrance to Ragefire Chasm?",a="The entrance is located deep inside Orgrimmar within the Cleft of Shadow, right next to the tent of the warlock Neeru Fireblade.",al={"rfc entrance","how to get to ragefire chasm","where is ragefire chasm located"}},{q="Who lives inside Ragefire Chasm?",a="The chasm is infested with aggressive Ragefire troggs and occupied by the Searing Blade, a cult linked to the Shadow Council. They are led by the warlock Jergosh the Invoker, the satyr Bazzalan, and the felguard Taragaman the Hungerer.",al={"ragefire mobs","what enemies are in rfc","who controls ragefire chasm"}},{q="Why hasn't Thrall cleared out the chasm?",a="The Horde is stretched thin establishing Durotar and defending against external threats. Warchief Thrall relies on capable champions to delve into the caverns, eliminate the Searing Blade leadership, and cull the trogg population before they can breach the city streets.",al={"why does thrall allow ragefire","thrall ragefire chasm"}},{q="Can Alliance players enter Ragefire Chasm?",a="Yes, but reaching it requires sneaking through the gates of Orgrimmar and descending into the heavily guarded Cleft of Shadow, making it an exceptionally perilous undertaking for Alliance adventurers.",al={"can alliance do rfc","alliance in ragefire"}}},ang={["faction:Horde"]="Ragefire Chasm represents a glaring security crisis at the very heart of the capital, testing young adventurers' dedication to protecting the nascent Horde.",["class:Warlock"]="The presence of the Searing Blade and their demonic masters demonstrates the lingering corruption of fel magic that Thrall's new Horde actively seeks to root out."},kw={"bazzalan","cleft of shadow","jergosh the invoker","orgrimmar","ragefire chasm","rfc","searing blade","taragaman","troggs"},rel={"zone:ragefire","subzone:cleft-of-shadow","zone:orgrimmar","npc:taragaman-the-hungerer","npc:jergosh-the-invoker","npc:bazzalan","quest:829","quest:5726"},src={"Ragefire Chasm"}}
E["subzone:ragefire-chasm-classic"] = {t="subzone",n="Ragefire Chasm (Classic)",z="orgrimmar",s="Ragefire Chasm is a sprawling network of volcanic tunnels carved directly beneath Orgrimmar, accessible through the shadowy depths of the Cleft of Shadow. Despite being situated under the Horde's sovereign capital, these fiery caverns crawl with hostile troggs and a subversive coven of cultists loyal to the Shadow Council.",h="Ragefire Chasm is a sprawling network of volcanic tunnels carved directly beneath Orgrimmar, accessible...",sec={{t="A Hidden Peril",b="Beneath the stone streets and fortified towers of Orgrimmar lies Ragefire Chasm, a treacherous network of magma-filled subterranean caverns. The tunnels recently became overrun by the savage Ragefire troggs, who pushed upward from deep subterranean fissures. Magatha Grimtotem of the tauren attempted peaceful diplomacy with the creatures, but her overtures were violently rejected. Left unchecked, the troggs threaten to tunnel further into the foundations of the city itself.",sp=0},{t="The Searing Blade",b="Far more dangerous than mindless troggs is the presence of the Searing Blade, an insurgent cult subordinate to the demonic Shadow Council. Led by the hulking felguard Taragaman the Hungerer, the orc warlock Jergosh the Invoker, and the corrupt satyr Bazzalan, these conspirators scheme to unravel everything Thrall's Horde has established in Durotar. Rather than immediately cleansing the caves, Warchief Thrall has maintained surveillance on their activities, hoping their foolish overconfidence will expose their masters higher up in the Shadow Council's hierarchy.",sp=1}},faq={{q="Where is the entrance to Ragefire Chasm?",a="The entrance portal is located deep within Orgrimmar, specifically in the subterranean canyon known as the Cleft of Shadow. It sits near the tent of the orc warlock Neeru Fireblade.",al={"where is ragefire","rfc entrance","how to get to rfc","where is rfc located"}},{q="Why are there troggs beneath Orgrimmar?",a="The troggs surfaced from ancient, deep cavern systems beneath Durotar, emerging directly into the volcanic underbelly of the city. Their sudden invasion poses a structural and physical hazard to the capital, refusing any attempts at peaceful containment.",al={"why are troggs here","ragefire troggs","orgrimmar troggs"}},{q="Why does Thrall allow cultists to live under the capital?",a="Warchief Thrall is fully aware of the cult's presence beneath the city. Rather than launching a blunt assault that might cause the wider network to scatter, he allows them to operate under close watch in hopes they will inadvertently reveal the identity and whereabouts of the Shadow Council's true leadership.",al={"why doesn't thrall clear rfc","thrall shadow council","why is searing blade under orgrimmar"}},{q="Who leads the cultists inside the chasm?",a="The Searing Blade inside Ragefire Chasm is commanded by three figures: Taragaman the Hungerer, a formidable felguard; Jergosh the Invoker, an orc warlock; and Bazzalan, a treacherous satyr.",al={"rfc bosses","who leads the searing blade","ragefire chasm leaders"}}},ang={["faction:Horde"]="Clearing Ragefire Chasm is a matter of homeland defense, securing the bedrock of Durotar against internal sabotage while rooting out demonic collaborators.",["race:Tauren"]="Elder Crone Magatha Grimtotem sent emissaries to sue for peace with the invading troggs; their bloody refusal proved diplomacy is impossible against these underground beasts."},kw={"bazzalan","cleft of shadow","jergosh","ragefire chasm","rfc","searing blade","taragaman","troggs"},rel={"zone:orgrimmar","subzone:cleft-of-shadow","npc:thrall","topic:shadow-council","npc:taragaman-the-hungerer","npc:jergosh-the-invoker","npc:bazzalan","quest:829"},src={"Ragefire Chasm (Classic)"}}
E["subzone:valley-of-honor"] = {t="subzone",n="Valley of Honor",z="orgrimmar",s="The Valley of Honor serves as the martial core and warrior district of Orgrimmar, nestled in the northeastern canyons of the capital. It houses the city's barracks, warrior and hunter guilds, and the battlemasters directing Horde forces across Azeroth. With active forges, training rings, and quiet waters, it is where the Horde hones its strength and remembers its martial heritage.",h="The Valley of Honor serves as the martial core and warrior district of Orgrimmar, nestled in the northeastern...",sec={{t="Heart of the Horde's Might",b="Situated behind high canyon ridges, the Valley of Honor acts as Orgrimmar's primary military quarter. Here, the clatter of practice weaponry and the ringing of blacksmith anvils define daily life. The Hall of the Brave dominates the valley, serving as a gathering point for seasoned warriors and battlemasters coordinating campaigns across battlefronts like Alterac Valley and Warsong Gulch. Flanked by training facilities for beastmasters and hunters, the district is dedicated entirely to equipping, drilling, and mobilizing the Horde's frontline defenders.",sp=0},{t="Craft, Trade, and Respite",b="Beyond arms and drill grounds, the valley supports the logistics of war. The Burning Anvil and Red Canyon Mining supply armor and raw iron, while engineers tinker nearby in Nogg's Machine Shop. Between duties, grunts and visiting adventurers frequent The Wyvern's Tail tavern or cast a line into the valley's surprisingly serene central lake, offering brief moments of calm away from the dusty bustle of the Valley of Strength.",sp=0}},faq={{q="What is the purpose of the Valley of Honor?",a="It is the military and martial hub of Orgrimmar. It contains the city's barracks, warrior and hunter trainers, weaponsmiths, and the battlemasters responsible for dispatching soldiers to major battlefronts.",al={"valley of honor purpose","what is here","what's in valley of honor"}},{q="Where can I find battlemasters in Orgrimmar?",a="The Horde battlemasters are stationed inside the Hall of the Brave, located in the Valley of Honor. From there, soldiers are enlisted and dispatched to ongoing engagements across Azeroth.",al={"battlemaster location","orgrimmar pvp","queue bg orgrimmar"}},{q="What professions are trained in the Valley of Honor?",a="The valley is home to trainers and supply vendors for blacksmithing, mining, and fishing, along with goblin engineering specialists operating out of Nogg's Machine Shop.",al={"professions valley of honor","trainers here","blacksmithing orgrimmar"}},{q="What is The Wyvern's Tail?",a="The Wyvern's Tail is the local tavern and inn situated along the edge of the valley, providing food, drink, and rest for weary warriors, hunters, and travelers.",al={"wyverns tail","inn in valley of honor","valley of honor tavern"}}},ang={["class:Warrior"]="The Valley of Honor is your spiritual home in Orgrimmar, housing the Hall of the Brave, veteran combat instructors, and the armorers who forge the Horde's front lines.",["class:Hunter"]="The Hunter's Hall and beast-taming grounds make this valley an essential stop for replenishing ammunition, honing marksmanship, and stabling companions."},kw={"barracks","battlemasters","blacksmithing","hall of the brave","nogg","orgrimmar","the wyvern's tail","valley of honor"},rel={"zone:orgrimmar","subzone:hall-of-the-brave","npc:nogg","topic:horde"},src={"Valley of Honor"}}
E["subzone:valley-of-spirits"] = {t="subzone",n="Valley of Spirits",z="orgrimmar",s="Tucked against the western cliffs of Orgrimmar, the Valley of Spirits serves as the long-standing seat of the Darkspear tribe within the Horde's capital. Filled with thatched lodges, tiki poles, and serene pools, it offers a stark contrast to the surrounding red stone and iron-clad orcish architecture.",h="Tucked against the western cliffs of Orgrimmar, the Valley of Spirits serves as the long-standing seat of the...",sec={{t="A Home for the Darkspear",b="Branching westward off the bustling Valley of Strength, the Valley of Spirits is a lush and quiet enclave dedicated to the Darkspear trolls. When the tribe settled in Durotar alongside Thrall's orcs, this tranquil pocket among the crags became their urban gathering place. Trollish craftspeople, spiritualists, and practitioners gather around its wooden bridges and winding waters, practicing their arts away from the dry heat of the main thoroughfares.",sp=0},{t="Keepers of the Craft",b="Beyond its dwellings and tranquil pools, the valley hosts practitioners of magic and wild crafts. Witch doctors, herbalists, and spellcasters congregate in lodges like the Spirit Lodge and Darkbriar Lodge. Tucked toward the back is the Talon Gate, which opens directly toward the open plains of the Barrens, offering quick passage for wanderers, hunters, and travelers roaming beyond the canyon walls.",sp=0}},faq={{q="Who lives in the Valley of Spirits?",a="The valley is primarily home to the Darkspear trolls who settled in Durotar alongside the orcs. You will find their craftsmen, spiritual leaders, herbalists, and hunters here, living among distinct troll-style huts and carved tiki totems.",al={"who lives here","valley of spirits inhabitants","trolls in orgrimmar"}},{q="Where does the Talon Gate lead?",a="The Talon Gate sits at the rear of the Valley of Spirits, functioning as the western exit of Orgrimmar. Passing through it leads directly into the Southfury River basin and the plains of the Barrens.",al={"talon gate exit","back gate orgrimmar","valley of spirits gate"}},{q="What services and trainers are found here?",a="The Valley of Spirits features trainers and merchants for herbalism, cooking, and various wilderness and magical disciplines, housed across notable structures such as the Spirit Lodge and Darkbriar Lodge.",al={"trainers in valley of spirits","what is in valley of spirits"}}},ang={["race:Troll"]="For the Darkspear tribe, this peaceful enclave provides a crucial piece of home and cultural identity within the towering red canyons of the orcish capital.",["profession:Herbalism"]="The quiet waterways and specialized lodges in the valley make it a prime hub in the city for gathering wisdom from local herbalist masters."},kw={"darkbriar lodge","darkspear","orgrimmar","spirit lodge","talon gate","trolls","valley of spirits"},rel={"zone:orgrimmar","subzone:valley-of-strength","topic:troll","topic:horde","npc:thrall"},src={"Valley of Spirits"}}
E["subzone:valley-of-strength"] = {t="subzone",n="Valley of Strength",z="orgrimmar",s="The Valley of Strength is the bustling central commons of Orgrimmar, greeting all who pass through the city's towering front gates. Housing the city bank, the central auction house, and the Broken Tusk inn, it serves as the beating commercial and administrative heart of the Horde capital.",h="The Valley of Strength is the bustling central commons of Orgrimmar, greeting all who pass through the city's...",sec={{t="The Gates of the City",b="Step past the fortified timber gates of Orgrimmar and you enter the Valley of Strength. Carved deep into the red canyon rock of Durotar, this valley serves as the Horde's front square. Adventurers, merchants, and warriors from all allied nations mingle across its dusty plazas, swapping war stories over flagons from the Broken Tusk inn or attending to vital trade at the central bank and auction house. It is a bustling testament to the strength and unity the orcs fought to establish in their new homeland.",sp=0},{t="Hub of Trade and Command",b="Beyond its defensive significance, the valley functions as the capital's foremost marketplace. Armories such as Naros' provide blacksmithing anvils and raw ore, while various vendors supply provisions for long treks across the Barrens. Grunts stand vigilant watch at every corner, directing newcomers and ensuring order among the diverse peoples who have taken refuge beneath Thrall's banner.",sp=0}},faq={{q="What is the Valley of Strength?",a="It is the primary entryway and central valley of Orgrimmar, located just inside the city's main gates. It contains essential urban services such as the bank, auction house, general goods merchants, and the Broken Tusk inn.",al={"valley of strength overview","what is this place","orgrimmar entrance area"}},{q="Where is Grommash Hold located relative to this valley?",a="Grommash Hold is not in the Valley of Strength; it stands to the north in the Valley of Wisdom, serving as the seat of Warchief Thrall and the Horde's high command.",al={"where is thrall","grommash hold location","warchief seat"}},{q="What services can I find here?",a="The valley houses the city's primary bank, the auction house, trade supplies, blacksmithing and mining trainers at Naros' Armory, lodging at the Broken Tusk, and general trade goods.",al={"valley of strength amenities","vendors valley of strength","what's here"}},{q="Who guards the Valley of Strength?",a="The valley is heavily patrolled by Orgrimmar Grunts, seasoned orc warriors who maintain peace, protect incoming caravans, and direct travelers through the labyrinthine canyon city.",al={"orgrimmar grunts","guards in valley of strength","city defense"}}},ang={["faction:Horde"]="As the primary plaza inside Orgrimmar's gates, the Valley of Strength is the first place Horde travelers meet to trade, recruit for expeditions, and pay respects before the seat of the Warchief.",["profession:Blacksmithing"]="Naros' Armory in the valley provides anvils, forges, and skilled training for smiths outfitting the warriors of the Horde."},kw={"auction house","bank","broken tusk","durotar","grommash hold","horde","orgrimmar","thrall","valley of strength"},rel={"zone:orgrimmar","subzone:grommash-hold","subzone:broken-tusk","topic:horde"},src={"Valley of Strength"}}
E["zone:orgrimmar"] = {t="city",n="Orgrimmar",z="orgrimmar",s="Orgrimmar is the fortress capital of the orcs and the beating heart of Thrall's New Horde. Carved directly into the towering red-rock canyons of northern Durotar, the fortified city stands as a monument to orcish perseverance and an unyielding sanctuary for trolls, tauren, and Forsaken allies alike.",h="Orgrimmar is the fortress capital of the orcs and the beating heart of Thrall's New Horde.",sec={{t="A Home Chiseled from Stone",b="Following the Third War, Warchief Thrall led the orcs to the arid coasts of Kalimdor to build a homeland free from demonic corruption and human bondage. Naming the harsh region Durotar after his father, Thrall established Orgrimmar in memory of his fallen mentor, Orgrim Doomhammer. Raising the city required blood and sweat; aided by the tauren, the Darkspear trolls, goblin engineers, and the Champion Rexxar, the Horde drove back encroaching centaur, harpies, and ferocious thunder lizards to secure the canyon stronghold.",sp=0},{t="Valleys of the Horde",b="Orgrimmar is naturally fortified by rugged mountains that shield it from both foreign invaders and the violent razor-winds sweeping through Durotar. The settlement is partitioned into distinct natural hollows. The Valley of Strength serves as the bustling civic gatehouse, leading deeper into the trade bazaar of The Drag. Tauren druids and shaman congregate in the serene pools of the Valley of Wisdom, while Darkspear shadow hunters and witch doctors dwell among the stilted pavilions of the Valley of Spirits.",sp=0},{t="Shadows in the Red Rock",b="Beneath the martial pride of the Valley of Honor and the heights of Grommash Hold lies a dimmer reality. In the subterranean cavern known as the Cleft of Shadow, warlocks and rogues practice arts Thrall strictly watches yet grudgingly tolerates. Deeper still plunges Ragefire Chasm, a fiery labyrinth of volcanic tunnels beneath the canyon floor where dark cultists and subterranean beasts fester, threatening the fortress from directly within its own foundations.",sp=1}},faq={{q="Who rules Orgrimmar?",a="Warchief Thrall rules the city from his seat in Grommash Hold. He leads the New Horde with a focus on honor, survival, and shamanistic heritage, supported closely by Darkspear chieftain Vol'jin and veteran commander Varok Saurfang.",al={"orgrimmar leader","who is in charge of orgrimmar","current warchief"}},{q="Why is the city named Orgrimmar?",a="Thrall named the city in honor of Orgrim Doomhammer, the legendary former Warchief who broke the shadow council's hold on the Old Horde and passed his warplate and the Doomhammer to Thrall before dying in battle.",al={"orgrimmar name origin","who is orgrimmar named after"}},{q="Who lives in Orgrimmar besides orcs?",a="While founded by orcs, the city is a haven for the Darkspear troll tribe—who occupy the Valley of Spirits—and hosts visiting tauren ambassadors in the Valley of Wisdom. An emissary contingent of Forsaken has also established a presence following their recent entry into the Horde.",al={"races in orgrimmar","who lives here","trolls in orgrimmar"}},{q="What is the Cleft of Shadow?",a="The Cleft of Shadow is a dim, cavernous fissure tucked beneath the canyon bluffs off The Drag. It houses the city's rogue and warlock guilds, keeping their illicit trade and dangerous demonic invocations secluded from the civilian districts.",al={"cleft of shadow","underground orgrimmar","orgrimmar warlock area"}},{q="What threats exist inside the city?",a="Directly below the Cleft of Shadow lies Ragefire Chasm, a treacherous network of subterranean volcanic fissures infested with troggs, searing elementals, and treacherous warlocks seeking to undermine Thrall's rule from the depths.",al={"dangers in orgrimmar","ragefire chasm threat","orgrimmar cultists"}},{q="How do you travel to other continents from Orgrimmar?",a="Goblin-engineered zeppelins dock atop towers outside the main gate, providing regular flights across the Great Sea to Tirisfal Glades near Undercity and south to Grom'gol Base Camp in Stranglethorn Vale.",al={"orgrimmar zeppelins","getting to tirisfal from orgrimmar","travel from orgrimmar"}}},ang={["faction:Horde"]="As the supreme military and cultural seat of the New Horde, Orgrimmar provides all Horde champions with essential weaponmasters, class mentors, trade hubs, and direct audience with Warchief Thrall.",["race:Orc"]="For the orcs, Orgrimmar represents hard-won freedom from demonic lethargy and internment, serving as their proud ancestral fortress on the soil of Durotar.",["race:Troll"]="Having lost the Darkspear Isles, the Darkspear trolls found enduring sanctuary alongside the orcs, claiming the Valley of Spirits as a secure spiritual home.",["class:Shaman"]="Thrall has restored shamanism to the core of Horde leadership; practitioners gather within the tranquil Valley of Wisdom to study the elements and commune with ancestral spirits.",["class:Warlock"]="Warlocks find an uneasy refuge here: banished to the secluded Cleft of Shadow, they operate under Thrall's watchful eye while honing their dark arts away from open judgment."},kw={"cleft of shadow","drag","durotar","grommash hold","orgrim doomhammer","orgrimmar","ragefire chasm","thrall","valley of spirits","valley of strength","valley of wisdom","warchief"},rel={"npc:thrall","npc:orgrim-doomhammer","zone:durotar","zone:ragefire","subzone:grommash-hold","subzone:cleft-of-shadow","topic:new-horde","npc:vol-jin"},src={"Orgrimmar"}}
